class RecordingCheckTest(unittest.TestCase):
    """録音の確かめ（make_ack_clips）：声の途中で切れた録音・文の途中の長い無音を落とす。"""

    RATE = 24000

    def tone(self, *parts):
        """(秒, 声か) の並びから、作った音を作る。"""
        import numpy as np
        out = []
        for sec, on in parts:
            t = np.arange(int(self.RATE * sec)) / self.RATE
            out.append(np.sin(2 * np.pi * 160 * t) * (0.3 if on else 0.0))
        return (np.concatenate(out) * 32767).astype("<i2").tobytes()

    def test_cut_in_the_middle_of_the_voice_is_rejected(self):
        """⛔ 2026-10-15：S4 の「承知しました、」の候補3は声の途中で終わっていたのに、耳の確かめは通した（ユーザーが聞いて気づいた）。"""
        from make_ack_clips import ends_in_silence
        self.assertFalse(ends_in_silence(self.tone((0.2, False), (0.6, True)), self.RATE))
        self.assertFalse(ends_in_silence(self.tone((0.2, False), (0.6, True), (0.05, False)), self.RATE))
        self.assertTrue(ends_in_silence(self.tone((0.2, False), (0.6, True), (0.25, False)), self.RATE))

    def test_long_pause_only_at_sentence_end(self):
        from make_ack_clips import long_pauses_ok
        one_sentence = self.tone((0.1, False), (0.8, True), (0.35, False), (0.8, True), (0.2, False))
        self.assertFalse(long_pauses_ok("お忙しいところお時間をいただきましてありがとうございました。", one_sentence, self.RATE))
        self.assertTrue(long_pauses_ok("ありがとうございました。それでは失礼いたします。", one_sentence, self.RATE))
        lead = self.tone((0.1, False), (0.8, True), (0.30, False), (0.8, True), (0.2, False))  # つなぎの言葉のあとの間（上限 0.32秒の内側）
        self.assertTrue(long_pauses_ok("それではご希望の日時をお聞かせいただけますでしょうか？", lead, self.RATE))  # 頭のつなぎの言葉のあと

    def test_pause_after_lead_word_has_a_limit(self):
        """✅ 2026-10-16 ユーザー：「それではの後も少しだけ間が長い」（0.38秒）。「続きまして」のあとの 0.30秒は指摘なし。"""
        from make_ack_clips import long_pauses_ok
        text = "それではご希望の日時をお聞かせいただけますでしょうか？"
        long_lead = self.tone((0.1, False), (0.6, True), (0.38, False), (1.5, True), (0.2, False))
        ok_lead = self.tone((0.1, False), (0.6, True), (0.30, False), (1.5, True), (0.2, False))
        self.assertFalse(long_pauses_ok(text, long_lead, self.RATE))
        self.assertTrue(long_pauses_ok(text, ok_lead, self.RATE))

    def test_cut_after_context_keeps_only_the_second_sentence(self):
        """前置き「かしこまりました。」のあとの文の切れ目で切り、後ろだけを残す（声の頭の前に少し無音を残す）。切れ目が無ければ使わない。"""
        from make_ack_clips import CUT_KEEP_S, cut_after_context
        from barge import voice_runs, voiced
        pcm = self.tone((0.1, False), (0.7, True), (0.4, False), (1.5, True), (0.3, False))
        kept = cut_after_context(pcm, self.RATE)
        runs = voice_runs(voiced(kept, self.RATE), 0.05)
        self.assertEqual(len(runs), 1)                                    # 前置きの文は残らない
        self.assertAlmostEqual(runs[0][0], CUT_KEEP_S, delta=0.02)        # 声の頭は切らない
        self.assertAlmostEqual(runs[0][1] - runs[0][0], 1.5, delta=0.05)  # 後ろの文はそのまま
        self.assertIsNone(cut_after_context(self.tone((0.1, False), (2.0, True), (0.3, False)), self.RATE))

    def test_short_comma_like_pause_is_rejected(self):
        """⛔ 2026-10-15：締めの候補は、文の途中の 0.12〜0.24秒の無音で「、」が入った言い方に聞こえた（ユーザー）。0.08秒は聞こえなかった。"""
        from make_ack_clips import long_pauses_ok
        text = "お忙しいところお時間をいただきましてありがとうございました。"
        with_comma = self.tone((0.1, False), (0.8, True), (0.16, False), (0.8, True), (0.2, False))
        smooth = self.tone((0.1, False), (0.8, True), (0.08, False), (0.8, True), (0.2, False))
        self.assertFalse(long_pauses_ok(text, with_comma, self.RATE))
        self.assertTrue(long_pauses_ok(text, smooth, self.RATE))


class JudgeSetupTest(unittest.TestCase):
    """Google 以外の判定（meaning_judge.OTHER_JUDGES）と、ユーザーが貼る文字（docs/JUDGE_SETUP.md）。つながずに確かめる。"""

    DOC = Path(__file__).resolve().parent.parent / "docs" / "JUDGE_SETUP.md"

    def blocks(self) -> list[str]:
        lines, inside = [], False
        for line in self.DOC.read_text(encoding="utf-8").splitlines():
            if line.startswith("```"):
                inside = not inside
            elif inside and line.strip():
                lines.append(line.strip())
        return lines

    def q(self):
        from g53_meaning import g48_questions
        return next(q for q in g48_questions() if q.id == "G17")

    def test_spend_is_counted_saved_and_capped(self):
        # 有料の判定（Anthropic）の料金の帳簿（meaning_judge.SPEND）：返事の使った量から円を数え、結果の記録に入れ、試しの上限を超えたら
        # 送らない（判定は止まった扱い）。⛔ 2026-10-28 ユーザー：「ここまでで3万円以上使用しているということですよ。無駄遣いや…」
        import asyncio
        import json
        import tempfile
        from types import SimpleNamespace
        import common
        import meaning_judge as mj

        sent = []

        class Messages:
            def create(self, **body):
                sent.append(body["model"])
                return SimpleNamespace(usage=SimpleNamespace(input_tokens=1670, output_tokens=40, cache_read_input_tokens=0,
                                                             cache_creation_input_tokens=0))

        class AioMessages:
            async def create(self, **body):
                return Messages().create(**body)
        old, mj.SPEND = mj.SPEND, mj.Spend()
        try:
            c = mj._Metered(SimpleNamespace(messages=Messages()), aio=False)
            c.messages.create(model="claude-sonnet-5-5", messages=[])
            # 1回＝入力 1,670×2ドル＋出力 40×10ドル（100万トークンあたり）＝0.00374ドル＝約0.56円
            self.assertAlmostEqual(mj.SPEND.yen, (1670 * 2.0 + 40 * 10.0) / 1e6 * 150, places=6)
            a = mj._Metered(SimpleNamespace(messages=AioMessages()), aio=True)
            asyncio.run(a.messages.create(model="claude-haiku-5-5", messages=[]))
            self.assertEqual(dict(mj.SPEND.calls), {"claude-sonnet-5-5": 1, "claude-haiku-5-5": 1})

            class Slow:
                async def create(self, **body):
                    await asyncio.sleep(1.0)

            async def stop_one():   # 先に届いた答えで決めて、返事を待たずに止めた問い合わせも、料金の見込みに入れる
                job = asyncio.ensure_future(mj._Metered(SimpleNamespace(messages=Slow()), aio=True).messages.create(
                    model="claude-sonnet-5-5", messages=[]))
                await asyncio.sleep(0.01)
                job.cancel()
                await asyncio.gather(job, return_exceptions=True)
            before = mj.SPEND.yen
            asyncio.run(stop_one())
            self.assertEqual(dict(mj.SPEND.stopped), {"claude-sonnet-5-5": 1})
            self.assertAlmostEqual(mj.SPEND.yen - before, (1670 * 2.0 + 40 * 10.0) / 1e6 * 150, places=6)   # 返事のあった1回の平均
            mj.SPEND.limit = mj.SPEND.yen   # 上限に達した：それより後は送らない（失敗は止まった判定と同じ形）
            with self.assertRaises(mj.OtherJudgeError):
                c.messages.create(model="claude-sonnet-5-5", messages=[])
            self.assertEqual(len(sent), 2)
            with tempfile.TemporaryDirectory() as d:   # 結果を保存するとき、料金も記録に入る
                old_dir, old_ledgers = common.RESULTS_DIR, list(common.LEDGERS)
                common.RESULTS_DIR, common.LEDGERS[:] = Path(d), [mj.SPEND]
                try:
                    got = json.loads(common.save_result("TEST", {}).read_text(encoding="utf-8"))
                finally:
                    common.RESULTS_DIR, common.LEDGERS[:] = old_dir, old_ledgers
            self.assertEqual(got["有料の窓口の料金"]["Anthropic の判定"]["回数"], {"claude-sonnet-5-5": 1, "claude-haiku-5-5": 1})
            self.assertEqual(common.base_parser("").parse_args([]).budget_yen, common.DEV_BUDGET_YEN)   # 試しには初めから上限がある
        finally:
            mj.SPEND = old

    def test_doc_has_every_host_and_key_name(self):
        # 枠に、判定の接続先・キーの名前と、いま使えている接続先（貼り替えで消さない）が、すべてある
        from meaning_judge import OTHER_JUDGES
        lines = self.blocks()
        for j in OTHER_JUDGES.values():
            self.assertIn(j["host"], lines)
            self.assertTrue(any(l.startswith(f"{j['key']}=") for l in lines), j["key"])
        for keep in ("acp-api.amivoice.com", "stt-rt.soniox.com", "api.soniox.com", "*.googleapis.com", "github.com", "*.githubusercontent.com"):
            self.assertIn(keep, lines)
        # この作業の場所そのものが読む名前にしない
        self.assertFalse(any(l.startswith("ANTHROPIC_API_KEY=") for l in lines))
        self.assertNotIn("ANTHROPIC_API_KEY", {j["key"] for j in OTHER_JUDGES.values()})

    def test_requests_carry_the_same_prompt_and_choices(self):
        # 会社ごとに違うのは送り方だけ：同じ問い合わせの文と、同じ選べるものの名前（Gemini の _config と同じ並び）。
        # Jev は決まり・場面・選べるものを別々に受け取る：同じ決まりの文・同じ場面・同じ名前と説明（同じ並び）
        from meaning_judge import OTHER_JUDGES, RULES, cached_content, decision_model, options, other_path, other_request, prompt, prompt_parts, scene
        q, asked, text = self.q(), "念のためご連絡はメールでよろしいでしょうか？", "メールのほうが助かりますが…"
        names = [n for n, _, _ in options(q, asked)]
        self.assertEqual({n for n in OTHER_JUDGES if decision_model(n)}, {"Jev 1.14", "d1 Ultra（Liquid）", "d1.1（Liquid）", "GPT-6 Luna Decisions",
                                                                         "Mercury Decide（Inception）", "Solar Decide（Upstage）"})
        for name in OTHER_JUDGES:
            body = other_request(name, q, text, asked)
            sent = json.dumps(body, ensure_ascii=False)
            if decision_model(name):  # 判断のモデル（Jev・d1）：問いは短く・選択肢は同じ名前で同じ並び（定義は意味で読む書き方）・同じ場面・同じ窓口
                self.assertEqual(other_path(name), "/api/v1/systemone")
                ask = body["questions"]["choice"]
                self.assertEqual((list(ask["criteria"]), body["state"]), (names, scene(q, text, asked)))
                self.assertLess(len(ask["instructions"]), 120)
                continue
            if OTHER_JUDGES[name]["maker"] == "anthropic":   # 毎回同じ前の部分に印を付けて、後ろに変わる部分（cached_content）
                fixed, varying = prompt_parts(q, text, asked)
                self.assertEqual(body["messages"][0]["content"], cached_content(fixed, varying))
                self.assertEqual(fixed + varying, prompt(q, text, asked))
            else:
                self.assertIn(json.dumps(prompt(q, text, asked), ensure_ascii=False), sent)
            self.assertIn(json.dumps(names, ensure_ascii=False), sent)
            # Claude Haiku 5.5 は温度などを送ると断る（2026-10-18 に400）
            self.assertFalse({"temperature", "top_p", "top_k"} & set(body), name)

    def test_replies_are_read_the_same_way(self):
        # 返事の形が違っても、read で同じ中の名前になる・読めない返事は None
        from meaning_judge import options, other_text, read
        q, asked = self.q(), "念のためご連絡はメールでよろしいでしょうか？"
        name, cond = options(q, asked)[0][0], options(q, asked)[0][2]
        claude = {"content": [{"type": "tool_use", "name": "answer", "input": {"choice": name}}]}
        gpt = {"output": [{"type": "reasoning"}, {"type": "message", "content": [{"type": "output_text", "text": json.dumps({"choice": name})}]}]}
        self.assertEqual(read(q, other_text("Claude Haiku 5.5", claude), asked), cond)
        self.assertEqual(read(q, other_text("GPT-6 Luna", gpt), asked), cond)
        self.assertIsNone(read(q, other_text("Claude Haiku 5.5", {"content": [{"type": "text", "text": "…"}]}), asked))
        self.assertIsNone(read(q, other_text("GPT-6 Luna", {"output": []}), asked))
        jev = {"answers": {"choice": {"type": "choice", "choice": name, "confidence": 0.99}}}
        self.assertEqual(read(q, other_text("Jev 1.14", jev), asked), cond)
        self.assertIsNone(read(q, other_text("Jev 1.14", {"error": {"code": 402}}), asked))
        # Jev の確からしさは答えに残す（線は JudgePanel が当てる）・言い切っているかは測って合った線（0.2）で読む（⛔ 半分で切っていた）
        got = read(q, other_text("Jev 1.14", jev | {"answers": jev["answers"] | {"firm": {"type": "noul", "noul": 0.3}}}), asked)
        self.assertEqual((got.sure, got.firm), (0.99, True))
        self.assertFalse(read(q, other_text("Jev 1.14", jev | {"answers": jev["answers"] | {"firm": {"noul": 0.1}}}), asked).firm)
        self.assertIsNone(read(q, other_text("Claude Haiku 5.5", claude), asked).sure)  # 確からしさを返さない判定は None

    def test_call_tests_choose_judges_in_one_place(self):
        # 判定の選び方は meaning_judge の1か所（add_judge_args・make_judges）。2つ目の判定の既定は JUDGE2（✅ 2026-10-18 ユーザー：当面は Sonnet だけ）
        import argparse
        from meaning_judge import JUDGE2, add_judge_args
        here = Path(__file__).resolve().parent
        for f in ("g14_listen.py", "g34_ack.py", "g50_replay.py"):
            src = (here / f).read_text(encoding="utf-8")
            self.assertIn("add_judge_args(p)", src, f)
            self.assertNotIn('"--judge"', src, f)
        p = argparse.ArgumentParser()
        add_judge_args(p)
        a = p.parse_args(["--judge", "--judge2"])
        self.assertEqual((a.judge, a.judge2), ("3.5 Flash Lite", JUDGE2))
        # ✅ 2026-10-25 ユーザー：「以前、JevやSonnet 5.5 の「考えない」形を使うと決めましたよね。同じことを聞くな！」＝2つ目の判定は、中身の判定と
        #    同じ組（Jev と2つの Sonnet を同時に出し、先に届いた確かな読み）。組は1か所（meaning_judge.RACE）
        from grounding import GROUNDERS
        from meaning_judge import GROUPS, RACE
        self.assertEqual((GROUPS[JUDGE2], GROUNDERS), (RACE, RACE))
        # ✅ 2026-10-30 ユーザー：「d1-ultra（線0.6）と Jev（線0.8）を同時に出し、どちらも確かでないときだけ考えない Sonnet を出す形。OK」
        self.assertEqual(RACE, ("d1 Ultra（Liquid）", "Jev 1.14", "Claude Sonnet 5.5（考える）", "Claude Sonnet 5.5"))

    def test_decisive_answers_go_first_and_survive_rejudge(self):
        # 1日の上限が少ないとき、いまの判定が言い直しへの返事を認めたと読み違えた答えを、先に判定させる（判定し直しで読みを捨てても印は残る）
        from g53_meaning import BASE, first, misread_as_affirmed
        bad = {"set": "D", "qid": "G17", "text": "メールのほうが助かりますが…", "truth": "決められない", "asked_choice": "メール", BASE: "メール"}
        ok = {"set": "D", "qid": "G17", "text": "はい、メールで。", "truth": "メール", "asked_choice": "メール", BASE: "メール"}
        self.assertTrue(misread_as_affirmed(bad, BASE) and first(bad))
        self.assertFalse(first(ok))
        stripped = {k: v for k, v in bad.items() if k != BASE} | {"前の読み違え": True}
        self.assertTrue(first(stripped))


class BatchJudgeTest(unittest.TestCase):
    """正しさだけを見る測りを、Anthropic の Message Batches でまとめて送る（meaning_judge.batch_judge。✅ 2026-10-30 ユーザー：「BatchもOKです」）。
    問い合わせの文と読み方は通話と同じ1か所。料金は送った量すべてが半分。前の部分は1時間もつ形にし、前の部分ごとに1つだけ先にふつうに送る。"""

    def fake(self, input_tokens=600):
        import json
        from types import SimpleNamespace as N

        sent = {"create": [], "batch": []}

        def message(body):
            usage = N(input_tokens=10, output_tokens=20, cache_read_input_tokens=0, cache_creation_input_tokens=input_tokens,
                      cache_creation=N(ephemeral_1h_input_tokens=input_tokens, ephemeral_5m_input_tokens=0))
            answer = {"choice": "はい", "firm": True}
            # 考えない Sonnet は返事の形を決めた文字（form json）・ほかは道具で答える（meaning_judge.other_text の1か所で読む）
            return N(usage=usage, to_dict=lambda: {"content": [{"type": "text", "text": json.dumps(answer, ensure_ascii=False)},
                                                               {"type": "tool_use", "input": answer}]})

        def create(**body):
            sent["create"].append(body)
            return message(body)

        def batch_create(requests):
            sent["batch"] = list(requests)
            return N(id="b1", processing_status="in_progress", request_counts={})

        def results(batch_id):
            for r in sent["batch"]:
                m = message(r["params"])
                m.usage.cache_creation_input_tokens, m.usage.cache_read_input_tokens = 0, input_tokens   # バッチの中では前の部分を読めた
                m.usage.cache_creation = None
                yield N(custom_id=r["custom_id"], result=N(type="succeeded", message=m))
        batches = N(create=batch_create, retrieve=lambda i: N(id=i, processing_status="ended", request_counts={}), results=results)
        client = N(messages=N(create=create, count_tokens=lambda **kw: N(input_tokens=input_tokens), batches=batches))
        return client, sent

    def items(self):
        from flowctl import Question
        q1 = Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        q2 = Question("Q2", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        return [(f"r{i}", q, t, None, None) for i, (q, t) in enumerate([(q1, "はい、しています。"), (q1, "はい。"), (q2, "はい。"), (q1, "ええ。")])]

    def test_warms_each_prefix_then_batches_the_rest_at_half_price(self):
        from meaning_judge import SPEND, Spend, batch_judge
        client, sent = self.fake()
        before = SPEND.yen
        got = batch_judge("Claude Sonnet 5.5", "x", self.items(), client=client, poll_s=0)
        self.assertEqual(sorted(got), ["r0", "r1", "r2", "r3"])
        self.assertTrue(all(str(r) == "はい" and why is None for r, why in got.values()))   # 読み方は通話と同じ（read・other_text）
        self.assertEqual([b["messages"][0]["content"][1]["text"].count("はい") > 0 for b in sent["create"]], [True, True])
        self.assertEqual(len(sent["create"]), 2)                       # 前の部分（質問）ごとに1つだけ、ふつうに送って書いておく
        self.assertEqual(sorted(r["custom_id"] for r in sent["batch"]), ["r1", "r3"])
        self.assertTrue(all(r["params"]["messages"][0]["content"][0]["cache_control"] == {"type": "ephemeral", "ttl": "1h"} for r in sent["batch"]))
        # 料金：先に送った2つは1時間もつ形の書き込み（入力の2倍）・まとめて送った2つは前の部分の読み出しで、半分
        alone = Spend()
        alone.add("claude-sonnet-5-5", {"input_tokens": 10, "output_tokens": 20, "cache_read_input_tokens": 600, "cache_creation_input_tokens": 0},
                  factor=0.5)
        full = Spend()
        full.add("claude-sonnet-5-5", {"input_tokens": 10, "output_tokens": 20, "cache_read_input_tokens": 600, "cache_creation_input_tokens": 0})
        self.assertAlmostEqual(alone.yen, full.yen / 2)
        hour = Spend()
        hour.add("claude-sonnet-5-5", {"input_tokens": 0, "output_tokens": 0, "cache_read_input_tokens": 0, "cache_creation_input_tokens": 600,
                                       "cache_creation": {"ephemeral_1h_input_tokens": 600, "ephemeral_5m_input_tokens": 0}})
        self.assertAlmostEqual(hour.yen, 600 * 2 * 2.00 / 1e6 * 150)
        self.assertAlmostEqual(SPEND.yen - before, 2 * (10 * 2 + 20 * 10 + 600 * 4) / 1e6 * 150 + 2 * alone.yen)

    def test_g59_batch_fills_the_rows_like_the_live_run(self):
        # 測りの道具（g59_calling_judge --batch）：1行の答えの書き方は、ふつうに送る測りと同じ1か所（fill）。答えまでの秒は測らない（None）
        import asyncio
        import unittest.mock as m
        from types import SimpleNamespace as N

        import g59_calling_judge as g
        from meaning_judge import RACE_NAME, Reading

        seen = []

        def fake_batch(name, key, items, budget=None, poll_s=30.0):
            seen.extend(items)
            return {cid: (Reading("尋ねていない") if "尋ねているか" in q.text or q.facets == () else Reading("ご本人"), None)
                    for cid, q, text, asked, before in items}
        args = N(batch=True, judge=None, judge2="Claude Sonnet 5.5", only=["はい、岡田です。"], repeat=1, pace_s=0.0, budget_yen=10.0, env=None,
                 batch_poll_s=0.0, asks_only=False, hide_names=False)
        with m.patch.object(g, "batch_judge", fake_batch), m.patch("common.load_secret", return_value="x"):
            out = asyncio.run(g.run(args))
        self.assertEqual(len(seen), 2 * len(out["rows"]))                 # 目的のお客様の判定と、尋ねているか
        self.assertTrue(all(r["judge2_s"] is None and "judge2" in r and "judge2_asks" in r for r in out["rows"]))
        self.assertIn("judge2", out["summary"])
        self.assertNotIn("judge2（答えまでの秒：中央・遅いほうから1割・最長）", out["summary"])
        with self.assertRaises(SystemExit):                                # 組・その場の判定とは一緒に使えない
            asyncio.run(g.run(N(**{**vars(args), "judge2": RACE_NAME})))

    def test_refuses_when_the_worst_case_exceeds_the_budget(self):
        from meaning_judge import SPEND, OtherJudgeError, batch_judge
        client, sent = self.fake(input_tokens=200_000)
        limit = SPEND.limit
        try:
            with self.assertRaises(OtherJudgeError):
                batch_judge("Claude Sonnet 5.5", "x", self.items(), budget=SPEND.yen + 60, client=client, poll_s=0)
        finally:
            SPEND.limit = limit
        self.assertEqual(sent["batch"], [])                            # まとめては送らない（前の部分ごとの2つだけ送った）
        with self.assertRaises(ValueError):
            batch_judge("Jev 1.14", "x", self.items(), client=client)   # まとめて送れるのは Anthropic の判定だけ


class JudgePanelTest(unittest.TestCase):
    """通話の中の意味の判定の受け持ち（meaning_judge.JudgePanel）：会社の違う2つを受け持ちに置き、止まった判定の代わりに Jev が入る。
    ✅ 2026-10-19 ユーザー：「同じ会社のモデルだけだと、通信の問題が影響するでしょ」「どれかがダウンしていたら、Jevも使ったらいいんじゃない」"""

    LITE, SONNET, JEV = "3.5 Flash Lite", "Claude Sonnet 5.5（考える）", "Jev 1.14"

    def panel(self, fail=None, sure=0.99, standin=True, took=None):
        """fail：判定の名前 ⇒ 投げる失敗（呼ばれた順は calls に残る）。took：判定の名前 ⇒ かかる秒。
        ここの試験は、2つの受け持ちが同じ質問（質問を渡さない＝答えの段の種類）に答えるときの、代わりの判定の入り方を見る。答えの段でその場の判定を
        使わない形（meaning_judge.UNUSED_IN＝F0）は test_flash_lite_is_switched_out_of_the_answer_stage_in_one_place で見るので、ここでは表を空にする"""
        import asyncio
        import unittest.mock as m

        import meaning_judge as mj
        from meaning_judge import JudgePanel, Reading
        patcher = m.patch.object(mj, "UNUSED_IN", {})
        patcher.start()
        self.addCleanup(patcher.stop)
        calls, now = [], [0.0]
        fail, took = fail or {}, took or {}

        def judge(name, answer):
            async def run(q, text, asked=None, before=None):
                calls.append(name)
                if name in took:
                    await asyncio.sleep(took[name])
                if name in fail:
                    raise fail[name]
                return Reading(answer, sure=sure if name == self.JEV else None)
            return run
        panel = JudgePanel({"judge": (self.LITE, judge(self.LITE, "はい")), "judge2": (self.SONNET, judge(self.SONNET, "はい"))},
                           standin=(self.JEV, judge(self.JEV, "はい")) if standin else None, clock=lambda: now[0])
        return panel, calls, now

    @staticmethod
    def ask(panel, kind):
        import asyncio

        from meaning_judge import NoJudgment
        try:
            return asyncio.run(panel.ask(kind, None, "はい。"))
        except NoJudgment as exc:
            return exc

    def test_each_slot_asks_its_own_judge(self):
        panel, calls, _ = self.panel()
        self.assertEqual([self.ask(panel, k).by for k in ("judge", "judge2")], [self.LITE, self.SONNET])
        self.assertEqual(calls, [self.LITE, self.SONNET])

    def test_group_asks_jev_first_and_sonnets_only_without_a_sure_reading(self):
        # 組（Jev＋2つの Sonnet）は Jev を先に出し、確かな読みが届けば Sonnet は出さない。確かでない読み・失敗が届いたらその時に、
        # LEAD_WAIT_S 秒たっても届かなければ、2つの Sonnet を出す（first_of の lead＝意味の判定・中身の判定の1か所）。
        # ✅ 2026-10-29 ユーザー：「(1) では、Jev が『確かでない』と返したら、その時点で Sonnet を出します。OK」
        import asyncio
        import time

        from meaning_judge import LEAD_WAIT_S, OtherJudgeError, JudgePanel, Reading, first_of
        THINK, FAST = self.SONNET, "Claude Sonnet 5.5"

        def run(sure=0.99, jev_s=0.0, fail=False):
            calls = []

            def judge(name, s=0.0):
                async def go(q, text, asked=None, before=None):
                    calls.append((name, round(time.monotonic() - t0, 1)))
                    await asyncio.sleep(s)
                    if name == self.JEV and fail:
                        raise OtherJudgeError(401, "期限切れ")
                    return Reading("はい", sure=sure if name == self.JEV else None)
                return go
            panel = JudgePanel({"judge2": ((self.JEV, judge(self.JEV, jev_s)), (THINK, judge(THINK, 0.05)), (FAST, judge(FAST, 0.02)))})
            t0 = time.monotonic()
            got = asyncio.run(panel.ask("judge2", None, "はい。"))
            return got.by, calls
        by, calls = run()
        self.assertEqual((by, [n for n, _ in calls]), (self.JEV, [self.JEV]))         # 確かな読み：Sonnet は出さない
        # 答えの意味の質問（q=None）の Sonnet は考える形だけ（✅ 2026-10-30 夜 ユーザー：「(1)(2)ともお勧めの形でOKです」＝考えない形は
        # お呼びする段の2つだけ。meaning_judge の group_kinds）
        by, calls = run(sure=0.5)
        self.assertEqual((by, sorted(n for n, _ in calls)), (THINK, sorted([self.JEV, THINK])))
        self.assertTrue(all(t < LEAD_WAIT_S for n, t in calls))                       # 確かでない読みが届いた時に出す（待たない）
        by, calls = run(fail=True)
        self.assertEqual(by, THINK)                                                    # 失敗も同じ
        by, calls = run(jev_s=1.0)
        # 届かなければ LEAD_WAIT_S 秒で出す。先に出したものの確かな読みが待つ長さの中で届けば、先に届いた Sonnet よりそちらを優先（優先の順は組の並びの1つ＝
        # first_of。⛔ 2026-11-06 日本時間8時台（EN-C の指摘1）までは、先に届いた Sonnet で決めていた）
        self.assertEqual(by, self.JEV)
        self.assertTrue(all(abs(t - LEAD_WAIT_S) < 0.1 for n, t in calls if n != self.JEV))
        # 先に出すものが無い組（契約者が Jev を使わない＝2つの Sonnet）は、今までどおり同時
        async def two():
            order = []

            def s(name, d):
                async def go():
                    order.append(name)
                    await asyncio.sleep(d)
                    return name
                return go
            return await first_of([s(THINK, 0.05), s(FAST, 0.01)], lambda g: True), order
        self.assertEqual(asyncio.run(two()), (FAST, [THINK, FAST]))

    def test_calling_questions_ask_both_decision_models_first_then_the_fast_sonnet(self):
        # ✅ 2026-10-30 ユーザー：「d1-ultra（線0.6）と Jev（線0.8）を同時に出し、どちらも確かでないときだけ考えない Sonnet を出す形。OK」
        # お呼びする段の2つの質問（目的のお客様の判定・尋ねているか）：d1-ultra と Jev を同時に先に出し、d1-ultra の確かな読みを優先して決める（d1-ultra が確かでない・失敗なら Jev の確かな読み）。どちらも
        # 確かでなければ考えない Sonnet だけ（考える形は出さない）。答えの意味は d1-ultra → 考える Sonnet で、Jev は d1-ultra が止まったときの
        # 代わりだけ（✅ 2026-10-31 の夜 ユーザー：(b)「OK」）。
        # 組の中でどれが答えるかは takes_part・線は sure_line の1か所
        import asyncio
        import dataclasses
        import time

        from g22_opening import BUSINESS
        from instruction import Target
        from meaning_judge import RACE, JudgePanel, Reading, question_kind, sure_line
        D1, JEV, THINK, FAST = RACE
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"))
        f = b.flow(play_recordings=True)
        target_q, asks_q, answer_q = f.judge_context()[0], next(iter(f.asks_questions.values())), b.questions[0]
        self.assertEqual([question_kind(q) for q in (target_q, asks_q, answer_q)], ["facets", "asks", "other"])
        self.assertEqual([sure_line(D1, q) for q in (target_q, asks_q)], [0.6, 0.6])

        def run(q, sures, down=(), asks=1):
            calls = []

            def judge(name):
                async def go(q, text, asked=None, before=None):
                    calls.append((name, round(time.monotonic() - t0, 2)))
                    await asyncio.sleep({D1: 0.02, JEV: 0.01, FAST: 0.03, THINK: 0.06}[name])
                    return Reading("はい", sure=sures.get(name))
                return go
            panel = JudgePanel({"judge2": tuple((n, judge(n)) for n in RACE)}, down=down)
            for _ in range(asks):   # 同じ受け持ちで続けて読む（止まったと分かった判定は、次の発話から問い合わせない）
                calls.clear()
                t0 = time.monotonic()
                got = asyncio.run(panel.ask("judge2", q, "はい。"))
            return got.by, calls
        for q in (target_q, asks_q):
            by, calls = run(q, {D1: 0.7, JEV: 0.3})
            self.assertEqual((by, sorted(n for n, _ in calls)), (D1, sorted([D1, JEV])))       # d1-ultra の確かな読み：Sonnet は出さない
            self.assertTrue(all(t < 0.01 for _, t in calls))                                 # 2つは同時に先に出す
            by, calls = run(q, {D1: 0.5, JEV: 0.9})
            self.assertEqual((by, sorted(n for n, _ in calls)), (JEV, sorted([D1, JEV])))      # Jev の確かな読み
            by, calls = run(q, {D1: 0.5, JEV: 0.3})
            self.assertEqual((by, sorted(n for n, _ in calls)), (FAST, sorted([D1, JEV, FAST])))   # どちらも確かでない：考えない Sonnet だけ
            by, calls = run(q, {D1: 0.7, JEV: 0.9})
            self.assertEqual((by, sorted(n for n, _ in calls)), (D1, sorted([D1, JEV])))       # 2つとも確か：先に届いた Jev ではなく d1-ultra の読み
        # 答えの意味（F0＝✅ 2026-11-07 日本時間8時57分04秒「はい、その形でいいですが…」・8時05分55秒「d1-ultra とJev を、両方出して、d1-ultra を優先する。
        # d1-ultra が答えを出せないときは、Jev が対応する。それでも対応できないときに、そのソネットが対応する」）：お呼びする段と同じ形＝d1-ultra と Jev を同時に
        # 先に出し、d1-ultra の確かな読み → Jev の確かな読み → 考える Sonnet。⛔ それまでは Jev を d1-ultra が止まったときの代わりだけにしていた（10-31 の (b)）
        by, calls = run(answer_q, {D1: 0.99, JEV: 0.99})
        self.assertEqual((by, sorted(n for n, _ in calls)), (D1, sorted([D1, JEV])))           # 2つとも確か：d1-ultra の読み（考える Sonnet は出さない）
        self.assertTrue(all(t < 0.01 for _, t in calls))                                     # 2つは同時に先に出す
        below = sure_line(D1, answer_q) - 0.01                                               # 線より下（線の値に寄りかからない）
        by, calls = run(answer_q, {D1: below, JEV: 0.99})
        self.assertEqual((by, sorted(n for n, _ in calls)), (JEV, sorted([D1, JEV])))         # d1-ultra が確かでない：Jev の確かな読み
        by, calls = run(answer_q, {D1: below, JEV: sure_line(JEV, answer_q) - 0.01})
        self.assertEqual((by, sorted(n for n, _ in calls)), (THINK, sorted([D1, JEV, THINK])))   # どちらも確かでない：考える Sonnet
        by, calls = run(answer_q, {D1: 0.99, JEV: 0.99}, down=[D1])
        self.assertEqual(by, JEV)                                                              # d1-ultra が止まったと分かった発話：同時に出した Jev
        by, calls = run(answer_q, {D1: 0.99, JEV: 0.99}, down=[D1], asks=2)
        self.assertEqual((by, [n for n, _ in calls]), (JEV, [JEV]))                            # 止まっている間：Jev だけが先に出る
        by, calls = run(answer_q, {D1: 0.99, JEV: 0.5}, down=[D1], asks=2)
        self.assertEqual((by, sorted(n for n, _ in calls)), (THINK, sorted([JEV, THINK])))

    def test_prior_reader_falls_to_jev_on_any_failure(self):
        # ⛔ 2026-11-06 日本時間8時台（5時56分55秒のご質問の読み直し EN-C の指摘5・6）：前の話の答えは、d1-ultra が断ったときだけ Jev へ回り、つながらない
        #    （httpx.ConnectError）・時間切れでは Jev に問い合わせずに誤りを上げた（通話の中では前の話の答えが無いまま進み、測りの道具は止まった）。打ち切りは通信の
        #    60秒だけだった。同期と非同期の2本が同じ形の写しだった ⇒ 順と取り出しは _prior_walk の1か所・どの失敗でも次の判定へ・1回は DOWN_AFTER_S で打ち切る
        import asyncio
        import unittest.mock as m

        import httpx

        import meaning_judge as mj
        D1, JEV = mj.PRIOR_READERS

        def boom(kind):
            if kind == "connect":
                raise httpx.ConnectError("つながらない")
            if kind == "refused":
                raise mj.OtherJudgeError(503, "混雑")
            raise asyncio.TimeoutError()

        for kind in ("connect", "refused", "timeout"):
            def send(client, name, req, kind=kind):
                if name == D1:
                    boom(kind)
                return "RAW"

            async def asend(client, name, req, kind=kind):
                return send(client, name, req)
            with m.patch.object(mj, "_send_other", send), m.patch.object(mj, "_asend_other", asend), \
                    m.patch.object(mj, "prior_request", lambda name, q, before: "REQ"), m.patch.object(mj, "other_text", lambda name, t: t), \
                    m.patch.object(mj, "read_prior", lambda q, t: ("利用する", 0.95, "利用する") if t == "RAW" else (None, None, None)):
                clients = {D1: object(), JEV: object()}
                self.assertEqual(mj.read_prior_first(clients, None, "前の話"), ("利用する", 0.95, "利用する"), kind)
                self.assertEqual(asyncio.run(mj.aread_prior_first(clients, None, "前の話")), ("利用する", 0.95, "利用する"), kind)

        async def slow(client, name, req):
            await asyncio.sleep(1.0 if name == D1 else 0.0)
            return "RAW"
        with m.patch.object(mj, "_asend_other", slow), m.patch.object(mj, "DOWN_AFTER_S", 0.1), \
                m.patch.object(mj, "prior_request", lambda name, q, before: "REQ"), m.patch.object(mj, "other_text", lambda name, t: t), \
                m.patch.object(mj, "read_prior", lambda q, t: ("利用する", 0.95, "利用する")):
            self.assertEqual(asyncio.run(mj.aread_prior_first({D1: object(), JEV: object()}, None, "前の話")), ("利用する", 0.95, "利用する"))
        # 測りの道具が使う同期の形（read_prior_first）も、打ち切りの秒（DOWN_AFTER_S）は本番と同じ1か所：d1-ultra が遅れれば Jev の答え（本番の組と同じ読み）。
        # ⛔ 2026-11-06 日本時間13時台の見直し（判定の組の持ち場の A5）：同期の形は打ち切りを持たず、遅れた d1-ultra の答えを待って使った＝測りが本番と違う
        #    判定の答えを数えうる
        import time as _time

        def slow_sync(client, name, req):
            if name == D1:
                _time.sleep(0.5)
                return "RAW_D1"
            return "RAW"
        with m.patch.object(mj, "_send_other", slow_sync), m.patch.object(mj, "DOWN_AFTER_S", 0.1), \
                m.patch.object(mj, "prior_request", lambda name, q, before: "REQ"), m.patch.object(mj, "other_text", lambda name, t: t), \
                m.patch.object(mj, "read_prior", lambda q, t: ("利用しない", 0.9, "利用しない") if t == "RAW_D1" else ("利用する", 0.95, "利用する")):
            self.assertEqual(mj.read_prior_first({D1: object(), JEV: object()}, None, "前の話"), ("利用する", 0.95, "利用する"))
        # 測りの同期の形も、本番と同じく会話の側の待つ長さ（待つ長さの1か所 Limits.judge_wait_s）で前の話の答えを待つのをやめる（本番の組は、会話の側の合図
        # release で待つのをやめる＝JudgePanel.ask の prior_of）。⛔ 2026-11-06 日本時間23時22分41秒のご質問の見直し（判定の組と測りの持ち場 J3）：同期の形は
        # 1回ずつの打ち切り（10秒）まで待ち、本番では待つ長さに間に合わず使わない前の話の答えを、測りでは使って数えうる形だった
        import flowctl
        with m.patch.object(mj, "_send_other", slow_sync), \
                m.patch.object(flowctl.Limits, "judge_wait_s", lambda self, held_s=0.0: 0.2), \
                m.patch.object(mj, "prior_request", lambda name, q, before: "REQ"), m.patch.object(mj, "other_text", lambda name, t: t), \
                m.patch.object(mj, "read_prior", lambda q, t: ("利用しない", 0.9, "利用しない") if t == "RAW_D1" else ("利用する", 0.95, "利用する")):
            self.assertEqual(mj.read_prior_first({D1: object(), JEV: object()}, None, "前の話"), (None, None, None))
        # 1回ずつの問い合わせは、ほかの判定と同じ1か所（routed_call）：組の道の状態（RouteState＝JudgePanel）で、止まっている判定には送らず、止まったら
        # 印を付けて知らせる（本書 9-5 の (6)「どのAIが止まっても、新しい電話は回復するまで一時停止」・止まったことは通話の報告の ai_trouble に残す）。
        # ⛔ 2026-11-06 日本時間8時台（EN-C の残り「前の話の答えの止まりの記録」を確かめて見つけた）：前の話の答えだけ routed_call を通らず、止まった d1-ultra
        # にも送り、止まっても印も知らせも残らなかった
        sent, told = [], []

        async def flaky(client, name, req):
            sent.append(name)
            if name == D1:
                raise mj.OtherJudgeError(503, "混雑")
            return "RAW"
        st = mj.RouteState()
        st.on_trouble = told.append
        with m.patch.object(mj, "_asend_other", flaky), m.patch.object(mj, "prior_request", lambda name, q, before: "REQ"), \
                m.patch.object(mj, "other_text", lambda name, t: t), m.patch.object(mj, "read_prior", lambda q, t: ("利用する", 0.95, "利用する")):
            clients = {D1: object(), JEV: object()}
            self.assertEqual(asyncio.run(mj.aread_prior_first(clients, None, "前の話", state=st)), ("利用する", 0.95, "利用する"))
            self.assertEqual((sent, st._down(D1), [t["model"] for t in told if t.get("outage")]), ([D1, JEV], True, [D1]))
            sent.clear()
            self.assertEqual(asyncio.run(mj.aread_prior_first(clients, None, "前の話", state=st)), ("利用する", 0.95, "利用する"))
            self.assertEqual(sent, [JEV])   # 止まっている d1-ultra には送らない（組のほかの問い合わせと同じ印）

    def test_standin_holder_is_per_utterance(self):
        # ⛔ 2026-11-06 日本時間8時台（5時56分55秒のご質問の読み直し EN-C の指摘4）：代わり（Jev）が一度ある受け持ちに入ると、その印が組に残り、そのあとの
        #    別の発話・別の質問でも、お呼びする段の組から Jev を「ほかの受け持ちが同じ会社で答えた」として外した（d1-ultra が確かでない言葉が、Jev ではなく
        #    考えない Sonnet で決まった）。会社を分ける決まりは「1つの発話の同じ質問で」（✅ 2026-10-19「同じ会社のモデルだけだと、通信の問題が影響するでしょ」・
        #    本書 9-5 の (6)「お呼びする段は Jev を外さない」）⇒ 代わりの印は発話（質問と言葉）ごと
        #    （答えの段の質問でその場の判定が止まったときの代わりを見るので、答えの段でその場の判定を使わない表 UNUSED_IN は空にする＝F0 の形は別の試験）
        import asyncio
        import unittest.mock as m

        import meaning_judge as mj
        from meaning_judge import RACE, JudgePanel, OtherJudgeError, Reading
        patcher = m.patch.object(mj, "UNUSED_IN", {})
        patcher.start()
        self.addCleanup(patcher.stop)
        D1, JEV = RACE[0], RACE[1]
        LITE = "3.5 Flash Lite"

        def judge(name, sure, fail=False):
            async def go(q, text, asked=None, before=None):
                if fail:
                    raise OtherJudgeError(400, "断られた")
                return Reading("ご本人" if q is not None else "はい", sure=sure)
            return go
        panel = JudgePanel({"judge": ((LITE, judge(LITE, None, fail=True)),), "judge2": tuple((n, judge(n, 0.3 if n == D1 else 0.9)) for n in RACE)},
                           standin=(JEV, judge(JEV, 0.99)))
        f, *_ = self.calling()
        q, asked, before = f.judge_context()

        async def main():
            first = await panel.ask("judge", None, "はい。")                    # 答えの段：その場の判定が答えず、代わりの Jev が入る
            second = await panel.ask("judge2", q, "お電話代わりました。", asked, before)   # 別の発話のお呼びする段
            return first.by, second.by
        self.assertEqual(asyncio.run(main()), (JEV, JEV))

    def test_held_reading_reaches_the_conversation_before_it_stops_waiting(self):
        # ⛔ 2026-11-06 日本時間8時台（5時56分55秒のご質問の読み直し EN-C の指摘2・3）：組は Jev の確かな読みを「問い合わせを始めてから Limits.hold_s」まで
        #    持ち、会話の側は「言葉が出揃ってから flow.limits.hold_s」で待つのをやめた＝起点も値も2か所。d1-ultra が待つ長さに間に合わないと、Jev の読みは会話の
        #    側が待つのをやめた直後に渡り、目的の人かを1回確かめた（✅ 本書 9-5 の (6)「d1-ultra が…会話の側の待つ長さ（2秒）に間に合わないときだけ Jev」・
        #    10-29「『確かめが1回増える』のは安全でなく、相手からの不信ですよ！」）⇒ 待つ長さは会話の側の1か所：切れる時に組へ合図し、組は持っている読みを返す
        import asyncio
        import dataclasses
        import unittest.mock as m
        from types import SimpleNamespace

        from convo import check_handler
        from meaning_judge import RACE, JudgePanel, Reading
        D1, JEV = RACE[0], RACE[1]

        def drive(took, hold_s=None):
            f, *_ = self.calling()
            if hold_s is not None:
                f.limits = dataclasses.replace(f.limits, hold_s=hold_s)
            f.use_checks("judge", "judge2")

            def judge(name):
                async def go(q, text, asked=None, before=None):
                    await asyncio.sleep(took.get(name, 0.01))
                    return Reading("ご本人", sure=0.9)
                return go
            panel = JudgePanel({"judge": ("3.5 Flash Lite", judge("3.5 Flash Lite")), "judge2": tuple((n, judge(n)) for n in RACE)},
                               standin=(JEV, judge(JEV)))

            async def main():
                pending = []
                f.on_callee()
                handle, _, info, _ = check_handler(f, judge=panel.slot("judge"), judge2=panel.slot("judge2"), pcm=b"\x00\x00", rate=16000,
                                                   wav="x.wav", tasks=pending, audio_at=1.0)
                f.on_heard("お電話代わりました。"); f.on_activity(False, 2.0)
                out = await handle(SimpleNamespace(name="report_party", args={"相手": "目的の人"}))
                await asyncio.wait(pending, timeout=4)
                return info, out
            with m.patch("stitch_gap.callee_speech", return_value=(b"", 16000, 0.0)):
                info, out = asyncio.run(main())
            return f, info, out
        for took, hold_s in (({D1: 2.5, JEV: 0.05}, None), ({D1: 1.0, JEV: 0.05}, 0.3)):
            f, info, out = drive(took, hold_s)
            self.assertEqual(info.get("judge2_by"), JEV, (took, hold_s))
            self.assertNotEqual(out[0].get("result"), "confirm_target", (took, hold_s))   # 確かめを1回増やさない

    def test_no_call_to_a_judge_marked_down_and_one_sure_rule(self):
        # ⛔ 2026-11-06 日本時間13時台の見直し（判定の組の持ち場の指摘2・3）：(1) 止まっているとみなした判定（DOWN_S のあいだ）に送らない決まりが、意味の判定の
        #    組（JudgePanel._ask）にだけあり、中身の判定の組（grounding.make_grounder）と止まった判定の代わり（standin）は、止まった Jev にも送っていた
        #    ⇒ 1回ずつの問い合わせの1か所（routed_call）で見る。(2) 確かな読みの決め方が2か所（grounding.trusted＝確からしさの無い読みも確か・
        #    meaning_judge.sure_reading＝確からしさの無い読みは確かでない）⇒ sure_reading の1か所（中身の判定は質問の種類 ground の線）
        import asyncio
        from types import SimpleNamespace

        from grounding import trusted
        from meaning_judge import FAILED, OTHER_JUDGES, RouteState, routed_call, sure_line, sure_reading
        jev = next(n for n in OTHER_JUDGES if n.startswith("Jev"))
        state = RouteState(clock=lambda: 100.0)
        state.down_until[jev] = 150.0
        called, tried = [], []

        async def direct():
            called.append(jev)
            return "読み"
        got = asyncio.run(routed_call(state, jev, direct, None, tried))
        self.assertEqual((got is FAILED, called), (True, []))
        self.assertEqual(sure_line(jev, "ground"), OTHER_JUDGES[jev]["ground_sure_min"])
        for sure in (None, 0.5, 0.9):
            self.assertEqual(trusted(jev, sure), sure_reading(jev, "ground", SimpleNamespace(sure=sure, firm_p=None)), sure)
        self.assertEqual((trusted(jev, None), trusted(jev, 0.9)), (False, True))

    def test_flash_lite_is_switched_out_of_the_answer_stage_in_one_place(self):
        # F0（✅ 2026-11-07 日本時間8時57分04秒「はい、その形でいいですが…」＝8時台の2回目のご報告「Flash Lite は、まず (1) の使わない形で入れます。測りの数で
        # 使い方を決め、同じ1か所で切り替えます」）：組の中で使わない判定の表（meaning_judge.UNUSED_IN）にあれば、その種類の質問では、自分でも答えず・止める側
        # だけにも裏で出さない（料金だけかかる＝その読みを使う所が無い）。ほかの種類（待たせた方が戻ったか・お呼びする段の止める側）は今までどおり。ほかの受け持ちが
        # 無い（1つの判定で測る道具）ときは答える。表から外せば、今までの形（自分で答える）に戻る
        import unittest.mock as m

        import meaning_judge as mj
        from flowctl import ASKS_MEANINGS, RETURN_MEANINGS, Question
        from meaning_judge import RACE, JudgePanel
        fn = lambda *a, **k: None
        answer_q = Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        returned_q = Question("R", "（戻ったか）", "choice", conditions=tuple(RETURN_MEANINGS))
        asks_q = Question("A", "（尋ねているか）", "choice", conditions=tuple(ASKS_MEANINGS))
        panel = lambda: JudgePanel({"judge": ("3.5 Flash Lite", fn), "judge2": tuple((n, fn) for n in RACE)}, backup=True)
        p = panel()
        self.assertEqual([p.answers("judge", q) for q in (answer_q, returned_q, asks_q)], [False, True, False])
        self.assertTrue(p.answers("judge2", answer_q))
        self.assertNotIn("3.5 Flash Lite", [n for n, _ in p._backups("judge2", "other")])   # 裏でも出さない
        self.assertIn("3.5 Flash Lite", [n for n, _ in p._backups("judge2", "facets")])     # お呼びする段の止める側は今までどおり
        self.assertTrue(JudgePanel({"judge": ("3.5 Flash Lite", fn)}).answers("judge", answer_q))   # 1つの判定で測る
        with m.patch.object(mj, "UNUSED_IN", {}):
            self.assertTrue(panel().answers("judge", answer_q))   # 表から外せば、今までの形

    def test_stop_only_backup_starts_when_the_leads_fail_even_without_the_rest(self):
        # ⛔ 2026-11-06 日本時間13時台の見直し（判定の組の持ち場の指摘6）：お呼びする段で考えない Sonnet が止まっている（組が d1-ultra と Jev だけ＝全部が先に
        #    出すもの）と、どちらも確かでないと分かっても on_rest が呼ばれず、止める側だけの 3.5 Flash Lite が裏で出なかった（✅ 本書 9-5 の (6)「d1-ultra と Jev が
        #    どちらも確かでないと分かった時点で裏で出し」）⇒ 先に出すものから使える答えが無いと分かった時点で、ほかのものが無くても on_rest を呼ぶ
        import asyncio

        from meaning_judge import LEAD_WAIT_S, Race, first_of
        r = Race(2, leads=(0, 1))
        self.assertEqual(r.begin(), ([0, 1], False))
        self.assertEqual(r.next(0.0), ("wait", LEAD_WAIT_S))
        self.assertEqual(r.next(LEAD_WAIT_S), ("rest", []))
        r = Race(2, leads=(0, 1)); r.begin(); r.done(0); r.done(1)
        self.assertEqual([r.next(0.1), r.next(0.1)], [("rest", []), ("none", None)])
        r = Race(2, leads=(0, 1)); r.begin(); r.done(1, "はい")
        self.assertEqual(r.next(LEAD_WAIT_S)[0], "wait")   # 使える答えがあれば呼ばない（前の順の d1-ultra の答えを待つ）
        calls = []

        def slow(answer, took):
            async def go():
                await asyncio.sleep(took)
                return answer
            return go
        got = asyncio.run(first_of([slow(None, 0.01), slow(None, 0.02)], lambda v: True, leads=(0, 1), on_rest=lambda: calls.append(1)))
        self.assertEqual((got, calls), (None, [1]))

    def test_group_answer_does_not_depend_on_when_the_conversation_stopped_waiting(self):
        # ⛔ 2026-11-06 日本時間13時台の見直し（13時27分07秒のご質問・判定の組の持ち場の指摘1）：会話の側が組へ「待つのをやめた」合図を出すのは、待つ長さが
        #    切れたときだけだった。答えの段で、その場の判定（3.5 Flash Lite）が先に届いて会話の側が先に決めると、合図が出ず、組（d1-ultra → 考える Sonnet）は
        #    d1-ultra を打ち切り（DOWN_AFTER_S＝本番10秒）まで待った＝組の読みが10秒遅れて届き、しかも組の答えが、もう1つの受け持ち（その場の判定）の速さで
        #    変わった（d1-ultra が待つ長さに遅れても、その場の判定が速いと d1-ultra の読み・遅いと Sonnet の読み）。⇒ 組へ合図するのは、会話の側の待つ長さが
        #    切れる時（言葉が出揃ってから flow.limits.hold_s）の1か所：先に決めても、その時に合図する・待たない報告も同じ（✅ 本書 9-5 の (6)「d1-ultra が…
        #    会話の側の待つ長さ（2秒）に間に合わないときだけ」）
        import asyncio
        import dataclasses
        import unittest.mock as m
        from types import SimpleNamespace

        import meaning_judge as mj
        from convo import check_handler
        from flowctl import Flow, Question
        from meaning_judge import RACE, JudgePanel, Reading
        D1, JEV, THINK, FAST = RACE

        def drive(lite_s, d1_s, wants=True):
            f = Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))])
            f.limits = dataclasses.replace(f.limits, hold_s=0.4)
            f.use_checks("judge", "judge2")
            f.on_callee()

            def judge(answer, took, sure=None):
                async def go(q, text, asked=None, before=None):
                    await asyncio.sleep(took)
                    return Reading(answer, sure=sure)
                return go
            panel = JudgePanel({"judge": ("3.5 Flash Lite", judge("はい", lite_s)),
                                # Jev は確かでない読み（答えの段も Jev を同時に出す＝F0。確かなら Jev で決まり、待つ長さの切れ目を見られない）
                                "judge2": ((D1, judge("はい", d1_s, 0.99)), (JEV, judge("はい", 0.01, 0.5)),
                                           (THINK, judge("いいえ", 0.1)), (FAST, judge("はい", 0.01)))},
                               standin=(JEV, judge("はい", 0.01, 0.99)))

            async def main():
                pending = []
                handle, _, info, _ = check_handler(f, judge=panel.slot("judge"), judge2=panel.slot("judge2"), pcm=b"\x00\x00", rate=16000,
                                                   wav="x.wav", tasks=pending, audio_at=1.0)
                f.on_heard("ええ、しています。"); f.on_activity(False, 2.0)
                f.wants_checks = lambda name, args=None: wants
                f.binding = lambda name, args=None: False
                await handle(SimpleNamespace(name="record_answer", args={"質問": "Q1", "答えの種類": "はい"}))
                await asyncio.wait(pending, timeout=6)
                return info
            with m.patch("stitch_gap.callee_speech", return_value=(b"", 16000, 0.0)), m.patch.object(mj, "DOWN_AFTER_S", 3.0):
                return asyncio.run(main())
        # d1-ultra は待つ長さ（0.4秒）に遅れる（1.2秒）：組の答えは、その場の判定が速くても遅くても、待つ長さで決まる考える Sonnet の読み
        got = {lite_s: drive(lite_s, 1.2) for lite_s in (0.05, 0.8)}
        self.assertEqual({k: (str(v.get("judge2")), v.get("judge2_by")) for k, v in got.items()},
                         {k: ("いいえ", THINK) for k in got})
        # d1-ultra が答えない：組の読みは打ち切り（3秒）まで待たず、待つ長さのあとすぐ届く（待たない報告も同じ）
        for wants in (True, False):
            info = drive(0.05, 30.0, wants)
            self.assertLess(info.get("judge2_s") or 99, 1.0, wants)

    def test_leads_answer_in_their_order(self):
        # ✅ 2026-11-05 日本時間18時台 ユーザー：「d1-ultra と Jev を同時に出すが、d1-ultra の判定が優先じゃないんですか？いい加減な記憶で決めるな！」
        # 先に出すもの（leads）は、並びの前のものが優先（先に届いた順では決めない＝同じ言葉の読みが、どちらが速く届いたかで変わらない）：
        # 後ろのものの使える答えは、前のものが使えない答え・失敗を返すまで持っておく。持っている間は、ほかの判定（Sonnet）を出さない。
        import asyncio

        from meaning_judge import LEAD_WAIT_S, first_of

        def run(d1, jev):
            started = []

            def s(name, d, val):
                async def go():
                    started.append(name)
                    await asyncio.sleep(d)
                    if val is RuntimeError:
                        raise RuntimeError(name)
                    return val
                return go

            async def main():
                won = await first_of([s("d1", *d1), s("jev", *jev), s("sonnet", 0.01, "S")], lambda g: g != "弱い", leads=(0, 1))
                return won, started
            return asyncio.run(main())
        self.assertEqual(run((LEAD_WAIT_S + 0.1, "D"), (0.01, "J")), ("D", ["d1", "jev"]))    # Jev が先でも d1-ultra（遅くても Sonnet は出さない）
        self.assertEqual(run((0.01, "D"), (0.3, "J")), ("D", ["d1", "jev"]))                  # d1-ultra が先なら Jev を待たない
        self.assertEqual(run((0.05, "弱い"), (0.01, "J")), ("J", ["d1", "jev"]))              # d1-ultra が確かでない：持っていた Jev の読み
        self.assertEqual(run((0.05, RuntimeError), (0.01, "J")), ("J", ["d1", "jev"]))        # d1-ultra が失敗：同じ
        self.assertEqual(run((0.02, "弱い"), (0.01, "弱い")), ("S", ["d1", "jev", "sonnet"]))  # どちらも使えない：Sonnet
        self.assertEqual(run((LEAD_WAIT_S + 0.1, "弱い"), (0.01, "弱い"))[1], ["d1", "jev", "sonnet"])   # 待つ長さで Sonnet も出す（今までどおり）
        # ⛔ 2026-11-06 日本時間8時台（5時56分55秒のご質問の読み直し EN-C の指摘1）：先に出すもの（d1-ultra・Jev）がどちらも 0.3秒までに確かな読みを返さず、
        # Sonnet を出したあとは、届いた順で決めていた＝d1-ultra の確かな読みが待つ長さ（2秒）の中で届いても、先に届いた Sonnet・Jev で決まった（Jev が 0.3秒の前か
        # 後かだけで、同じ言葉の答えが d1-ultra と Jev に分かれた）。優先の順は1つ：d1-ultra ＞ Jev ＞ Sonnet（✅ 本書 9-5 の (6)「d1-ultra の確かな読みを優先
        # （d1-ultra が確かでない・失敗・待つ長さに間に合わないときだけ Jev）、どちらも確かでなければ考えない Sonnet」）
        self.assertEqual(run((LEAD_WAIT_S + 0.2, "D"), (0.01, "弱い")), ("D", ["d1", "jev", "sonnet"]))  # Sonnet が先に届いても d1-ultra
        self.assertEqual(run((LEAD_WAIT_S + 0.2, "D"), (LEAD_WAIT_S + 0.1, "J")), ("D", ["d1", "jev", "sonnet"]))  # Sonnet・Jev が先でも d1-ultra
        self.assertEqual(run((LEAD_WAIT_S + 0.2, "弱い"), (LEAD_WAIT_S + 0.1, "J")), ("J", ["d1", "jev", "sonnet"]))  # d1-ultra が確かでない：Sonnet より Jev
        self.assertEqual(run((LEAD_WAIT_S + 0.2, "弱い"), (LEAD_WAIT_S + 0.1, "弱い")), ("S", ["d1", "jev", "sonnet"]))  # どちらも確かでない：Sonnet

        async def late_d1():   # d1-ultra が会話の側の待つ長さ（prefer_s）に間に合わない：持っていた Jev の読みで決める（Sonnet は出さない）
            started = []

            def s(name, d, val):
                async def go():
                    started.append(name)
                    await asyncio.sleep(d)
                    return val
                return go
            t = asyncio.get_running_loop().time()
            won = await first_of([s("d1", 1.0, "D"), s("jev", 0.01, "J"), s("sonnet", 0.01, "S")], lambda g: True, leads=(0, 1), prefer_s=0.4)
            return won, started, round(asyncio.get_running_loop().time() - t, 1)
        self.assertEqual(asyncio.run(late_d1()), ("J", ["d1", "jev"], 0.4))

    def test_recorded_seconds_decide_like_the_running_group(self):
        # 測りの数えは、記録の秒（判定ごとの答え・失敗が届くまでの秒と、使える答えか）を、本番の組と同じ1か所（meaning_judge.Race）に通して決める
        # （meaning_judge.race_recorded）。⛔ 2026-11-06 日本時間8時台（5時56分55秒のご質問の読み直し EN-C の指摘8）：測りの数え（g59_tally.cascade）は、
        # 並べた順で線から上かだけを見て、届いた秒を見ずに決めていた＝d1-ultra が確か（2.5秒）・Jev が確か（0.1秒）の行を「d1-ultra で決めた」と
        # 数えた（本番の組は、d1-ultra が会話の側の待つ長さに間に合わないので Jev で決める）
        from flowctl import Limits
        from meaning_judge import LEAD_WAIT_S, race_recorded
        inf = float("inf")

        def won(d1, jev, sonnet=(0.01, True)):
            got, at, started = race_recorded([d1, jev, sonnet], leads=(0, 1))
            return got, round(at, 3), started
        self.assertEqual(won((LEAD_WAIT_S + 0.1, True), (0.01, True)), (0, LEAD_WAIT_S + 0.1, (0, 1)))   # Jev が先でも d1-ultra（Sonnet は出さない）
        self.assertEqual(won((0.01, True), (0.3, True))[:2], (0, 0.01))                    # d1-ultra が先なら Jev を待たない
        self.assertEqual(won((0.05, False), (0.01, True))[:2], (1, 0.05))                  # d1-ultra が確かでない・失敗：持っていた Jev
        self.assertEqual(won((0.02, False), (0.01, False), (0.5, True)), (2, 0.52, (0, 1, 2)))   # どちらも使えない：その時に Sonnet を出す
        self.assertEqual(won((Limits.hold_s + 0.5, True), (0.1, True))[:2], (1, Limits.hold_s))   # d1-ultra が待つ長さに間に合わない：Jev（指摘8の行）
        self.assertEqual(won((Limits.hold_s - 0.5, True), (0.1, True))[:2], (0, Limits.hold_s - 0.5))   # 間に合えば d1-ultra
        self.assertEqual(won((0.5, True), (0.01, False), (0.01, True))[:2], (0, 0.5))      # Sonnet が先に届いても d1-ultra
        self.assertEqual(won((inf, False), (inf, False), (0.5, True))[:2], (2, Limits.hold_s))   # 先のものが答えない：Sonnet の読みを待つ長さまで持つ
        self.assertEqual(won((0.1, False), (0.1, False), (inf, False))[0], None)          # どれも答えない
        # 本番の組（first_of）と同じ1か所を通る：同じ並び・同じ秒なら、同じ番号で決める（届く秒は、実際の時計の揺れより十分に離す）
        import asyncio

        from meaning_judge import first_of

        def live(runs):
            def s(i, d, ok):
                async def go():
                    await asyncio.sleep(d)
                    return (i, ok)
                return go
            return asyncio.run(first_of([s(i, d, ok) for i, (d, ok) in enumerate(runs)], lambda g: g[1], leads=(0, 1), prefer_s=0.6))[0]
        for runs in (((0.45, True), (0.05, True), (0.05, True)), ((0.8, True), (0.05, True), (0.05, True)),
                     ((0.1, False), (0.05, False), (0.1, True)), ((0.35, False), (0.5, True), (0.05, True))):
            self.assertEqual(live(runs), race_recorded(list(runs), leads=(0, 1), prefer_s=0.6)[0], runs)

    def calling(self):
        """お呼びする段の2つの質問と、答えの意味の質問（営業部部長の岡田様をお呼びする試しの業務）。"""
        import dataclasses

        from g22_opening import BUSINESS
        from instruction import Target
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"))
        f = b.flow(play_recordings=True)
        return f, f.judge_context()[0], next(iter(f.asks_questions.values())), b.questions[0]

    def lite_and_race(self, sures, fail=(), backup=True, took=None, lite_asks=None):
        """その場の判定（3.5 Flash Lite）と2つ目の受け持ち（組）の JudgePanel。sures：判定 ⇒ 確からしさ・fail：答えずに失敗する判定・
        took：判定 ⇒ かかる秒（無ければ 0.01秒）・lite_asks：尋ねているかの質問への Flash Lite の読み（無ければほかの質問と同じ）。"""
        import asyncio

        from flowctl import ASKS_YES
        from meaning_judge import RACE, JudgePanel, OtherJudgeError, Reading
        calls = []

        def judge(name):
            async def go(q, text, asked=None, before=None):
                calls.append(name)
                await asyncio.sleep((took or {}).get(name, 0.01))
                if name in fail:
                    raise OtherJudgeError(503, "混雑")
                if name == self.LITE and lite_asks is not None and ASKS_YES in (getattr(q, "conditions", ()) or ()):
                    return Reading(lite_asks)
                return Reading("代わった人が話し始めた" if name in sures else "ご本人", sure=sures.get(name))
            return go
        panel = JudgePanel({"judge": (self.LITE, judge(self.LITE)), "judge2": tuple((n, judge(n)) for n in RACE)},
                           standin=(self.JEV, judge(self.JEV)), backup=backup)
        return panel, calls

    def test_unsure_readings_are_used_in_the_priority_order(self):
        # ⛔ 2026-11-06 日本時間13時台の見直し（判定の持ち場の A7）：確かでない読みは、届いた順の最初を使っていた（組の Reading.weak・会話の側の on_unsure）＝
        # 同じ言葉の弱い読みが、どの判定が速く届いたかで変わった。確かな読みを優先の順で決める（✅ 2026-11-05 18時42分05秒 ユーザー「d1-ultra と Jev を同時に
        # 出すが、d1-ultra の判定が優先じゃないんですか？」）のと同じ理由で、優先の順（組の並び）に並べる1か所（meaning_judge.unsure_order）
        import asyncio

        from meaning_judge import RACE, NoJudgment, unsure_order
        D1, JEV, THINK, FAST = RACE
        _, target_q, _, _ = self.calling()
        panel, _ = self.lite_and_race({D1: 0.3, JEV: 0.3}, fail=(THINK, FAST), took={D1: 0.05, JEV: 0.01})
        with self.assertRaises(NoJudgment) as e:
            asyncio.run(panel.ask("judge2", target_q, "はい。"))
        arrived = [t["model"] for t in e.exception.tried if "unsure" in t]
        self.assertEqual(arrived[:2], [JEV, D1])                                         # 届いたのは Jev が先
        self.assertEqual([t["model"] for t in e.exception.unsure][:2], [D1, JEV])       # 使う順は d1-ultra が先
        self.assertEqual(unsure_order(e.exception.tried, RACE), e.exception.unsure)

    def test_unsure_leans_reach_the_flow_whole_on_either_path(self):
        # ⛔ 2026-11-06 日本時間23時22分41秒のご質問の見直し（判定の組の持ち場の J4）：確かでない読みの寄り（電話を終える言葉か・こちらの声が届いていない
        # 様子か）を、組が答えたとき（JudgePanel._mark）は届いた読みの全部、組が答えなかったとき（通話の側 convo の on_unsure）は優先の1つだけ渡していた＝
        # 同じ読みの組でも、通り道で決まらないときの場面が変わった（d1-ultra が「急いでいる」・Jev が「怒っている」に寄ると、通話の側は急いでいる方への伺い）。
        # 流れの制御は寄りを集まりとして使う（_end_lean＝食い違った読みも全部。怒っている・苦情に寄れば確かめずに締めて引き継ぐ＝丁寧に締める側）ので、
        # 寄りを決める1か所（meaning_judge.leans）を組と答えが無かった知らせ（NoJudgment）の両方が通り、通話の側はそのまま渡す。
        # 確かでない答えそのもの（1つ要る）は今までどおり優先の順の最初（unsure_order＝A7）
        import asyncio
        import unittest.mock as m
        from types import SimpleNamespace

        from convo import check_handler
        from flowctl import ARG_LABEL, END_ANGRY, END_HURRY, HEAR_LOST, UNDECIDED, Flow, Question
        from meaning_judge import RACE, JudgePanel, NoJudgment, Reading, unsure_order
        D1, JEV, _, _ = RACE
        tried = [{"model": JEV, "unsure": UNDECIDED, "sure": 0.5, "end": END_ANGRY},
                 {"model": D1, "unsure": UNDECIDED, "sure": 0.4, "end": END_HURRY, "hear": HEAR_LOST}]
        exc = NoJudgment(list(tried), unsure_order(tried, RACE))
        got = JudgePanel._mark(Reading(UNDECIDED), JEV, list(tried))
        self.assertEqual((set(exc.end_lean), set(exc.hear_lean)), ({END_ANGRY, END_HURRY}, {HEAR_LOST}))
        self.assertEqual((set(exc.end_lean), set(exc.hear_lean)), (set(got.end_lean), set(got.hear_lean)))
        f = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"))])
        f.use_checks("judge")

        async def judge(q, text, asked=None, before=None):
            raise NoJudgment(list(tried), unsure_order(tried, RACE))

        async def main():
            pending = []
            f.on_callee()
            handle, _, info, _ = check_handler(f, judge=judge, pcm=b"\x00\x00", rate=16000, wav="x.wav", tasks=pending, audio_at=1.0)
            f.on_heard("何回かけてくるんですか、今忙しいんで。"); f.on_activity(False, 2.0)
            out = await handle(SimpleNamespace(name="request_end", args={ARG_LABEL["reason"]: "callee_refused_call"}))
            await asyncio.wait(pending, timeout=3)
            return out
        with m.patch("stitch_gap.callee_speech", return_value=(b"", 16000, 0.0)):
            asyncio.run(main())
        self.assertEqual(f.end_leans.get(f.callee_turns), {END_ANGRY, END_HURRY})
        self.assertIn(f.callee_turns, f.hear_leans)
        self.assertEqual(f.end_reason, "callee_complaint")   # 怒っている・苦情に寄る＝確かめずに締めて引き継ぐ（急いでいる方への伺いにしない）

    def test_lite_is_stop_only_for_the_calling_questions(self):
        # ✅ 2026-10-30 ユーザー：「Flash Lite は代わりだけにする形でOKです」・同じ夜「(1)(2)ともお勧めの形でOKです」＝お呼びする段の2つの質問では、
        # その場の判定（3.5 Flash Lite）は自分で答えず、組が答えられない（止まった・時間切れ・確かな読みが無い）ときも答えにしない＝止める側だけ
        # （組が答えられないときの代わりは、同じ Sonnet の緊急の道＝下の test_emergency_route_*）。
        # ⛔ 同じ言葉に同時に出していたので、組が正しく読んでも、Flash Lite の読み1つで流れの制御が動いた（G-59 のいまの文で 213回中30回）
        # 答えの意味の質問は、F0（✅ 2026-11-07 日本時間8時57分04秒）で使わない形（止める側だけでもない＝meaning_judge.UNUSED_IN。
        # test_flash_lite_is_switched_out_of_the_answer_stage_in_one_place）
        import asyncio

        from meaning_judge import RACE, NoJudgment, stop_only, unused
        D1, JEV, THINK, FAST = RACE
        _, target_q, asks_q, answer_q = self.calling()
        self.assertEqual([stop_only(self.LITE, k) for k in ("facets", "asks", "other", "ground")], [True, True, False, False])
        self.assertEqual([unused(self.LITE, k) for k in ("facets", "asks", "other", "returned")], [False, False, True, False])
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3})
        self.assertEqual([(panel.answers("judge", q), panel.answers("judge2", q)) for q in (target_q, asks_q, answer_q)],
                         [(False, True), (False, True), (False, True)])
        self.assertEqual([panel.slot("judge").answers(q) for q in (target_q, answer_q)], [False, False])   # 会話の側が見る形（convo.answers）
        for q in (target_q, asks_q):
            panel.reset(); calls.clear()
            with self.assertRaises(NoJudgment) as e:   # 止める側だけの受け持ちは、問い合わせない（止まった判定の代わりの Jev も入れない）
                asyncio.run(panel.ask("judge", q, "はい。"))
            self.assertEqual((calls, e.exception.tried[0]["error"]), ([], "この質問では止める側だけ"))
            got = asyncio.run(panel.ask("judge2", q, "はい。"))        # 組が答えた：組の答え（Flash Lite は裏で出すだけ＝下の混んだときの備え）
            self.assertEqual((got.by, got.weak, calls.count(self.LITE)), (FAST, None, 1))
            panel.reset(); calls.clear()
            panel_d1, calls_d1 = self.lite_and_race({D1: 0.9, JEV: 0.3})
            self.assertEqual((asyncio.run(panel_d1.ask("judge2", q, "はい。")).by, self.LITE in calls_d1), (D1, False))  # 確かな読み：出さない
        # 組がどれも答えない（d1-ultra・Jev は確かでない・考えない Sonnet は止まっている）：Flash Lite の読みは答えにしない＝止める側だけの読み
        # （tried の stop_only ⇒ convo が Flow.on_unsure(…, answer=False)）。✅ 2026-10-30 夜 ユーザー：「(1)(2)ともお勧めの形でOKです」。
        # ⛔ 前は Flash Lite が組の代わりに答えていた＝その言葉で 96回中17回、流れの制御の動きが外れる（PHASE0 G-59）
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3}, fail={FAST})
        with self.assertRaises(NoJudgment) as e:
            asyncio.run(panel.ask("judge2", target_q, "はい。"))
        tried = e.exception.tried
        self.assertEqual(([t["stop_only"] for t in tried if "stop_only" in t], calls.count(self.LITE)), (["ご本人"], 1))
        self.assertEqual(sorted(t["model"] for t in tried if "unsure" in t or "error" in t), sorted([JEV, D1, FAST]))
        self.assertTrue(next(t for t in tried if t["model"] == FAST)["outage"])     # 止まった印（通話の報告の ai_trouble へ）
        self.assertIn("止める側だけの読み：ご本人", str(e.exception))
        self.assertNotIn(THINK, calls)
        # Flash Lite も止まっている：答え無し（組の確かでない読みは、今までどおり流れの制御が数える＝convo の on_unsure）
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3}, fail={FAST, self.LITE})
        with self.assertRaises(NoJudgment) as e:
            asyncio.run(panel.ask("judge2", target_q, "はい。"))
        self.assertTrue(any("unsure" in t for t in e.exception.tried))
        # 比べる試しで代わりを使わない（--no-standin）：Flash Lite は入らない
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3}, fail={FAST}, backup=False)
        with self.assertRaises(NoJudgment):
            asyncio.run(panel.ask("judge2", target_q, "はい。"))
        self.assertNotIn(self.LITE, calls)
        # 答えの意味の質問：F0 で Flash Lite は使わない（問い合わせない＝料金もかからない。UNUSED_IN）
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3})
        with self.assertRaises(NoJudgment):
            asyncio.run(panel.ask("judge", answer_q, "はい。"))
        self.assertNotIn(self.LITE, calls)
        # Flash Lite だけで測るとき（ほかの受け持ちが無い）は、お呼びする段の質問にも答える
        from meaning_judge import JudgePanel
        alone = JudgePanel({"judge": (self.LITE, panel.judges["judge"][0][1])})
        self.assertTrue(alone.answers("judge", target_q))
        self.assertEqual(asyncio.run(alone.ask("judge", target_q, "はい。")).by, self.LITE)

    def test_emergency_route_only_when_the_direct_route_is_down(self):
        # ✅ 2026-10-30 夜 ユーザー：「OpenRouter を通して Google が預かる Claudeを使うのは、会話の途中などでアンソロピックが使えなくなった緊急事態の
        # 時のみです。基本的にアンソロピックが使えなくなったりその他に使う AI のどれかが止まったら、AI の不具合として回復するまで一時停止してください。
        # ただし、どうしても使わなければいけないシーンが出たときは、契約者以上の権限で…再開することができるようにしておいてください。」
        # ＝直接が止まった（outage）ときだけ、同じ問い合わせを緊急の道へ（meaning_judge.routed_call の1か所）。止まっている間（DOWN_S）は直接を
        # 試さない。契約者以上の権限で再開した通話（emergency_first）は、はじめから緊急の道。止まったこと・緊急の道で答えたことは on_trouble へ
        import asyncio

        from meaning_judge import DOWN_S, EMERGENCY_ROUTE, JudgePanel, NoJudgment, OtherJudgeError, Reading
        now, calls, events = [0.0], [], []
        state = {"direct": None}

        def judge():
            async def direct(q, text, asked=None, before=None):
                calls.append("直接")
                if state["direct"]:
                    raise state["direct"]
                return Reading("はい")

            async def urgent(q, text, asked=None, before=None):
                calls.append("緊急")
                return Reading("いいえ")
            direct.emergency = urgent
            return direct
        panel = JudgePanel({"judge2": ((self.SONNET, judge()),)}, clock=lambda: now[0])
        panel.on_trouble = events.append

        def ask():
            calls.clear()
            got = asyncio.run(panel.ask("judge2", None, "はい。"))
            return str(got), list(calls)
        self.assertEqual(ask(), ("はい", ["直接"]))                       # ふだんは直接だけ（緊急の道は使わない）
        self.assertEqual(events, [])
        state["direct"] = OtherJudgeError(529, "混雑")
        self.assertEqual(ask(), ("いいえ", ["直接", "緊急"]))              # 通話の途中で止まった：同じ発話を緊急の道で
        self.assertEqual([(e["model"], e.get("route"), bool(e.get("outage")), bool(e.get("used"))) for e in events],
                         [(self.SONNET, None, True, False), (self.SONNET, EMERGENCY_ROUTE, False, True)])
        self.assertEqual(ask(), ("いいえ", ["緊急"]))                      # 止まっている間は、直接を試さない
        now[0] += DOWN_S + 1
        state["direct"] = None
        self.assertEqual(ask(), ("はい", ["直接"]))                       # 戻ったら直接へ
        state["direct"] = OtherJudgeError(400, "問い合わせの中身が断られた")
        with self.assertRaises(NoJudgment):
            ask()                                                           # 止まったのではない（中身の誤り）：緊急の道へは回さない
        self.assertNotIn("緊急", calls)
        state["direct"], panel.emergency_first = None, True
        self.assertEqual(ask(), ("いいえ", ["緊急"]))                      # 契約者以上の権限で再開した通話：はじめから緊急の道

    def test_grounder_shares_the_route_state_with_the_meaning_judge(self):
        # 中身の判定（grounding.make_grounder）も同じ1か所（routed_call）・同じ道の状態（RouteState）＝意味の判定で Anthropic が止まったと分かれば、
        # 中身の判定も直接を試さずに緊急の道へ（make_judges が同じものを渡す）
        import asyncio
        import unittest.mock as m

        import grounding
        from grounding import GROUNDED, Verdict
        from meaning_judge import DOWN_S, EMERGENCY_ROUTE, RouteState
        calls = []

        def reader(args, name, route=None):
            async def call(knowledge, said, draft):
                calls.append(route or "直接")
                v = Verdict(GROUNDED)
                v.by, v.sure = name, None
                return v
            return call
        st = RouteState(clock=lambda: 0.0)
        with m.patch.object(grounding, "make_reader", reader):
            ground = grounding.make_grounder(None, (self.SONNET,), state=st)
        self.assertIs(ground.state, st)
        self.assertEqual((asyncio.run(ground(["業務の情報：x"], "相手", "文")), calls), (GROUNDED, ["直接"]))
        calls.clear()
        st.down_until[self.SONNET] = DOWN_S      # 意味の判定で止まったと分かった（同じ状態）
        self.assertEqual((asyncio.run(ground(["業務の情報：x"], "相手", "文")), calls), (GROUNDED, [EMERGENCY_ROUTE]))

    def test_emergency_route_sends_the_same_request_to_openrouter_only(self):
        # 緊急の道の問い合わせは、モデルの名前のほか直接と1文字も変わらない（other_request の1か所）。送り先は OpenRouter の Anthropic と同じ形の
        # 窓口で、預け先は Google だけ（ほかへ回さない・お客様の言葉を残す預け先は使わない）。鍵は OpenRouter の鍵だけを明示して渡す
        # （⚠️ Anthropic の公式の部品は、鍵を渡さないと作業の場所の ANTHROPIC_API_KEY を読む＝使わない）。料金は同じ帳簿（_Metered）
        import asyncio
        import json

        import httpx

        from meaning_judge import (EMERGENCY, EMERGENCY_ROUTE, SPEND, _Metered, _Routed, ajudge_other, other_request)
        _, target_q, _, answer_q = self.calling()
        for name in (self.SONNET, "Claude Sonnet 5.5"):
            direct, urgent = other_request(name, answer_q, "はい。", None), other_request(name, answer_q, "はい。", None, route=EMERGENCY_ROUTE)
            self.assertEqual({k: v for k, v in urgent.items() if k != "model"}, {k: v for k, v in direct.items() if k != "model"})
            self.assertEqual((direct["model"], urgent["model"]), ("claude-sonnet-5-5", EMERGENCY["model"]))
        seen = []

        def handler(request):
            seen.append((request.url.path, dict(request.headers), json.loads(request.content)))
            return httpx.Response(200, json={"content": [{"type": "text", "text": json.dumps({"choice": "はい"}, ensure_ascii=False)}],
                                             "usage": {"input_tokens": 10, "output_tokens": 5}})
        before = SPEND.calls[EMERGENCY["model"]]

        async def go():
            http = httpx.AsyncClient(base_url=EMERGENCY["base"], transport=httpx.MockTransport(handler), headers={"authorization": "Bearer test-key"})
            return await ajudge_other(_Metered(_Routed(http, EMERGENCY), aio=True), self.SONNET, answer_q, "はい。", route=EMERGENCY_ROUTE)
        got = asyncio.run(go())
        path, headers, body = seen[0]
        self.assertEqual((str(got), path), ("はい", "/api/v1/messages"))
        self.assertEqual(body["provider"], {"only": ["google-vertex/us"], "allow_fallbacks": False, "data_collection": "deny"})
        self.assertEqual((headers.get("authorization"), "x-api-key" in headers), ("Bearer test-key", False))
        self.assertEqual(SPEND.calls[EMERGENCY["model"]], before + 1)

    def test_ai_trouble_is_one_record_per_ai_route_and_event(self):
        # 通話の報告の ai_trouble（Flow.on_ai_trouble の1か所）：止まったAI・緊急の道で答えたことを、AI・道・出来事ごとに1つにまとめて数える。
        # 会話AIの不具合で終えたとき（Flow._trouble の ai_malfunction）も入る。⚠️ 新しい電話の一時停止・再開は発信の門（CL-2）
        import inspect

        import convo
        from meaning_judge import EMERGENCY_ROUTE
        f, *_ = self.calling()
        f.on_ai_trouble({"model": self.SONNET, "error": "529", "outage": True})
        f.on_ai_trouble({"model": self.SONNET, "route": EMERGENCY_ROUTE, "used": True})
        f.on_ai_trouble({"model": self.SONNET, "route": EMERGENCY_ROUTE, "used": True})
        self.assertEqual([(t["ai"], t["route"], t["what"], t["count"]) for t in f.ai_trouble],
                         [(self.SONNET, "直接", "止まった", 1), (self.SONNET, EMERGENCY_ROUTE, "緊急の道で答えた", 2)])
        f._trouble("ai_malfunction", "張り替えても声が戻らない")
        self.assertEqual(f.ai_trouble[-1]["ai"], "会話AI")
        src = inspect.getsource(convo.run_call)
        self.assertIn("st.on_trouble, st.emergency_first = flow.on_ai_trouble, judge_route == RESUME_EMERGENCY", src)   # 通話の始めに入れ
        self.assertIn("st.on_trouble, st.emergency_first = None, False", src)                                           # 終わりに外す
        self.assertIn('"ai_trouble": flow.ai_trouble', src)

    def test_probe_asks_each_judge_once_and_names_them_like_ai_trouble(self):
        # 回復の確かめ（JudgePanel.probe・convo.check_ais）：✅ 2026-10-30 夜 ユーザー：「…AI の不具合として回復するまで一時停止してください。」
        # ＝発信の門が再開の前に呼ぶ。どの判定にも1回ずつ（2つの受け持ちにいる判定・止まった判定の代わりも1回）・名前は ai_trouble と同じ。
        # 別の耳と会話AIは、通話と同じ部品でつないで閉じるだけ（声も文字も送らない）
        import asyncio
        import unittest.mock as m
        from contextlib import asynccontextmanager

        from convo import check_ais
        from meaning_judge import RACE
        D1, JEV, THINK, FAST = RACE
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3}, fail={FAST})
        got = asyncio.run(panel.probe())
        self.assertEqual(sorted(calls), sorted([self.LITE, D1, JEV, THINK, FAST]))   # Jev は組と代わりの両方にいても1回
        self.assertEqual({g["ai"]: g["ok"] for g in got}, {self.LITE: True, D1: True, JEV: True, THINK: True, FAST: False})
        self.assertIn("混雑", next(g for g in got if g["ai"] == FAST)["error"])
        panel.forced_down = {D1}   # 試験で止めた判定（--judge-down）は、確かめでも止まっている
        self.assertFalse(next(g for g in asyncio.run(panel.probe()) if g["ai"] == D1)["ok"])

        @asynccontextmanager
        async def ear_fails(kind, client=None):
            raise ConnectionError("つながらない")
            yield

        @asynccontextmanager
        async def live_opens(client, model, cfg, closing):
            yield object()
        class Ring:   # キーの輪（common.KeyRing.acall と同じ形）：1本目は上限・2本目で通る＝確かめも、通話と同じくキーを回す
            def __init__(self):
                self.used = []

            async def acall(self, model, fn, max_wait_s=None):
                for i in (0, 1):
                    self.used.append(i)
                    if i == 0 and model:
                        continue
                    return await fn(object()), i
        ring = Ring()
        with m.patch("convo.open_ear", ear_fails), m.patch("convo.open_session", live_opens):
            got = asyncio.run(check_ais(judges=(panel,), ear_kind="soniox", ring=ring, model="gemini-3.8-live"))
        oks = {g["ai"]: g["ok"] for g in got}
        self.assertEqual((oks["別の耳（soniox）"], oks["会話AI"], oks[FAST]), (False, True, False))
        self.assertEqual(ring.used, [0, 1, 0, 1])   # 別の耳と会話AIの両方が、キーの輪を通った
        self.assertIn("つながらない", next(g for g in got if g["ai"] == "別の耳（soniox）")["error"])
        self.assertEqual(asyncio.run(check_ais()), [])   # 何も渡さなければ、何も問い合わせない

    def test_lite_runs_ahead_when_the_decision_models_are_unsure(self):
        # ✅ 2026-10-30 ユーザー：「(1)(2)ともお勧めの形でOK」＝d1-ultra と Jev がどちらも確かでないと分かった時点で、Flash Lite も裏で出しておく
        # （考えない Sonnet と同時。first_of の on_rest）。組より先に届いた Flash Lite の読みは early に知らせる（会話の側が、組の答えが待つ長さに
        # 間に合わなかったときだけ、止める側だけに使う）。組が答えたら、その答え。⛔ 前は組が答えられなかったあとにだけ出していたので、Anthropic が
        # 混んで遅いだけのときは、10秒の時間切れまで入らなかった（Intent.md 9-4 の J10b「その会社が混むと質問に気づけない」）
        import asyncio
        import time

        from meaning_judge import RACE
        D1, JEV, THINK, FAST = RACE
        _, target_q, asks_q, answer_q = self.calling()
        for q in (target_q, asks_q):
            panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3}, took={FAST: 0.2, self.LITE: 0.05})
            early = []

            async def run():
                t0 = time.monotonic()
                got = await panel.ask("judge2", q, "はい。", early=lambda r: early.append((r.by, str(r), round(time.monotonic() - t0, 2))))
                return got, round(time.monotonic() - t0, 2)
            got, took_s = asyncio.run(run())
            self.assertEqual((got.by, [e[:2] for e in early]), (FAST, [(self.LITE, "ご本人")]))   # 答えは組・Flash Lite は先に知らせるだけ
            self.assertLess(early[0][2], 0.15)
            self.assertGreaterEqual(took_s, 0.2)
        # 答えの意味の質問では、裏で出さない（Flash Lite は自分の受け持ちで答える）
        panel, calls = self.lite_and_race({D1: 0.3, JEV: 0.3})
        early = []
        self.assertEqual(asyncio.run(panel.ask("judge2", answer_q, "はい。", early=early.append)).by, THINK)   # 答えの意味は考える Sonnet だけ
        self.assertEqual((early, self.LITE in calls), ([], False))

    def test_call_does_not_ask_lite_while_calling_and_counts_the_weak_reading(self):
        # 会話の側（convo.check_handler）：お呼びする段では、止める側だけの受け持ち（その場の判定）に問い合わせない（convo.answers）。組が
        # 答えられないときの Flash Lite の読みも、組の確かでない読みも、答えが無いときと同じに数える（繋ぐのを止める側だけ＝Flow.on_unsure・Flow.doubt）。
        # ⛔ 2026-10-21 G-57 tc10：弱い「代わった人が話し始めた」を捨て、読みが2つそろったとして別の方（山田様）に繋いだ。
        # ✅ 2026-10-30 ユーザー：「(1)(2)ともお勧めの形でOK」＝組の答えが待つ長さに間に合わなければ、裏で出した Flash Lite の読みを、止める側だけに使う
        import asyncio
        import dataclasses
        import unittest.mock as m
        from types import SimpleNamespace

        from convo import check_handler
        from meaning_judge import RACE
        D1, JEV, THINK, FAST = RACE

        def drive(fail=(), took=None, lite_reads_new=False, report=False, lite_asks=None):
            f, *_ = self.calling()
            f.limits = dataclasses.replace(f.limits, hold_s=0.3)
            f.use_checks("judge", "judge2")   # 本番の通話と同じ（convo.run_call）
            sures = {D1: 0.3, JEV: 0.3} | ({self.LITE: None} if lite_reads_new else {})
            panel, calls = self.lite_and_race(sures, fail=fail, took=took, lite_asks=lite_asks)

            async def main():
                pending = []
                f.on_callee()
                handle, _, info, _ = check_handler(f, judge=panel.slot("judge"), judge2=panel.slot("judge2"), pcm=b"\x00\x00", rate=16000,
                                                   wav="x.wav", tasks=pending, audio_at=1.0)
                f.on_heard("お電話代わりました。"); f.on_activity(False, 2.0)
                out = None
                if report:
                    out = await handle(SimpleNamespace(name="report_party", args={"相手": "目的の人"}))
                await asyncio.wait(pending, timeout=3)
                return info, out
            with m.patch("stitch_gap.callee_speech", return_value=(b"", 16000, 0.0)):
                info, out = asyncio.run(main())
            return f, calls, info, out
        f, calls, info, _ = drive()
        self.assertFalse(any(k in info for k in ("judge", "asks")))          # その場の判定の受け持ちには問い合わせない
        self.assertEqual(calls.count(self.LITE), 2)                         # 組の裏で出すだけ（目的のお客様の判定・尋ねているか）
        self.assertEqual({k for k in ("judge", "judge2", "asks", "asks2") if k in f.check}, {"judge2", "asks2"})
        self.assertEqual(f.check["judge2"].by, FAST)
        self.assertEqual(f.doubt, {})
        # 組がどれも答えない（考えない Sonnet が止まった）：Flash Lite の読みは答えにしない（止める側だけ）。組の確かでない読みは、今までどおり
        # 繋ぐのを止める印。止まった考えない Sonnet は、通話の報告の ai_trouble に入る（Flow.on_ai_trouble）
        f, calls, info, _ = drive(fail={FAST})
        self.assertNotIn("judge2", f.check)
        self.assertIn({"model": self.LITE, "stop_only": "ご本人"}, info["judge2_tried"])
        self.assertIn("judge2", f.doubt)                     # 繋ぐのを止める印（判定の読みには入れない）
        # 組（考えない Sonnet）が待つ長さに間に合わない：裏の Flash Lite の「代わった人が話し始めた」を、止める側だけに使う＝AIの「目的の人」で繋がない
        f, calls, info, out = drive(took={FAST: 1.0, self.LITE: 0.02}, lite_reads_new=True, report=True)
        self.assertEqual(sorted((a["kind"], a["by"]) for a in info["ahead"]), [("asks2", self.LITE), ("judge2", self.LITE)])
        self.assertIn("judge2", f.doubt)
        self.assertNotIn("connect", f.facts)
        # 裏の Flash Lite の「尋ねている」は、答える側（聞かれたことに録音で答える）には数えない＝止める側だけ（flowctl.unsure_counts の answer）。
        # ⛔ 2026-10-30 夜：弱い読みと同じに数えていたので、AIの報告を「聞かれたことに答えて」と差し戻した（G-59 の記録：Flash Lite は、裏で出す
        #    言葉＝d1-ultra と Jev が2つとも確かでない言葉で、確かめへの「いいえ、私は山田と申します。」を3回中1回「尋ねている」と読んだ）
        f, calls, info, out = drive(took={FAST: 1.0, self.LITE: 0.02}, lite_reads_new=True, report=True, lite_asks="尋ねている")
        self.assertIn(("asks2", self.LITE), [(a["kind"], a["by"]) for a in info["ahead"]])
        self.assertEqual(out[0]["結果"], "目的の人か確かめる")   # 直す前は「差し戻し」（こちらへの質問です。聞かれたことに答えます）
        self.assertIn("judge2", f.doubt)                     # 目的のお客様の判定の読みは、今までどおり止める側に使う
        self.assertNotIn("connect", f.facts)
        # 間に合えば使わない
        f, calls, info, out = drive(took={FAST: 0.05, self.LITE: 0.02}, lite_reads_new=True, report=True)
        self.assertNotIn("ahead", info)
        self.assertNotIn("judge", f.check)

    def test_stopped_judge_is_replaced_and_skipped_for_a_while(self):
        # 止まっている（混雑の 503）：その発話は Jev が答え、DOWN_S 秒は問い合わせずに Jev へ。過ぎたら、また問い合わせる
        from meaning_judge import DOWN_S, OtherJudgeError
        panel, calls, now = self.panel(fail={self.LITE: OtherJudgeError(503, "混雑")})
        got = self.ask(panel, "judge")
        self.assertEqual((got.by, [t["model"] for t in got.tried]), (self.JEV, [self.LITE]))
        now[0] = DOWN_S - 1
        self.assertEqual(self.ask(panel, "judge").tried[0]["error"], "止まっている（前の問い合わせ）")
        self.assertEqual(calls, [self.LITE, self.JEV, self.JEV])
        now[0] = DOWN_S + 1
        self.ask(panel, "judge")
        self.assertEqual(calls[-2:], [self.LITE, self.JEV])
        # 判定の読みを言葉ごとに測る試験（G-59）は、言葉ごとに印を消す（受け持ちの仕組みは、試験の判定からたどれる）
        self.assertIs(panel.slot("judge").panel, panel)
        panel.reset()
        self.assertEqual((panel.down_until, panel.holders), ({}, {}))
        import inspect
        import g59_calling_judge
        self.assertIn(".reset()", inspect.getsource(g59_calling_judge.run))

    def test_refused_request_is_replaced_only_for_that_utterance(self):
        # 問い合わせの中身が断られた（400）：その発話だけ Jev。止まっているとはみなさない（次の発話は、また問い合わせる）
        from meaning_judge import OtherJudgeError, outage
        panel, calls, _ = self.panel(fail={self.LITE: OtherJudgeError(400, "形が違う")})
        self.assertEqual(self.ask(panel, "judge").by, self.JEV)
        self.ask(panel, "judge")
        self.assertEqual(calls, [self.LITE, self.JEV, self.LITE, self.JEV])
        self.assertFalse(outage(OtherJudgeError(400, "形が違う")))
        # 残高不足（402）も、足すまで続く止まり（⛔ 2026-10-31 の夜：中身の断りと同じに扱い、代わりも一時停止の印も付かなかった）
        self.assertTrue(all(outage(e) for e in (OtherJudgeError(429, ""), OtherJudgeError(403, ""), OtherJudgeError(402, "Insufficient credits"),
                                                 OtherJudgeError(None, ""),
                                                 TimeoutError(), RuntimeError("どのキーでも使えません"))))
        # 使用額の上限（管理者が決めた API の支払いの上限。Anthropic は中身の誤りと同じ番号 400 で返す＝2026-10-28 の実測）も、上限が戻るまで
        # 続く止まり（番号では見分けない＝返事の文 SPEND_LIMIT_TEXTS。CL-2 の errors.spend_limit と同じ文＝下の比べる試験）。⛔ 2026-11-04 まで
        # 中身の断りと読み、判定を止まったとみなさず、新しい電話を止める印も付かなかった（毎回の発話でその判定に問い合わせ、断られ続けた）
        limit = OtherJudgeError(400, "Error code: 400 - {'type': 'error', 'error': {'type': 'invalid_request_error', 'message': "
                                     "'You have reached your specified API usage limits. You will regain access on 2026-11-01 at 00:00 UTC.'}}")
        self.assertTrue(outage(limit))

    def test_spend_limit_texts_match_cl2(self):
        # 使用額の上限の返事の文（こちら meaning_judge.SPEND_LIMIT_TEXTS・CL-2 の errors.SPEND_LIMIT_TEXTS）が同じ（食い違うと、片方だけが止まりと読む）
        from meaning_judge import SPEND_LIMIT_TEXTS
        theirs = TargetTest.cl2_names("errors.py", "SPEND_LIMIT_TEXTS")
        if theirs is None:
            self.skipTest("CL-2 の errors.SPEND_LIMIT_TEXTS が、まだ main に無い")
        self.assertEqual(set(SPEND_LIMIT_TEXTS), theirs)

    def test_slow_judge_is_cut_and_replaced(self):
        # DOWN_AFTER_S 秒で打ち切り、止まっているとみなす（報告を待たせるのは2秒まで＝それより遅い判定は、その場の役に立たない）
        import unittest.mock as m
        panel, calls, _ = self.panel(took={self.LITE: 0.3})
        with m.patch("meaning_judge.DOWN_AFTER_S", 0.05):
            got = self.ask(panel, "judge")
        self.assertEqual(got.by, self.JEV)
        self.assertIn(self.LITE, panel.down_until)

    def test_standin_serves_one_slot_only(self):
        # 2社とも止まった：代わりは先に入った受け持ちだけ（同じ判定を2つの確かめに数えない）。入った受け持ちの判定が戻ったら返す
        from meaning_judge import NoJudgment, OtherJudgeError
        down = OtherJudgeError(503, "混雑")
        panel, calls, now = self.panel(fail={self.LITE: down, self.SONNET: down})
        self.assertEqual(self.ask(panel, "judge").by, self.JEV)
        self.assertIsInstance(self.ask(panel, "judge2"), NoJudgment)
        self.assertEqual(set(panel.holders.values()), {"judge"})   # 代わりの印は発話ごと（同じ発話の judge2 には入らない）
        panel.judges["judge"] = ((self.LITE, panel.standin[1]),)  # 3.5 Flash Lite が戻った（答えを返す判定に差し替え）
        now[0] = 1000
        self.ask(panel, "judge")
        self.assertEqual(panel.holders, {})
        self.assertEqual(self.ask(panel, "judge2").by, self.JEV)

    def test_unsure_standin_is_not_an_answer(self):
        # Jev の確からしさが線（0.95）より下：答えにしない（もう1つの判定で決め、通話後の検証へ）
        from meaning_judge import NoJudgment, OtherJudgeError
        panel, _, _ = self.panel(fail={self.LITE: OtherJudgeError(503, "混雑")}, sure=0.9)
        got = self.ask(panel, "judge")
        self.assertIsInstance(got, NoJudgment)
        self.assertEqual({k: v for k, v in got.tried[-1].items() if k != "s"}, {"model": self.JEV, "unsure": "はい", "sure": 0.9})
        # 受け持ちに置いたとき（検証）も同じ線で読む
        from meaning_judge import JudgePanel
        alone = JudgePanel({"judge": (self.JEV, panel.standin[1])}, clock=panel.clock)
        self.assertIsInstance(self.ask(alone, "judge"), NoJudgment)

    def test_standin_of_the_same_maker_is_not_used(self):
        # 代わりが、ほかの受け持ちと同じ会社なら使わない（止まるのも遅れるのも一緒）
        from meaning_judge import JudgePanel, maker
        noop = None
        panel = JudgePanel({"judge": (self.LITE, noop), "judge2": (self.JEV, noop)}, standin=("Claude Haiku 5.5", noop))
        self.assertIsNotNone(panel.standin)
        panel = JudgePanel({"judge": (self.LITE, noop), "judge2": (self.SONNET, noop)}, standin=("Claude Haiku 5.5", noop))
        self.assertIsNone(panel.standin)
        self.assertEqual({maker(n) for n in (self.LITE, self.SONNET, self.JEV)}, {"google", "anthropic", "typesafe"})

    def test_forced_down_goes_the_same_way(self):
        # 試験の「止まっているものとして流す」（--judge-down）は、本物の失敗と同じ道を通る
        from meaning_judge import JudgePanel
        panel, calls, _ = self.panel()
        forced = JudgePanel(panel.judges, standin=panel.standin, down=[self.SONNET], clock=panel.clock)
        self.assertEqual(self.ask(forced, "judge2").by, self.JEV)
        self.assertIn(self.SONNET, forced.down_until)
        self.assertNotIn(self.SONNET, calls)

    def race(self, took, sure=0.99, fail=None):
        """2つ目の受け持ちを組（Jev・Sonnet の考える・考えない）にした受け持ち。took：判定の名前 ⇒ かかる秒。"""
        import asyncio

        from meaning_judge import JudgePanel, Reading
        calls, now, fail = [], [0.0], fail or {}

        def judge(name):
            async def run(q, text, asked=None, before=None):
                calls.append(name)
                await asyncio.sleep(took.get(name, 0.0))
                if name in fail:
                    raise fail[name]
                return Reading("はい", sure=sure if name == self.JEV else None)
            return run
        fast = "Claude Sonnet 5.5"
        panel = JudgePanel({"judge": (self.LITE, judge(self.LITE)),
                            "judge2": tuple((n, judge(n)) for n in (self.JEV, self.SONNET, fast))},
                           standin=(self.JEV, judge(self.JEV)), clock=lambda: now[0])
        return panel, calls, now

    def test_group_slot_takes_the_first_sure_reading(self):
        # 組の受け持ち：確かな読みで決め（先に出すものの中では並びの前が優先＝first_of）、ほかの問い合わせは止める。Jev が線（0.95）より下なら、Sonnet の読みを待つ
        took = {self.JEV: 0.0, self.SONNET: 0.05, "Claude Sonnet 5.5": 0.02}
        panel, calls, _ = self.race(took)
        self.assertEqual(self.ask(panel, "judge2").by, self.JEV)
        panel, calls, _ = self.race(took, sure=0.9)
        got = self.ask(panel, "judge2")
        self.assertEqual(got.by, self.SONNET)          # 答えの意味の質問は考える Sonnet だけ（group_kinds）
        self.assertEqual([t.get("unsure") for t in got.tried], ["はい"])
        # どれも答えない：代わり（Jev）はこの受け持ちには入らない（組に Jev がいる）
        from meaning_judge import NoJudgment, OtherJudgeError
        down = OtherJudgeError(503, "混雑")
        panel, _, _ = self.race(took, sure=0.9, fail={self.SONNET: down, "Claude Sonnet 5.5": down})
        self.assertEqual(panel.serves, {"judge"})
        self.assertIsInstance(self.ask(panel, "judge2"), NoJudgment)
        # 契約者が Jev を使わないと選んだ組（2つの Sonnet）：Jev は、どちらの受け持ちが止まっても代わりに入る（✅ 2026-10-18 ユーザー）
        from meaning_judge import JudgePanel, SONNETS_NAME, members
        both = JudgePanel({"judge": (self.LITE, None), "judge2": tuple((m, None) for m in members(SONNETS_NAME))}, standin=(self.JEV, None))
        self.assertEqual(both.serves, {"judge", "judge2"})

    def test_two_slots_never_answer_from_one_maker(self):
        # 1つの発話で、2つの受け持ちの答えは違う会社から：3.5 Flash Lite が止まって Jev が代わりに入ると、組からは Jev を外す（Sonnet を待つ）
        # （答えの段の質問で見るので、答えの段でその場の判定を使わない表 UNUSED_IN は空にする＝F0 の形は別の試験）
        import unittest.mock as m

        import meaning_judge as mj
        from meaning_judge import NoJudgment, OtherJudgeError, SAME_MAKER
        patcher = m.patch.object(mj, "UNUSED_IN", {})
        patcher.start()
        self.addCleanup(patcher.stop)
        down = OtherJudgeError(503, "混雑")
        took = {self.JEV: 0.0, self.SONNET: 0.03, "Claude Sonnet 5.5": 0.02}
        panel, calls, _ = self.race(took, fail={self.LITE: down})
        self.assertEqual((self.ask(panel, "judge").by, set(panel.holders.values())), (self.JEV, {"judge"}))
        got = self.ask(panel, "judge2")
        self.assertEqual(got.by, self.SONNET)          # 答えの意味の質問は考える Sonnet だけ（group_kinds）
        self.assertEqual(got.tried[0], {"model": self.JEV, "error": SAME_MAKER})
        # 先に組の Jev が答えた発話では、止まった 3.5 Flash Lite の代わりに Jev を入れない（その発話は、受け持ち1つで決める）
        panel, calls, _ = self.race(took, fail={self.LITE: down})
        self.assertEqual(self.ask(panel, "judge2").by, self.JEV)
        got = self.ask(panel, "judge")
        self.assertIsInstance(got, NoJudgment)
        self.assertEqual(got.tried[-1], {"model": self.JEV, "error": SAME_MAKER})
        # 同じ言葉の、前の発話の答え（1回の判定の打ち切りより前）は見ない
        from meaning_judge import DOWN_AFTER_S
        panel, calls, now = self.race(took, fail={self.LITE: down})
        self.ask(panel, "judge2")
        now[0] = DOWN_AFTER_S + 2
        panel.down_until.clear()
        self.assertEqual(self.ask(panel, "judge").by, self.JEV)

    def test_args_turn_on_the_standin(self):
        import argparse

        from meaning_judge import STANDIN, add_judge_args
        p = argparse.ArgumentParser()
        add_judge_args(p)
        a = p.parse_args(["--judge", "--judge2", "--judge-down", self.LITE])
        self.assertEqual((a.no_standin, a.judge_down, STANDIN), (False, [self.LITE], self.JEV))
        self.assertTrue(p.parse_args(["--no-standin"]).no_standin)


class FirstJudgmentTest(unittest.TestCase):
    """会社の違う2つの判定のうち、早く届いたほうで決める（convo.check_handler の hold・Flow.meaning_said）。待つのをやめた（Flow.on_decided）あとに
    遅れて届いたほうは、答えに当てず記録だけ（F0・2026-11-08 日本時間9時台。⛔ それまでは、遅れて届いたほうも同じ決まりで当てていた）。
    ⛔ 2026-10-19 G-57 の9回目：その場の判定（3.5 Flash Lite）だけを待ち、2秒超が328回中58回。G-61：違う会社の2つで早いほうは、遅いほうから1割 1.53秒"""

    def flow(self):
        from flowctl import Flow, Question
        f = Flow([Question("Q1", "ご予約は。", "yes_no", conditions=("はい", "いいえ"))])
        f.use_checks("judge", "judge2")
        f.on_callee()
        return f

    def test_meaning_is_what_the_arrived_judgments_agree_on(self):
        from flowctl import UNDECIDED
        f = self.flow()
        f.on_heard("はい、しています。")
        self.assertIsNone(f.meaning_said)
        f.on_check("judge2", "はい", said="はい、しています。")
        self.assertEqual(f.meaning_said, "はい")      # 先に届いたほう（2つ目の受け持ちでも）で決める
        f.on_check("judge", "はい", said="はい、しています。")
        self.assertEqual(f.meaning_said, "はい")
        f.check["judge"] = "いいえ"
        self.assertEqual(f.meaning_said, UNDECIDED)   # 届いた判定どうしが食い違う ⇒ どちらにも決めない
        self.assertTrue(f.judging)

    def drive(self, took: dict, fail=(), binding=False):
        """2つの判定（took＝受け持ち ⇒ かかる秒・fail＝答えずに失敗する受け持ち）で、出揃った言葉への報告を受ける。"""
        import asyncio
        import unittest.mock as m
        from types import SimpleNamespace

        from convo import check_handler
        f, out = self.flow(), {}

        def judge(kind):
            async def run(q, text, asked=None, before=None):
                await asyncio.sleep(took[kind])
                if kind in fail:
                    raise RuntimeError("止まっている")
                return "はい"
            return run

        async def main():
            pending = []
            handle, _, info, _ = check_handler(f, judge=judge("judge"), judge2=judge("judge2"), pcm=b"\x00\x00", rate=16000, wav="x.wav",
                                               tasks=pending, audio_at=1.0)
            f.on_heard("はい、しています。"); f.on_activity(False, 2.0)
            f.wants_checks = lambda name, args=None: True
            f.binding = lambda name, args=None: binding
            handle_call = f.handle_call
            t0 = asyncio.get_running_loop().time()
            f.handle_call = lambda fc, midway=False: (out.update(check=dict(f.check), at=asyncio.get_running_loop().time() - t0)
                                                      or handle_call(fc, midway))
            await handle(SimpleNamespace(name="record_answer", args={"質問": "Q1", "答えの種類": "はい"}))
            await asyncio.wait(pending, timeout=3)
            out["info"], out["after"] = info, dict(f.check)
        with m.patch("stitch_gap.callee_speech", return_value=(b"", 16000, 0.0)):
            asyncio.run(main())
        return f, out

    def test_report_is_decided_by_the_first_judgment(self):
        # その場の判定が遅い（1.0秒）：先に届いた2つ目（0.1秒）で決め、遅いほうは待たない。
        # F0（2026-11-08 日本時間9時台）：電話接続側が待つのをやめた時（Flow.on_decided）に決めたので、あとで届いた遅いほうは答えに当てず、記録（late_checks・
        # 受け取った答えの late）に残すだけ・届かなかった確かめに数える（⛔ F0 の前は、あとで届いた遅いほうも同じ決まりで当て直していた）
        f, out = self.drive({"judge": 1.0, "judge2": 0.1})
        self.assertEqual(set(out["check"]), {"judge2"})
        self.assertLess(out["at"], 0.6)
        self.assertEqual(out["info"]["waits"][-1]["judged"], ["judge2"])
        self.assertEqual(set(out["after"]), {"judge2"})
        self.assertEqual((f.items["Q1"].state, f.export()["Q1"]), ("accepted", "はい"))
        self.assertEqual((f.late_checks[f.callee_turns], f.taken["Q1"]["late"], f.unchecked()),
                         ({"judge": "はい"}, {"judge": "はい"}, {"Q1": ["judge"]}))

    def test_binding_report_waits_for_every_judgment(self):
        # 取り消せない報告（目的の人に繋ぐ＝Flow.binding）：待つ長さの中で、判定を全部待つ（早く届いたほうだけで繋がない）
        f, out = self.drive({"judge": 0.05, "judge2": 0.4}, binding=True)
        self.assertEqual(set(out["check"]), {"judge", "judge2"})
        self.assertTrue(out["info"]["waits"][-1]["every"])
        f, out = self.drive({"judge": 0.05, "judge2": 0.4})
        self.assertEqual(set(out["check"]), {"judge"})

    def test_failed_judgment_does_not_end_the_wait(self):
        # 先に終わったほうが答えずに失敗した：もう1つを待つ（失敗を「届いた」と数えない）
        f, out = self.drive({"judge": 0.05, "judge2": 0.3}, fail=("judge",))
        self.assertEqual(set(out["check"]), {"judge2"})
        self.assertIn("judge_error", out["info"])


class CallFactsTest(unittest.TestCase):
    """通話の事実（業務の判定＝DESIGN.md 7-1 への入力のうち、会話の側が決めるもの）を、根拠の発話つきで1か所（Flow._note）に残す。
    Intent.md 原則14：「もうかけないで」「営業はお断り」は、その場で発信禁止の申告。9-4：怒り・苦情は、弁明や約束をせず終え、人へ知らせる印。"""

    def flow(self):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ")),
                     Question("Q2", "ご希望の日時をお聞かせいただいてもよろしいでしょうか？", "datetime", conditions=("答えた",))])

    @staticmethod
    def say(f, heard, op, **args):
        f.on_callee(); f.on_heard(heard)
        return f.apply(op, args)

    def test_refused_call_is_a_do_not_call_report(self):
        from phrases import CLOSE_DECLINED
        f = self.flow()
        r = self.say(f, "営業の電話ですよね。もうかけてこないでください。", "request_end", reason="callee_refused_call")
        self.assertEqual((r["result"], r["say"], r["ack"], f.phase), ("end", CLOSE_DECLINED, "shouchi", "closing"))
        self.assertEqual([x["turn"] for x in f.facts["do_not_call"]], [1])                       # 発話の位置
        self.assertIn("もうかけてこないで", f.facts["do_not_call"][0]["said"])                      # 根拠の発話
        self.assertEqual(f.facts["end"], [{"turn": 1, "said": f.facts["do_not_call"][0]["said"], "reason": "callee_refused_call"}])
        self.assertTrue(f.hurried)
        self.assertNotIn("complaint", f.facts)
        self.assertEqual(f.irreversible_check, "none")   # 判定を使わない通話＝2つ目の判定が無い（CL-2 は録音の確かめまで保留）

    def test_complaint_is_marked_for_a_person_and_closed_without_promise(self):
        from phrases import CLOSE_DECLINED
        f = self.flow()
        self.say(f, "はい、予約しています。", "record_answer", question_id="Q1", condition_id="はい", value="予約しています")
        r = self.say(f, "何回かけてくるんですか。迷惑なんですけど。", "request_end", reason="callee_complaint")
        self.assertEqual((r["result"], r["say"], f.phase), ("end", CLOSE_DECLINED, "closing"))
        self.assertIsNone(r["ack"])                    # 締めの言い方そのものがお詫び（頭に「承知しました」を流さない）
        self.assertEqual(f.facts["complaint"][0]["turn"], 2)
        self.assertNotIn("do_not_call", f.facts)       # 苦情だけでは発信禁止にしない（7-1：人へ知らせる印は別に持つ）
        self.assertEqual(f.export(), {"Q1": "はい", "Q2": "-"})  # 取れた答えは残る

    def test_complaint_is_not_held_back_by_the_ambiguous_word_rule(self):
        # 「結構です」だけで断りにしない決まり（_ambiguous_only）は、急いでいる・断りの報告にだけ当てる（怒りは言葉が違う）
        f = self.flow()
        r = self.say(f, "結構です。", "request_end", reason="callee_complaint")
        self.assertEqual(r["result"], "end")

    def test_hurry_and_done_are_not_reports(self):
        # ✅ 2026-11-01 日本時間20時56分 ユーザー (b)：1回目の「急いでいる」は締める前に「それではまた改めてお掛けしてもよろしいでしょうか？」を伺い、
        # 2回目の「急いでいる」で締める（Flow._hurry_ask）
        f = self.flow()
        r = self.say(f, "すみません、今ちょっと忙しいんですけど。", "request_end", reason="callee_hurry")
        self.assertEqual((r["result"], r["question_id"], set(f.facts)), ("next", "H1", set()))
        self.say(f, "急いでいるので失礼します。", "request_end", reason="callee_hurry")
        self.assertEqual((set(f.facts), f.facts["end"][0]["reason"], f.hurried), ({"end"}, "callee_hurry", True))
        f = self.flow()
        self.say(f, "はい、予約しています。", "record_answer", question_id="Q1", condition_id="はい", value="予約しています")
        self.say(f, "15日の午後2時でお願いします。", "record_answer", question_id="Q2", condition_id="答えた", value="15日の午後2時")
        r = self.say(f, "はい。", "confirm_field", question_id="Q2", result="affirmed")
        self.assertEqual((r["result"], f.facts["end"][0]["reason"], f.hurried), ("end", "done", False))

    def test_word_alone_then_again_becomes_a_report(self):
        # 「結構です」だけ：1回目は答えとして確かめ、確かめたあとにまた言われたら断り＝発信禁止の申告（迷ったら原則14の側）
        f = self.flow()
        self.assertEqual(self.say(f, "結構です。", "request_end", reason="callee_refused_call")["result"], "rejected")
        self.assertNotIn("do_not_call", f.facts)
        f.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ", "value": "結構です"})
        self.say(f, "結構です。", "request_end", reason="callee_refused_call")
        self.assertEqual(len(f.facts["do_not_call"]), 1)

    def test_ai_sees_the_reasons_and_the_rule(self):
        from flowctl import END_LABEL, tool_declarations
        from instruction import Business, build
        decl = tool_declarations(list(self.flow().questions.values()))[0].function_declarations
        end = next(d for d in decl if d.name == "request_end")
        self.assertIn(END_LABEL["callee_complaint"], end.parameters.properties["理由"].enum)
        self.assertIn(END_LABEL["callee_complaint"], end.description)
        text = build(Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認", questions=list(self.flow().questions.values())), "S2")[1]
        self.assertIn(f"「{END_LABEL['callee_complaint']}」", text)
        self.assertIn("もうかけないで", text)

    def test_call_result_carries_the_facts(self):
        import inspect
        import convo
        self.assertIn('"facts": flow.facts', inspect.getsource(convo.run_call))


class PartyTest(unittest.TestCase):
    """相手の種別（DESIGN.md 4-3・6-2 の report_party）：人ではない相手（留守番電話・自動音声の案内・FAX）には話さずに終え、
    番号違いは決まった締めで終える。Intent.md 9-4：決まっていない場面は安全側（丁寧に終える）。留守番電話の伝言は業務設定（空なら残さない）。"""

    def flow(self, **kw):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], **kw)

    @staticmethod
    def say(f, heard, op, **args):
        f.on_callee(); f.on_heard(heard)
        return f.apply(op, args)

    def test_not_a_person_hangs_up_without_a_word(self):
        from types import SimpleNamespace
        from flowctl import PARTY_LABEL
        for party, heard in (("voicemail", "ただいま電話に出ることができません。発信音のあとにお名前とご用件をお話しください。"),
                             ("ivr", "お電話ありがとうございます。ご用件の番号を押してください。"), ("fax", "（ピー、ピー）")):
            f = self.flow()
            f.on_callee(); f.on_heard(heard)
            reply, silent = f.handle_call(SimpleNamespace(name="report_party", args={"相手": PARTY_LABEL[party]}))
            last = f.log[-1]["reply"]
            self.assertEqual((last["result"], last.get("hang_up"), last.get("say"), last.get("play"), last["ack"]),
                             ("end", True, None, None, None), party)
            self.assertTrue(silent, party)                                   # AIに話させない
            self.assertNotIn("hang_up", reply)                               # 中で使う印（電話接続側が切る）。AIには見せない
            self.assertEqual((f.facts["party"][0]["party"], f.end_reason, f.phase, f.hurried), (party, party, "closing", False))
            self.assertEqual(f.export(), {"Q1": "-"})

    def test_fax_is_known_by_its_sound(self):
        # ファクスの音は、会話AIに聞かせる前にプログラムが見分けて切る（⛔ G-57：会話AIは3本とも何も報告せずに黙った）。人の声は当たらない
        import glob
        from audio import fax_tone_seconds, is_fax_tone
        from common import HERE, read_wav_pcm16_mono
        from make_callee_samples import tone_pcm
        self.assertTrue(is_fax_tone(tone_pcm("fax"), 16000))
        voices = [p for p in sorted(glob.glob(str(HERE / "results" / "callee" / "*.wav"))) if "fax_tone" not in p]
        self.assertGreater(len(voices), 100)
        self.assertEqual([p for p in voices if fax_tone_seconds(*read_wav_pcm16_mono(p)) >= 0.2], [])
        f = self.flow()
        f.on_callee()
        r = f.on_signal("fax")
        self.assertEqual((r["result"], r.get("hang_up"), f.facts["party"][0]["by"], f.end_reason), ("end", True, "signal", "fax"))
        import inspect
        import convo
        self.assertIn("is_fax_tone(pcm, prate)", inspect.getsource(convo.run_call))

    def test_voicemail_message_is_left_only_when_the_business_sets_one(self):
        msg = "株式会社アオバ物流の佐藤です。ご予約の確認でお電話いたしました。改めてお電話いたします。"
        f = self.flow(voicemail_message=msg)
        r = self.say(f, "ただいま電話に出ることができません。", "report_party", party="voicemail")
        self.assertEqual((r["result"], r["say"], r.get("hang_up")), ("end", msg, None))
        # 録音で流す形：設定の伝言は依頼主の単位の録音（名乗りの部分 voicemail。✅ 2026-10-19 ユーザー：「依頼者ごとに設定で選べる形にして、
        # 必要なら録音をしましょう」）を流し、AIは黙る
        from instruction import Business
        b = Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認", questions=list(self.flow().questions.values()),
                     voicemail_message=msg)
        self.assertEqual(b.replay_parts()["voicemail"], msg)
        self.assertNotIn("voicemail", Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認",
                                               questions=list(self.flow().questions.values())).replay_parts())  # 設定が無ければ録音も無い
        f = self.flow(voicemail_message=msg, play_recordings=True, opening=b.replay_parts())
        r = self.say(f, "ただいま電話に出ることができません。", "report_party", party="voicemail")
        self.assertEqual(r["play"], [{"kind": "opening", "part": "voicemail", "text": msg}])
        self.assertEqual(f.end_reason, "voicemail")
        # 残した事実（CL-2 の 4-106）は、伝言の録音を最後まで流し終えてから（CL-2 の 4-167 の頼み6：途中で切れたら残していない）
        self.assertIsNone(f.facts.get("voicemail_message"))
        f.on_played([msg])
        self.assertEqual(f.facts["voicemail_message"], [{"turn": 1, "said": "ただいま電話に出ることができません。"}])
        # ✅ 2026-10-19 ユーザー：「留守番電話に入れるのは最初の1回だけ」＝この依頼者が、このお客様にもう残していたら、何も言わずに切る
        f = self.flow(voicemail_message=msg, play_recordings=True, opening=b.replay_parts(), voicemail_left=True)
        r = self.say(f, "ただいま電話に出ることができません。", "report_party", party="voicemail")
        self.assertEqual((r["result"], r.get("hang_up"), "play" in r, f.facts.get("voicemail_message")), ("end", True, False, None))

    def test_wrong_party_closes_politely(self):
        from phrases import CLOSE_DECLINED
        f = self.flow()
        r = self.say(f, "え、うちは山田ですけど、番号をお間違えではないですか？", "report_party", party="wrong_party")
        self.assertEqual((r["result"], r["say"], r["ack"], f.end_reason, f.hurried), ("end", CLOSE_DECLINED, None, "wrong_party", False))
        self.assertEqual(f.irreversible_check, "none")   # 番号違いは会話AIの報告だけで決まる＝録音の確かめまで保留（10-30 (6)）
        self.assertIn("番号をお間違え", f.facts["party"][0]["said"])

    def test_people_are_noted_and_the_flow_goes_on(self):
        # 受付・目的の人：いまは記録だけ（目的の人に繋がってから質問を始める流れは、目的の人のある業務で使う）
        f = self.flow()
        r = self.say(f, "はい、株式会社アオバでございます。", "report_party", party="reception")
        self.assertEqual((r["result"], f.current, f.phase), ("noted", "Q1", "asking"))
        self.assertIn("Q1", r["message"])

    def test_ai_sees_the_operation_and_the_rule(self):
        from flowctl import PARTY_LABEL, tool_declarations
        from instruction import Business, build
        qs = list(self.flow().questions.values())
        d = next(d for d in tool_declarations(qs)[0].function_declarations if d.name == "report_party")
        self.assertEqual(d.parameters.properties["相手"].enum,
                         [PARTY_LABEL[k] for k in ("person", "voicemail", "ivr", "fax", "wrong_party")])  # 目的の人の無い業務では、受付・目的の人は見せない
        # （「電話に出た方（人）」は、どの業務にも＝第一声で人と分かったら知らせる。CL-1.md 4-45）
        text = build(Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認", questions=qs), "S2")[1]
        self.assertIn("report_party", text)
        self.assertIn("何も言わずに", text)


class CallbackTest(unittest.TestCase):
    """かけ直しの申し出（DESIGN.md 6-2 の request_callback）：理由ごとにシステムが足す質問を、ふつうの質問と同じ流れ（言い直して確かめる）で聞き、
    取れたら締める。残りの業務の質問は聞かない（目的の人ではない・いまは話せない相手）。答えは依頼主へ渡す項目に入れず、通話の事実に残す。"""

    def flow(self, play=False):
        from flowctl import Flow, Question
        return Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ")),
                     Question("Q2", "ご希望の日時をお聞かせいただいてもよろしいでしょうか？", "datetime", conditions=("答えた",))],
                    play_recordings=play)

    @staticmethod
    def say(f, heard, op, **args):
        f.on_callee(); f.on_heard(heard)
        return f.apply(op, args)

    def test_absent_asks_when_back_and_closes(self):
        from phrases import CALLBACK_ASK, CLOSING
        f = self.flow()
        r = self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        self.assertEqual((r["result"], r["question_id"], r["question"], r["ack"]), ("next", "C1", CALLBACK_ASK["back_time"], "shouchi"))
        r = self.say(f, "3時ごろには戻ると思います。", "record_answer", question_id="C1", condition_id="答えた", value="3時ごろ")
        self.assertEqual((r["result"], r["value"]), ("confirm_required", "午後3時ごろ"))   # 時刻はほかの値と同じく言い直して確かめる
        r = self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertEqual((r["result"], r["say"], f.end_reason), ("end", CLOSING, "callback"))  # 残りの Q2 は聞かない
        self.assertEqual(f.facts["callback"], [{"turn": 1, "said": "あいにく本人は出かけておりまして。", "why": "absent", "read": ["ai"],
                                                "time": "午後3時ごろ", "number": None}])
        self.assertEqual(f.export(), {"Q1": "-", "Q2": "-"})                                  # 依頼主へ渡す項目には入れない

    def test_absent_without_a_return_time_asks_about_today(self):
        # ✅ 2026-10-24 ユーザー「まだ会話に入っていない言い方5つOK」（CL-2 の 4-140 (a)：「不在なら、出られる日時を聞き出す。聞き出せなかったら、
        # その日はかけない」）：戻る時刻が分からなければ、本日のお戻りのご予定を伺い、「いいえ」でなければ改めてお掛けしてよいかを伺う
        from phrases import CALLBACK_ASK
        f = self.flow()
        self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        r = self.say(f, "戻りの時間はちょっと分からないですね。", "record_answer", question_id="C1", condition_id="unknown")
        self.assertEqual((r["result"], r["question_id"], r["question"]), ("next", "C6", CALLBACK_ASK["back_today"]))
        r = self.say(f, "はい、今日中には戻ると思います。", "record_answer", question_id="C6", condition_id="はい")
        self.assertEqual((r["result"], r["question_id"], r["question"]), ("next", "C7", CALLBACK_ASK["call_again"]))
        r = self.say(f, "はい、お願いします。", "record_answer", question_id="C7", condition_id="はい")
        self.assertEqual((r["result"], f.end_reason), ("end", "callback"))
        self.assertEqual({k: f.facts["callback"][0].get(k) for k in ("time", "back_today", "again")}, {"time": None, "back_today": True, "again": True})
        # 本日はお戻りにならない：改めてお掛けしてよいかは伺わない（その日は改めてお掛けしない）
        f = self.flow()
        self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        self.say(f, "戻りの時間はちょっと分からないですね。", "record_answer", question_id="C1", condition_id="unknown")
        r = self.say(f, "いえ、今日はもう戻らないです。", "record_answer", question_id="C6", condition_id="いいえ")
        self.assertEqual((r["result"], f.end_reason), ("end", "callback"))
        self.assertEqual({k: f.facts["callback"][0].get(k) for k in ("back_today", "again")}, {"back_today": False, "again": False})
        # 戻る時刻が分かれば、伺わない（今までどおり）
        f = self.flow()
        self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        self.say(f, "3時ごろには戻ると思います。", "record_answer", question_id="C1", condition_id="答えた", value="3時ごろ")
        r = self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertEqual((r["result"], "back_today" in f.facts["callback"][0]), ("end", False))

    def test_later_until_keeps_the_reason(self):
        # ✅ 2026-10-23 ユーザー（CL-2 の 4-149）・2026-10-24「進めてよい」：「あとで」のかけ直しの「〇時まで」は、いま電話を続けられない理由で
        # かけてよい時間が決まる。理由が相手の言葉にあれば記録し、無ければ承認済みの時刻の問いで1回だけ伺い直す（そのあとは、そのまま受け取る）
        from phrases import CALLBACK_ASK
        f = self.flow()
        self.say(f, "今ちょっと手が離せなくて、あとでかけてもらえますか。", "request_callback", why="later")
        r = self.say(f, "3時までに担当に確認しておきますので。", "record_answer", question_id="C1", condition_id="答えた", value="3時まで",
                     until_why="preparing")
        self.assertEqual(r["result"], "confirm_required")
        self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertEqual((f.end_reason, f.facts["callback"][0].get("until_why")), ("callback", "preparing"))
        # 「〇日まで」も同じ（CL-2 の 4-155：「来月の5日までに」も、いま電話を続けられなかった理由で、かけてよい日が決まる）
        f = self.flow()
        self.say(f, "今ちょっと立て込んでいて、あとにしてもらえますか。", "request_callback", why="later")
        self.say(f, "来月の5日までに社内で決めておきますので。", "record_answer", question_id="C1", condition_id="答えた", value="来月の5日までに",
                 until_why="preparing")
        self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertEqual(f.facts["callback"][0].get("until_why"), "preparing")
        # 理由が無い：1回だけ伺い直す。一言は、その質問を伺ったときと同じ（答えの段＝「いつ頃おかけ直しさせていただきましょうか？」・お呼びする段＝10-19 の一言。
        # 録音も同じ）。⛔ 2026-11-06 日本時間7時台（5時56分55秒のご質問の読み直し EN-A の指摘5）：答えの段でも、お呼びする段の一言（録音 callback_later_time）で
        # 伺い直していた（✅ 2026-11-06 日本時間0時44分31秒「(イ) 答えの段のかけ直しすべてで大丈夫」＝お伺いしたときの説明「答えの段では使わなくなります」）
        from phrases import CALLBACK_ASK_ANSWERING
        f = self.flow()
        self.say(f, "今ちょっと手が離せなくて、あとでかけてもらえますか。", "request_callback", why="later")
        r = self.say(f, "3時までなら大丈夫です。", "record_answer", question_id="C1", condition_id="答えた", value="3時までなら")
        self.assertEqual((r["result"], r.get("say"), r["ask_reason"]), ("ask_back", CALLBACK_ASK_ANSWERING["later_time"], "until"))
        g = self.flow(play=True)
        self.say(g, "今ちょっと手が離せなくて、あとでかけてもらえますか。", "request_callback", why="later")
        r2 = self.say(g, "3時までなら大丈夫です。", "record_answer", question_id="C1", condition_id="答えた", value="3時までなら")
        self.assertEqual([(x["id"], x["text"]) for x in r2["play"]], [("callback_later_time_answering", CALLBACK_ASK_ANSWERING["later_time"])])
        for play in (False, True):
            h, _ = TargetTest("test_opening_ends_with_the_call_and_no_question_until_connected").flow(play=play)
            first = self.say(h, "岡田はいま手が離せないので、あとでかけていただけますか。", "request_callback", why="later")
            r3 = self.say(h, "3時までなら大丈夫です。", "record_answer", question_id="C1", condition_id="答えた", value="3時までなら")
            self.assertEqual((h.asking_reception, r3["ask_reason"]), (True, "until"), play)   # 繋ぐ前の受付の方に伺っている（お呼びする段のかけ直し）
            self.assertIn(CALLBACK_ASK["later_time"], str(first), play)                          # 最初の伺いと同じ一言
            if play:
                self.assertEqual([(x["id"], x["text"]) for x in r3["play"]], [("callback_later_time", CALLBACK_ASK["later_time"])])
            else:
                self.assertEqual(r3.get("say"), CALLBACK_ASK["later_time"])
        r = self.say(f, "ですから3時までなら。", "record_answer", question_id="C1", condition_id="答えた", value="3時までなら")
        self.assertEqual(r["result"], "confirm_required")                                         # 二度は伺わない
        self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertNotIn("until_why", f.facts["callback"][0])                                     # 分からないまま（CL-2 が確かめの要る時刻として扱う）
        # ⛔ CL-2 の 4-182 の (3)：「3時前なら」も「3時まで」と同じ（CL-2 の時刻の読みと同じ）＝理由を伺い直す。「3時前後」は「3時ごろ」＝伺わない
        for said, value, asked in (("3時前なら大丈夫です。", "3時前なら", True), ("3時前後なら大丈夫です。", "3時前後", False)):
            f = self.flow()
            self.say(f, "今ちょっと手が離せなくて、あとでかけてもらえますか。", "request_callback", why="later")
            r = self.say(f, said, "record_answer", question_id="C1", condition_id="答えた", value=value)
            self.assertEqual(r.get("ask_reason") == "until", asked, said)
        # 不在の「〇時まで」は、理由（不在＝それまでは出られない）が決める：伺い直さない
        f = self.flow()
        self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        r = self.say(f, "3時までには戻ると思います。", "record_answer", question_id="C1", condition_id="答えた", value="3時まで")
        self.assertEqual(r["result"], "confirm_required")

    def test_person_who_knows_gets_the_original_question(self):
        # 「分かる者に代わります」と取り次がれたら、代わった方に元の質問を伺い直す（CL-2 の 15-2-3 の (a1)。Flow._who_took_over の1か所）。
        # ⛔ 2026-10-24 の見直し（調べ役）で見つけた穴：聞き足しを伺っている最中で、名乗りの録音があり、流し直しが残っているときだけ戻していた
        from flowctl import Flow, Question
        h = {("dont_know", "not_in_charge"): "ask_who"}
        qs = lambda: [Question("Q1", "ご予算はおいくらほどでしょうか？", "amount", conditions=("答えた",), handlings=h),
                      Question("Q2", "ご導入の時期はお決まりでしょうか？", "yes_no", conditions=("はい", "いいえ"))]
        op = {"greeting": "お忙しいところ恐れ入ります。", "intro": "株式会社アオバ物流の佐藤と申します。", "purpose": "ご予算の件でお電話いたしました。"}
        played = lambda r: [p.get("part", p.get("id")) for p in r.get("play", [])]
        # (1) お名前の言い直しの返事待ちのまま取り次がれた：言い直しを代わった方に言わせない（⛔ 前は、そのあとの報告で止まった）
        f = Flow(qs(), opening=op, play_recordings=True)
        self.say(f, "担当じゃないので分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        self.say(f, "経理の山田なら分かります。少々お待ちください、代わります。", "record_answer", question_id="C8", condition_id="答えた", value="経理の山田")
        r = self.say(f, "お電話代わりました、山田です。", "replay_opening", part="handover")
        self.assertEqual((r["result"], f.current, f.awaiting_confirm, played(r)), ("replayed", "Q1", None, ["greeting", "intro", "purpose", "Q1"]))
        self.assertEqual(self.say(f, "50万円くらいですね。", "record_answer", question_id="Q1", condition_id="答えた", value="50万円")["result"],
                         "confirm_required")
        # (2) 代わった方も「わからない」：分かる方は、もう伺わない（1通話1回）
        f = Flow(qs(), opening=op, play_recordings=True)
        self.say(f, "担当じゃないので分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        self.say(f, "分かる者に代わりますね。", "replay_opening", part="handover")
        r = self.say(f, "私も担当ではないので分からないですね。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        self.assertEqual((r["result"], r["question_id"]), ("next", "Q2"))
        # (3) お名前を伺い終えて次の質問へ進んでいた：元の質問へ戻り、いま聞いていた質問はそのあと（お名前の記録は、言われたことの記録として残す）
        f = Flow(qs(), opening=op, play_recordings=True)
        self.say(f, "担当じゃないので分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        self.say(f, "経理の山田なら分かります。", "record_answer", question_id="C8", condition_id="答えた", value="経理の山田")
        self.assertEqual(self.say(f, "はい、いま代わりますね。", "confirm_field", question_id="C8", result="affirmed")["question_id"], "Q2")
        r = self.say(f, "お電話代わりました、山田です。", "replay_opening", part="handover")
        self.assertEqual((f.current, f.order, played(r), "connected" in f.facts["callback"][0]), ("Q1", ["Q2"], ["greeting", "intro", "purpose", "Q1"], False))
        # (4) 名乗りの録音が無い通話：AIが短く名乗って、元の質問を聞く（⛔ 前は差し戻し、代わった方の答えも「いまの質問ではない」で差し戻した）
        f = Flow(qs())
        self.say(f, "担当じゃないので分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        r = self.say(f, "分かる者に代わりますね。", "replay_opening", part="handover")
        self.assertEqual((r["result"], f.current), ("replayed", "Q1"))
        self.assertIn("まだ名乗っていません", r["message"])

    def test_unknown_reason_is_read_by_the_judges(self):
        # ✅ 2026-11-06 日本時間15時20分30秒 ユーザー「(3)「わからない」の理由（担当ではない・まだ決まっていない）を、いまは会話AIの報告だけで決めています。
        # 業務によっては、この理由で残りの質問を伺わずに締めます。お勧め：判定に理由も読ませます。OK」⇒ 理由は判定の読み（項目 WHY）がそろったときだけ。
        # 会話AIの理由では決めない（割れたら受け皿＝結論にしない）
        from flowctl import WHY, Flow, Question
        from meaning_judge import Reading
        h = {("dont_know", "not_in_charge"): "conclude"}

        def told(ai_why, whys, f=None, words="ちょっと分からないですね。"):
            f = f or Flow([Question("Q1", "ご予算はおいくらほどでしょうか？", "amount", conditions=("答えた",), handlings=h),
                           Question("Q2", "ご導入の時期はお決まりでしょうか？", "yes_no", conditions=("はい", "いいえ"))])
            f.use_checks("judge", "judge2")
            f.on_callee(); f.on_heard(words)
            for k, w in zip(("judge", "judge2"), whys):
                r = Reading("unknown")
                setattr(r, WHY, w)
                f.on_check(k, r)
            return f, f.apply("record_answer", {"question_id": "Q1", "condition_id": "unknown"} | ({"unknown_why": ai_why} if ai_why else {}))
        # 会話AIが「担当ではない」と報告しても、判定がそろって「まだ決まっていない」と読めば、結論として締めない（値を伺う質問の最初の「まだ決まっていない」は、
        # 1回だけ目安を伺う＝✅ 2026-11-08 日本時間2時21分15秒 ユーザー「(1)〜(4)ともイでOK」の (1)。それでも決まらなければ、理由「まだ決まっていない」で次へ）
        f, r = told("not_in_charge", ("まだ決まっていない", "まだ決まっていない"))
        self.assertEqual((r["result"], f.end_reason, f.items["Q1"].state), ("hesitate", None, "empty"))
        f, r = told("not_in_charge", ("まだ決まっていない", "まだ決まっていない"), f, "それもまだ決まってないですね。")
        self.assertEqual((f.items["Q1"].reason, f.end_reason, r.get("question_id")), ("undecided", None, "Q2"))
        # 判定がそろって「担当ではない」と読めば、会話AIが理由を言わなくても、業務の決まりどおり結論として締める
        f, r = told(None, ("担当ではない", "担当ではない"))
        self.assertEqual((f.items["Q1"].reason, r["result"]), ("not_in_charge", "end"))
        # 判定が割れたら受け皿（結論にしない）。値を伺う質問の理由の読みが割れた最初の「分からない」は、1回だけ目安を伺う（✅ 2026-11-08 日本時間3時15分04秒
        # ユーザー「(イ) 前者は、選ぶ質問の (3) と同じく、1回「おおよその目安だけでも…」を伺う形にします。：OK」。⛔ 直す前：受け皿の理由で次の質問へ）
        f, r = told("not_in_charge", ("担当ではない", "わからない理由を言わなかった"))
        self.assertEqual((r["result"], f.end_reason, f.items["Q1"].state), ("hesitate", None, "empty"))

    def test_follow_up_is_asked_in_rechecks_and_after_a_restatement(self):
        # ⛔ 2026-10-24 の見直し（調べ役）で見つけた穴2つ：(1) 締めの前の念のための確認への「担当ではないので分からない」で分かる方を足しても、
        # 伺わずに締めた (2) 言い直しへの返事で「わからない」に直されたときは理由を受け取れず、業務の決まり（分かるお客様を聞く）が当たらなかった
        from flowctl import Flow, Question
        h = {("dont_know", "not_in_charge"): "ask_who"}
        f = Flow([Question("Q1", "ご予算はおいくらほどでしょうか？", "amount", conditions=("答えた",), handlings=h)])
        while self.say(f, "えっと……", "report_unclear", question_id="Q1")["result"] != "recheck":
            pass
        r = self.say(f, "あ、それ私の担当じゃないので分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        self.assertEqual((r["result"], r["question_id"], f.end_reason), ("next", "C8", None))
        M = {"はい": "導入の予定がある", "いいえ": "導入の予定はない"}
        f = Flow([Question("Q1", "ご導入の予定はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"), meanings=M, handlings=h)])
        f.use_checks("judge")
        f.on_callee(); f.on_heard("うーん、あるんじゃないかなと思いますけど。"); f.on_check("judge", "いいえ")
        self.assertEqual(f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい"})["result"], "confirm_required")
        f.on_callee(); f.on_heard("あ、いや、私は担当じゃないので分からないです。")
        # 理由は判定が読む（✅ 2026-11-06 日本時間15時20分30秒 ユーザー「(3)…判定に理由も読ませます。OK」＝Flow._why_of。会話AIの理由だけでは決めない）
        from flowctl import WHY
        from meaning_judge import Reading
        why = Reading("unknown")
        setattr(why, WHY, "担当ではない")
        f.on_check("judge", why)
        r = f.apply("confirm_field", {"question_id": "Q1", "result": "corrected", "correction": "わからない", "unknown_why": "not_in_charge"})
        self.assertEqual((r["result"], r["question_id"], f.items["Q1"].reason), ("next", "C8", "not_in_charge"))

    def test_system_question_recordings_match_their_words(self):
        # 録音で流すシステムの質問は、録音の名前と文が同じ録音（phrases.RECORDED）を指す（電話接続側は名前で流す）。番号を伺い直す一言も
        # （⛔ 2026-10-24 の見直し（調べ役）：文だけを替え、録音の名前は「お電話番号を伺う」録音のままだった）
        import dataclasses
        from flowctl import CALLBACK_ASK, Flow, callback_question, question_play
        from g22_opening import BUSINESS
        from phrases import NUMBER_AGAIN, RECORDED
        for role in CALLBACK_ASK:
            if role == "authority" or role in ("message", "promise_again"):
                continue
            q = callback_question(role)
            p = question_play([q], q.id)
            self.assertEqual(RECORDED.get(p["id"]), p["text"], role)
        for reason in NUMBER_AGAIN:
            b = dataclasses.replace(BUSINESS, number_again=reason)
            f = Flow(b.questions, number_again=reason, play_recordings=True)
            p = question_play(list(f.questions.values()), "C2")
            self.assertEqual((p["id"], RECORDED.get(p["id"])), (f"number_again_{reason}", p["text"]), reason)

    def test_callback_record_is_built_in_one_place(self):
        # ⛔ 2026-10-24 の見直し（調べ役）で見つけた穴：かけ直しの記録の項目を、伺った質問の役目の名前から作っていた（Flow._callback_fields の1か所に）
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        # (1) 番号を伺い直す電話：人の言葉が届くまで、かけ直しの記録を書かない（留守番電話・ファクス・無言で切られた電話を「人と話した」にしない）
        b = dataclasses.replace(BUSINESS, number_again="wrong_party")
        f = Flow(b.questions, number_again=b.number_again)
        f.on_signal("fax")
        self.assertNotIn("callback", f.facts)
        f = Flow(b.questions, number_again=b.number_again)
        self.say(f, "ただいま電話に出ることができません。", "report_party", party="voicemail")
        self.assertNotIn("callback", f.facts)
        f = Flow(b.questions, number_again=b.number_again)
        f.on_line_end(ai_speaking=True)
        self.assertNotIn("callback", f.facts)
        f = Flow(b.questions, number_again=b.number_again)
        self.say(f, "あ、すみません、090-1234-5678です。", "record_answer", question_id="C2", condition_id="答えた", value="090-1234-5678")
        self.assertEqual((f.facts["callback"][0]["turn"], f.facts["callback"][0]["why"]), (1, "other_number"))   # 根拠＝人の最初の言葉
        # (2) はい／いいえの答えが取れていなければ書かない（null を書くと CL-2 が報告ごと断る）。改めてお掛けしてよいかは、伺ったら「はい」のときだけ true
        f = self.flow()
        self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        self.say(f, "戻りの時間はちょっと分からないですね。", "record_answer", question_id="C1", condition_id="unknown")
        self.assertNotIn("back_today", f.facts["callback"][0])                               # 本日のお戻りを伺ったところで切れた
        self.say(f, "ちょっと分からないですね。", "record_answer", question_id="C6", condition_id="unknown")
        self.say(f, "うーん、どうでしょう。", "record_answer", question_id="C7", condition_id="unknown")
        self.assertEqual((f.end_reason, "back_today" in f.facts["callback"][0], f.facts["callback"][0]["again"]), ("callback", False, False))
        # (3) 午前・午後を伺っても、「〇時まで」の理由は消えない（もう一度伺わない）
        f = self.flow()
        self.say(f, "今ちょっと会議がありまして、あとでかけてもらえますか。", "request_callback", why="later")
        r = self.say(f, "9時まで会議なんです。", "record_answer", question_id="C1", condition_id="答えた", value="9時まで", until_why="unavailable")
        self.assertEqual(r["ask_reason"], "ampm")
        r = self.say(f, "朝です。", "record_answer", question_id="C1", condition_id="答えた", value="朝")
        self.assertEqual(r["result"], "confirm_required")
        self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertEqual(f.facts["callback"][0]["until_why"], "unavailable")
        # (4) 直されて「〇時以降」になったら、「〇時まで」の理由を書かない
        f = self.flow()
        self.say(f, "今ちょっと手が離せなくて、あとでかけてもらえますか。", "request_callback", why="later")
        self.say(f, "3時までに確認しておきます。", "record_answer", question_id="C1", condition_id="答えた", value="午後3時まで", until_why="preparing")
        self.say(f, "いえ、4時以降でお願いします。", "confirm_field", question_id="C1", result="corrected", correction="午後4時以降")
        self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
        self.assertEqual((f.facts["callback"][0]["time"], "until_why" in f.facts["callback"][0]), ("午後4時以降", False))

    def test_monthly_reason_is_kept_with_the_callback_date(self):
        # ✅ 2026-10-19 ユーザー（CL-2 の 4-106）：「月ぎめの業務の都合や振り込みなどの入金の間隔などの話の場合は、月単位で考えた方がいい」
        # ⇒ 月単位の理由でその日・頃を選んだと言われたときだけ、かけ直しの記録に cycle: month（言葉だけでは、たまたまその頃か分からない）
        for cycle, want in (("month", "month"), (None, None)):
            f = self.flow()
            self.say(f, "あいにく岡田は席を外しております。", "request_callback", why="absent")
            r = self.say(f, "月末の締めが終わってからの方がいいので、来月の5日以降にお願いします。", "record_answer", question_id="C1",
                         condition_id="答えた", value="来月の5日以降", **({"cycle": cycle} if cycle else {}))
            self.assertEqual(r["result"], "confirm_required")
            self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
            self.assertEqual(f.facts["callback"][0].get("cycle"), want, cycle)

    def test_other_number_asks_number_then_reachable_time(self):
        from phrases import CALLBACK_ASK
        f = self.flow()
        self.say(f, "はい、予約しています。", "record_answer", question_id="Q1", condition_id="はい", value="予約しています")
        r = self.say(f, "この番号じゃなくて、携帯のほうにかけてもらえますか。", "request_callback", why="other_number")
        self.assertEqual((r["question_id"], r["question"]), ("C2", CALLBACK_ASK["number"]))
        self.say(f, "090-1234-5678です。", "record_answer", question_id="C2", condition_id="答えた", value="090-1234-5678")
        r = self.say(f, "はい。", "confirm_field", question_id="C2", result="affirmed")
        self.assertEqual((r["result"], r["question_id"], r["question"]), ("next", "C1", CALLBACK_ASK["reachable_time"]))
        r = self.say(f, "ちょっとわからないです。", "record_answer", question_id="C1", condition_id="unknown")
        self.assertEqual((r["result"], f.end_reason), ("end", "callback"))                    # 出られる時間は分からなくてよい
        self.assertEqual((f.facts["callback"][0]["number"], f.facts["callback"][0]["time"]), ("090-1234-5678", None))
        self.assertEqual(f.export(), {"Q1": "はい", "Q2": "-"})

    def test_unknown_answer_follows_the_business_handling(self):
        # CL-2 の 15-2-3（業務の決まり＝理由×扱い）・✅ 2026-10-24 ユーザー（伺い方「OK」）：「わからない」の理由に、業務が「分かるお客様を聞く」
        # 「分かる時を聞く」を宣言していれば1通話1回だけ伺い、答えをかけ直しの記録（person・time）に残して残りの質問へ。「結論として終える」は丁寧に締める
        from flowctl import CLOSING, Flow, Question
        from phrases import CALLBACK_ASK
        h = {("dont_know", "not_in_charge"): "ask_who", ("dont_know", "unknown_now"): "ask_when", ("dont_know", "unspecified"): "retry"}
        qs = lambda: [Question("Q1", "ご予算はおいくらほどでしょうか？", "amount", conditions=("答えた",), handlings=h),
                      Question("Q2", "ご導入の時期はお決まりでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                               handlings={("refused", "policy"): "conclude"})]
        f = Flow(qs())
        r = self.say(f, "予算は私の担当ではないので分からないですね。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        self.assertEqual((r["question_id"], r["question"]), ("C8", CALLBACK_ASK["ask_who"]))
        self.say(f, "経理の山田なら分かると思います。", "record_answer", question_id="C8", condition_id="答えた", value="経理の山田")
        r = self.say(f, "はい。", "confirm_field", question_id="C8", result="affirmed")
        self.assertEqual(r["question_id"], "Q2")                                                    # 残りの質問へ進む
        self.assertEqual({k: f.facts["callback"][0].get(k) for k in ("why", "person", "time", "number")},
                         {"why": "ask_who", "person": "経理の山田", "time": None, "number": None})
        # 分かる時を聞く
        f = Flow(qs())
        r = self.say(f, "まだ社内で調整中で、いまは分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="unknown_now")
        self.assertEqual((r["question_id"], r["question"]), ("C9", CALLBACK_ASK["ask_when"]))
        self.say(f, "来週の水曜には決まると思います。", "record_answer", question_id="C9", condition_id="答えた", value="来週の水曜")
        self.say(f, "はい。", "confirm_field", question_id="C9", result="affirmed")
        self.assertEqual((f.facts["callback"][0]["why"], f.facts["callback"][0]["time"]), ("ask_when", "来週の水曜"))
        # 分かる時を月単位の理由で選ばれた：記録に cycle（⛔ 2026-10-24 の見直し：前は C1 だけで、C9 では捨てていた）
        f = Flow(qs())
        self.say(f, "まだ社内で調整中で、いまは分からないです。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="unknown_now")
        self.say(f, "月次の会議で決まるので、来月の5日以降ですね。", "record_answer", question_id="C9", condition_id="答えた", value="来月の5日以降",
                 cycle="month")
        self.say(f, "はい。", "confirm_field", question_id="C9", result="affirmed")
        self.assertEqual((f.facts["callback"][0]["time"], f.facts["callback"][0].get("cycle")), ("来月の5日以降", "month"))
        # 聞き足しにまた「わからない」なら重ねない・日を改める（retry）は伺わずに次へ
        f = Flow(qs())
        self.say(f, "担当じゃないので。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        r = self.say(f, "ちょっと分からないですね。", "record_answer", question_id="C8", condition_id="unknown")
        self.assertEqual((r["question_id"], f.facts.get("callback")), ("Q2", None))
        f = Flow(qs())
        r = self.say(f, "うーん、分からないです。", "record_answer", question_id="Q1", condition_id="unknown")
        self.assertEqual((r["question_id"], f.items["Q1"].reason), ("Q2", "unspecified"))
        # 結論として終える：ほかの質問は伺わずに丁寧に締める
        f = Flow(qs())
        self.say(f, "50万円くらいです。", "record_answer", question_id="Q1", condition_id="答えた", value="50万円")
        self.say(f, "はい。", "confirm_field", question_id="Q1", result="affirmed")
        r = self.say(f, "社内の決まりでお答えできないんです。", "record_answer", question_id="Q2", condition_id="refused", unknown_why="policy")
        self.assertEqual((r["result"], f.end_reason, f.items["Q2"].state), ("end", "done", "refused"))
        self.assertIn(CLOSING, r.get("say") or "".join(x["text"] for x in r.get("play", [])))
        with self.assertRaises(AssertionError):            # 「答えたくない」に使えるのは結論として終えるだけ
            Question("Q3", "x", "yes_no", conditions=("はい",), handlings={("refused", "unwilling"): "ask_who"})

    def test_ask_who_handover_reasks_the_question_to_the_new_person(self):
        # 「分かる者に代わります」と取り次がれたら、代わった方に元の質問を伺い直す（CL-2 の 15-2-3：「(a1) で取り次がれたら相手が替わる」）
        import dataclasses
        from flowctl import Flow, Question
        from g22_opening import BUSINESS
        q1 = Question("Q1", "ご予算はおいくらほどでしょうか？", "amount", conditions=("答えた",), handlings={("dont_know", "not_in_charge"): "ask_who"})
        b = dataclasses.replace(BUSINESS, questions=[q1])
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts())
        self.say(f, "私の担当ではないので。", "record_answer", question_id="Q1", condition_id="unknown", unknown_why="not_in_charge")
        f.on_callee(); f.on_heard("少々お待ちください、分かる者に代わります。")   # 取り次ぎの言葉（AIは報告せずに待つ）
        r = self.say(f, "お電話代わりました、経理の山田です。", "replay_opening", part="handover")
        self.assertEqual((f.current, f.items["Q1"].state, "C8" in f.questions), ("Q1", "empty", False))
        self.assertEqual(r["play"][-1].get("id") or r["play"][-1].get("part"), "Q1")

    def test_handover_reask_and_pending_line_only_when_final(self):
        # ⛔ 2026-11-06 日本時間13時台（ご質問「ほかに…1本化漏れはないですか？」の見直し）で見つけた2つ：
        # (1) 「担当ではないので分からない」（わからない理由＝担当ではない）にも「それではこの件は保留とさせていただきますね。」を言い、続けて分かる方を伺って
        #     いた。保留で締めるのは、決められないのがお客様の最終の決定のとき（✅ 11時19分55秒「(2) 「ちょっと今は決められないですね。」というのが最終の
        #     お客様の決定であれば…保留とさせていただきますね。」）＝担当ではない（その方の決定ではない）・業務の決まりで分かる方・分かる時を続けて伺う
        #     （まだ最終ではない）ときは締めない
        # (2) 分かる方に代わって元の質問を伺い直すとき、質問の頭が「続きまして」だった（答えの印を作り直す所で、流した印も消していた）。この電話でもう伺った
        #     質問を伺い直すので、頭は「それでは」（AGAIN_LEAD＝12時54分30秒のご指示のあとの、もう伺った質問へ戻るときの決まり）
        import dataclasses
        from flowctl import AGAIN_LEAD, Flow, Question, pending_line
        from g22_opening import BUSINESS
        q1 = Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        q2 = Question("Q2", "ご予算はおいくらほどでしょうか？", "amount", conditions=("答えた",), handlings={("dont_know", "not_in_charge"): "ask_who"})
        q3 = Question("Q3", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))
        for play in (True, False):
            b = dataclasses.replace(BUSINESS, questions=[q1, q2, q3])
            f = Flow(b.questions, play_recordings=play, opening=b.replay_parts())
            self.say(f, "はい、お願いします。", "record_answer", question_id="Q1", condition_id="はい")
            r = self.say(f, "私の担当ではないので。", "record_answer", question_id="Q2", condition_id="unknown", unknown_why="not_in_charge")
            self.assertNotIn(pending_line(q2), str(r), play)
            f.on_callee(); f.on_heard("少々お待ちください、分かる者に代わります。")
            r = self.say(f, "お電話代わりました、経理の山田です。", "replay_opening", part="handover")
            if play:
                self.assertEqual(r["play"][-1]["text"], AGAIN_LEAD + q2.text)
            else:
                self.assertIn(f"「{AGAIN_LEAD}」から話し始めてください。", r["message"])
            # 担当ではない（伺い直しの決まりの無い質問でも）は、その方の決定ではないので保留の一言を言わない
            g = Flow([q1, q3], play_recordings=play)
            self.say(g, "はい、お願いします。", "record_answer", question_id="Q1", condition_id="はい")
            r = self.say(g, "それは私では分からないです。", "record_answer", question_id="Q3", condition_id="unknown", unknown_why="not_in_charge")
            self.assertNotIn(pending_line(q3), str(r), play)
            # いまは分からない：業務の決まりで分かる時を続けて伺うなら、まだ最終の決定ではない（保留の一言は言わずに伺う）。伺わない質問なら保留で締める
            q3w = dataclasses.replace(q3, handlings={("dont_know", "unknown_now"): "ask_when"})
            for q, pending in ((q3w, False), (q3, True)):
                g = Flow([q1, q], play_recordings=play)
                self.say(g, "はい、お願いします。", "record_answer", question_id="Q1", condition_id="はい")
                r = self.say(g, "ちょっと今は分からないですね。", "record_answer", question_id="Q3", condition_id="unknown", unknown_why="unknown_now")
                self.assertEqual(pending_line(q3) in str(r), pending, (play, pending))
            # まだ決まっていない・理由を言わない（お客様の決定）は今までどおり保留で締める
            for said, why in (("まだ決めてないです。", "undecided"), ("ちょっとわからないです。", "unspecified")):
                g = Flow([q1, q3], play_recordings=play)
                self.say(g, "はい、お願いします。", "record_answer", question_id="Q1", condition_id="はい")
                r = self.say(g, said, "record_answer", question_id="Q3", condition_id="unknown", unknown_why=why)
                self.assertIn(pending_line(q3), str(r), (play, why))

    def test_number_again_call_asks_the_number_after_the_introduction(self):
        # ✅ 2026-10-24 ユーザー（CL-2 の 4-42・4-153）：前の電話で伺った番号が別の方のお電話・繋がらなかったときは、名乗りのあとに伺い直す一言で
        # 番号を伺い直す（「前回お伺いしたお電話番号に…」）。答えはかけ直しの申し出（別の番号）として残す。目的のお客様のいる業務でも、電話に出た方に伺う
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        from phrases import CALLBACK_ASK, NUMBER_AGAIN
        for reason in NUMBER_AGAIN:
            b = dataclasses.replace(BUSINESS, number_again=reason)
            self.assertEqual(b.opening_parts()[-1], NUMBER_AGAIN[reason])
            self.assertEqual(len(b.opening_parts()), 3)                                    # あいさつ・名乗り・伺い直す一言（用件・業務の質問は無い）
            f = Flow(b.questions, number_again=b.number_again)
            self.assertEqual((f.current, f.questions["C2"].text, f.callback_why), ("C2", NUMBER_AGAIN[reason], "other_number"))
            self.say(f, "あ、すみません、090-1234-5678です。", "record_answer", question_id="C2", condition_id="答えた", value="090-1234-5678")
            r = self.say(f, "はい。", "confirm_field", question_id="C2", result="affirmed")
            self.assertEqual((r["question_id"], r["question"]), ("C1", CALLBACK_ASK["reachable_time"]))
            r = self.say(f, "夕方なら出られます。", "record_answer", question_id="C1", condition_id="答えた", value="夕方")
            self.say(f, "はい。", "confirm_field", question_id="C1", result="affirmed")
            self.assertEqual((f.end_reason, f.facts["callback"][0]["why"], f.facts["callback"][0]["number"]), ("callback", "other_number", "090-1234-5678"))
            self.assertEqual(set(f.export().values()), {"-"})                               # 業務の質問は伺っていない
        from instruction import Target, build
        t = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"), number_again="wrong_party")
        self.assertEqual(t.opening_parts()[-1], NUMBER_AGAIN["wrong_party"])                 # お呼びせずに、電話に出た方に伺う
        f = Flow(t.questions, play_recordings=True, opening=t.replay_parts(), target=t.replay_parts(), number_again="wrong_party")
        self.assertEqual((f.phase, f.current), ("asking", "C2"))
        self.assertIn("最初の質問は C2 です。", build(t, "S2", opening_mode="recorded")[1])

    def test_later_time_is_asked_back_when_unclear_but_not_rechecked(self):
        from flowctl import Limits
        f = self.flow()
        self.say(f, "今ちょっと手が離せないので、あとでかけてもらえますか。", "request_callback", why="later")
        for _ in range(Limits().ask_back):
            self.assertEqual(self.say(f, "えっと……", "report_unclear", question_id="C1")["result"], "ask_back")
        r = self.say(f, "えっと……", "report_unclear", question_id="C1")
        self.assertEqual((r["result"], f.end_reason, f.facts["callback"][0]["time"]), ("end", "callback", None))  # 念のための確認はしない

    def test_resume_during_callback(self):
        # 張り替えのときの「いまの位置」：足した質問がいまの質問でも書ける（⛔ 前は業務の質問の一覧から探していて、落ちる形だった）
        from instruction import Business, position_text
        from phrases import CALLBACK_ASK
        f = self.flow()
        self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        b = Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認", questions=[f.questions["Q1"], f.questions["Q2"]])
        self.assertIn(CALLBACK_ASK["back_time"], position_text(b, f))

    def test_only_one_callback_request(self):
        f = self.flow()
        self.say(f, "あとでかけてもらえますか。", "request_callback", why="later")
        r = self.say(f, "あ、やっぱり携帯にかけてください。", "request_callback", why="other_number")
        self.assertEqual(r["result"], "rejected")
        self.assertIn("C1", r["message"])

    def test_recorded_when_questions_are_recorded(self):
        # 足す質問も、録音で流す形では共通の一言の録音を流す（つなぎの言葉は付けない）。⛔ G-57：AIに言わせると、3本中1本で
        # 「私の方では折り返しのお電話ができかねますので」と足した
        from phrases import CALLBACK_ASK, RECORDED
        f = self.flow(play=True)
        r = self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        self.assertEqual(r["play"], [{"kind": "recorded", "id": "callback_back_time", "text": CALLBACK_ASK["back_time"]}])
        self.assertEqual(RECORDED["callback_back_time"], CALLBACK_ASK["back_time"])
        # 申し出の言葉が「〜もらえますか？」でも、相手からの質問として答えさせない（⛔ G-57 の2回目：AIに答えさせて、6本中2本で
        #    「私の方では折り返しのお電話はお約束できかねます」と言い、足す質問も録音でなくAIが言った）
        for why, heard in (("later", "今ちょっと手が離せないので、あとでかけてもらえますか？"), ("other_number", "携帯のほうにかけてもらえますか？")):
            f = self.flow(play=True)
            r = self.say(f, heard, "request_callback", why=why)
            self.assertEqual(r["play"][0]["kind"], "recorded", why)
            self.assertNotIn("相手が質問をしています", r["message"], why)
        f = self.flow(play=False)                                                       # AIが話す形では AIが言う
        r = self.say(f, "あいにく本人は出かけておりまして。", "request_callback", why="absent")
        self.assertNotIn("play", r)
        self.assertIn(CALLBACK_ASK["back_time"], r["message"])

    def test_ai_sees_the_operation_and_the_questions(self):
        from flowctl import CALLBACK_LABEL, tool_declarations
        from instruction import Business, build
        qs = list(self.flow().questions.values())
        decl = {d.name: d for d in tool_declarations(qs)[0].function_declarations}
        # 目的の人の無い業務には「在籍していない」を見せない（目的の人のある業務だけ）。相手の申し出も選べる
        self.assertEqual(decl["request_callback"].parameters.properties["かけ直しの理由"].enum,
                         [v for k, v in CALLBACK_LABEL.items() if k != "departed"])
        decl_t = {d.name: d for d in tool_declarations(qs, target=True)[0].function_declarations}
        self.assertEqual(decl_t["request_callback"].parameters.properties["かけ直しの理由"].enum, list(CALLBACK_LABEL.values()))
        self.assertEqual(decl_t["request_callback"].parameters.properties["相手の申し出"].enum, ["折り返し", "伝言", "メール", "ファクス", "郵送"])
        self.assertIn("S1", decl_t["record_answer"].parameters.properties["質問"].enum)
        self.assertIn("C1", decl["record_answer"].parameters.properties["質問"].enum)
        self.assertIn("C2", decl["confirm_field"].parameters.properties["質問"].enum)
        text = build(Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認", questions=qs), "S2")[1]
        self.assertIn("request_callback", text)


class VoiceFeaturesTest(unittest.TestCase):
    """名前の録音を継ぐ位置と、名前の部分を選ぶ条件に使う声の数（voice_features。G-58 の4回目）。"""

    @staticmethod
    def pcm(x):
        import numpy as np
        return (np.clip(x, -1, 1) * 32767).astype("<i2").tobytes()

    def test_unvoiced_span_is_found_between_voiced_parts(self):
        # 声（150Hz の音）・息の音（雑音）・声 ⇒ 息の音の区間だけが、声帯の震えの無い区間（「っし」の「シ」で継ぐため）
        import numpy as np
        from voice_features import unvoiced_spans
        rate = 24000
        t = np.arange(int(0.4 * rate)) / rate
        voiced = 0.5 * np.sin(2 * np.pi * 150 * t)
        noise = 0.2 * np.random.default_rng(0).standard_normal(int(0.15 * rate))
        spans = unvoiced_spans(self.pcm(np.concatenate([voiced, noise, voiced])), rate)
        self.assertEqual(len(spans), 1, spans)
        self.assertAlmostEqual(spans[0][0], 0.4, delta=0.04)
        self.assertAlmostEqual(spans[0][1], 0.55, delta=0.04)

    def test_seam_is_in_the_breath_after_the_particle(self):
        # 名前の録音の継ぎ目（name_clips.seam_cut）：「様」の次の言葉（で）より後ろの、最初の息の音（音の重心が高い＝「し」の息）。
        # その前の、かすれた声のような低い音（⛔ 2026-10-19：「様は｜いら」の間で、音の重心 1,400〜2,600Hz）は継ぎ目にしない
        import numpy as np
        from name_clips import join, seam_cut
        rate, rng = 24000, np.random.default_rng(1)

        def tone(s):
            t = np.arange(int(s * rate)) / rate
            return 0.5 * np.sin(2 * np.pi * 150 * t)

        def noise(s, high):
            x = rng.standard_normal(int(s * rate))
            return 0.2 * (np.diff(x, prepend=0) if high else np.convolve(x, np.ones(12) / 12, "same"))
        pcm = self.pcm(np.concatenate([tone(0.6), noise(0.08, False), tone(0.25), noise(0.12, True), tone(0.4)]))
        times = [("岡田", 0.0, 0.3), ("様", 0.3, 0.45), ("で", 0.45, 0.6), ("いら", 0.68, 0.93), ("っし", 0.93, 1.05), ("ゃいます", 1.05, 1.45)]
        cut = seam_cut(pcm, rate, times)
        self.assertIsNotNone(cut)
        self.assertTrue(0.93 <= cut / rate <= 1.05, cut / rate)
        self.assertIsNone(seam_cut(pcm, rate, [("岡田", 0.0, 0.3), ("さん", 0.3, 0.6)]))   # 「様」の無い文には継ぎ目が無い
        tail = {"pcm": pcm[cut * 2:]}
        self.assertEqual(join(pcm, cut, tail), pcm)                                    # 組み合わせは、そのまま並べるだけ

    def test_loudness_difference_in_db(self):
        # 同じ音の振幅が半分なら、約6dB 小さい（継ぎ目の前の大きさの差＝g58_name_splice.MAX_SEAM_DB で比べる）
        import numpy as np
        from voice_features import loudness_db
        t = np.arange(24000) / 24000
        a, b = loudness_db(self.pcm(0.5 * np.sin(2 * np.pi * 150 * t))), loudness_db(self.pcm(0.25 * np.sin(2 * np.pi * 150 * t)))
        self.assertAlmostEqual(a - b, 6.02, delta=0.05)
        self.assertEqual(loudness_db(b""), -999.0)

    def test_join_gap_reads_only_the_periods_next_to_the_seam(self):
        # G-69 のつなぎ目の物差し（g69_vowel_seam.join_gap）：つなぎ目に接する2周期で、高さの跳ね・高さの動き・大きさ・周期のそろいを読む。
        # ⛔ 2026-10-28：高さを約44ミリ秒で読み、下がっている声の、つなぎ目の 1.22半音の跳ねを 0.0 と数えた（3回目の S2 の「の」✕）
        import numpy as np
        from g69_vowel_seam import join_gap, ma_length
        rate = 24000

        def voice(f0, s=0.3):
            t = np.arange(int(s * rate)) / rate
            ph = 2 * np.pi * np.cumsum(f0(t)) / rate
            return ph, 0.3 * np.sin(ph) + 0.2 * np.sin(2 * ph) + 0.1 * np.sin(3 * ph)

        def starts(ph):   # 1周期の始まり（位相が 2π の倍数をまたぐ所）
            return np.nonzero(np.diff(np.floor(ph / (2 * np.pi))) > 0)[0] + 1

        def near(ph, s):
            k = starts(ph)
            return int(k[np.argmin(np.abs(k - int(s * rate)))])
        ph_a, a = voice(lambda t: np.full_like(t, 200.0))
        ph_b, b = voice(lambda t: np.full_like(t, 200.0 * 2 ** (2 / 12)))
        ph_f, f = voice(lambda t: 240.0 - 300.0 * t)          # 0.13秒で 200Hz を下がって通る（1周期に約0.13半音ずつ下がる）
        A, B, F = self.pcm(a), self.pcm(b), self.pcm(f)
        ca, cb, cf = near(ph_a, 0.15), near(ph_b, 0.15), near(ph_f, 0.133)
        same = join_gap(A, ca, 120, A, ca, 120, rate)           # 切らずに続く声
        self.assertLess(same["高さの跳ね（半音）"], 0.05)
        self.assertLess(same["高さの動き（半音）"], 0.05)
        self.assertLess(same["大きさ（dB）"], 0.1)
        self.assertEqual(same["周期のずれ"], 0.0)
        step = join_gap(A, ca, 120, B, cb, int(rate / 224.5), rate)   # 高さが2半音違う声
        self.assertAlmostEqual(step["高さの跳ね（半音）"], 2.0, delta=0.3)
        self.assertLess(step["高さの動き（半音）"], 0.3)
        fall = join_gap(F, cf, 120, A, ca, 120, rate)           # 下がっている声のあとに、平らな声
        # 200Hz で 1周期に 12×log2(1−1.5/200)≒−0.13半音ずつ下がる声 × 2つの区間の真ん中どうしの間 3.4周期 ≒ 0.44半音
        self.assertAlmostEqual(fall["高さの動き（半音）"], 0.13 * 3.4, delta=0.15)
        self.assertLess(fall["高さの跳ね（半音）"], 0.3)        # 下がっている声の続きの高さでつないだので、跳ねではない
        off = join_gap(A, ca, 120, A, ca + 36, 120, rate)       # 周期の3割ずれた所でつなぐ
        self.assertGreater(off["周期のずれ"], 0.05)
        # 組んだ「ま」の長さ：名前の部分の母音の頭から 0.04秒＋続く言葉の 0.025秒＝0.065秒・続く言葉のもとは 0.05秒＝1.3倍＝半音 1.44 の重さ
        comp, w = ma_length({"vowel": (0.5, 0.58)}, int(0.54 * rate), {"vowel": (0.6, 0.65)}, int(0.625 * rate), rate)
        self.assertAlmostEqual(comp, 0.065, delta=1e-4)
        self.assertAlmostEqual(w, np.log(1.3) / np.log(1.2), delta=0.01)

    def test_jev_line_for_target_facets(self):
        # Jev の線（meaning_judge.sure_line の1か所）：目的のお客様の判定（項目ごとに答える質問）は 0.8（G-59 で半分で決め、残りの半分で数えた）・
        # ほかの質問は 0.95（G-53 で測った線）のまま
        import dataclasses
        from g22_opening import BUSINESS
        from instruction import Target
        from meaning_judge import sure_line
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"))
        f = b.flow(play_recordings=True)
        self.assertEqual(sure_line("Jev 1.14", f.judge_context()[0]), 0.8)
        self.assertEqual(sure_line("Jev 1.14", b.questions[0]), 0.95)
        self.assertIsNone(sure_line("Claude Sonnet 5.5", f.judge_context()[0]))
        # 尋ねているか（お呼びする段・確かめる一言の段の両方）も 0.8（G-59 の Jev の3回分で決めて数えた）・「待たせた方が戻ったか」は 0.6
        # （2026-10-31 の昼に G-68 で測って決めた＝returned_sure_min。✅ ユーザー：「(b) 精度が100％ならOK」。それまでは測っていないので 0.95 だった）
        self.assertEqual({sure_line("Jev 1.14", q) for q in f.asks_questions.values()}, {0.8})
        self.assertGreater(len(f.asks_questions), 1)
        self.assertEqual(sure_line("Jev 1.14", f.return_question), 0.6)
        self.assertIsNone(sure_line("Claude Sonnet 5.5", next(iter(f.asks_questions.values()))))

    def test_judges_see_names_as_written(self):
        # 判定に見せる質問の文の名前は、書いてあるとおり＋読み（instruction.Business.judge_names・flowctl.Flow.for_judge の1か所）。声で流す文は読みのまま。
        # ⛔ 2026-10-29 G-59：判定に見せる質問の文が声の形のまま（「おかだ」）で、Haiku 5.5（考えない）は「はい、岡田です。」を3回とも「決められない」と読んだ
        import dataclasses
        from g22_opening import BUSINESS
        from instruction import Target
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"))
        f = b.flow(play_recordings=True)
        self.assertEqual(f.judge_context()[0].text, "営業部部長の岡田（おかだ）様はいらっしゃいますでしょうか？")
        self.assertEqual(f.asks_context()[0].text, f.judge_context()[0].text)
        self.assertEqual(b.replay_parts()["target"], "営業部部長の「おかだ」様はいらっしゃいますでしょうか？")   # 声は読みのまま
        self.assertEqual(f.calling_question.text, b.replay_parts()["target"])   # 流れの制御の持つ質問そのものは変えない
        self.assertEqual(dataclasses.replace(b, target=Target(role="社長")).judge_names(), {})   # お名前の無い呼び方は、そのまま

    def test_judges_can_be_shown_the_target_without_the_name(self):
        # 本書 18-3 の 10-30 の (5)「案A（ただし、送らなくても正確な判定ができるなら送らない）」：お呼びする方の名前と読みを伏せた形も、判定に見せる
        # 名前の1か所（instruction.Business.judge_names）で作る＝名前を伏せる形と今の形の比べ（CL-1.md 4-165）を、測りでも本番でも同じ1か所で切り替える
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        from instruction import HIDDEN_TARGET, JUDGE_SEES_TARGET_NAME, Target
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長", full_name="岡田太郎", full_reading="おかだたろう"))
        self.assertTrue(JUDGE_SEES_TARGET_NAME)   # 決まるまでは今の形（測って、送らなくても正確なら伏せる形にする）
        self.assertEqual(b.judge_names(), b.judge_names(sees_target=True))
        hidden = b.judge_names(sees_target=False)
        f = Flow(b.questions, opening=b.replay_parts(), target=b.replay_parts(), play_recordings=True, judge_names=hidden)
        bs = dataclasses.replace(b, target=dataclasses.replace(b.target, successor=True))   # 前の電話で在籍していないと言われた方の後任をお呼びする
        fs = Flow(bs.questions, opening=bs.replay_parts(), target=bs.replay_parts(), play_recordings=True, judge_names=bs.judge_names(sees_target=False))
        shown = [f.judge_context()[0].text, f.asks_context()[0].text, f.for_judge(f.confirm_questions["target_confirm"]).text, fs.judge_context()[0].text]
        self.assertEqual(shown[0], f"営業部部長の{HIDDEN_TARGET}様はいらっしゃいますでしょうか？")
        for text in shown:   # 呼ぶ一言・尋ねているか・確かめる一言・前任の方の後任をお呼びする一言のどれにも、お名前も読みも残らない
            self.assertIn(HIDDEN_TARGET, text)
            self.assertFalse([w for w in ("岡田", "おかだ") if w in text], text)
        f._to_successor()   # 通話の中で後任の方をお呼びし直す一言（「恐れ入りますが後任のご担当者様は…」）には、もともとお名前が無い
        self.assertFalse([w for w in ("岡田", "おかだ") if w in f.judge_context()[0].text], f.judge_context()[0].text)
        self.assertEqual(b.replay_parts()["target"], "営業部部長の「おかだ」様はいらっしゃいますでしょうか？")   # 声は読みのまま
        kana = dataclasses.replace(b, target=Target(name="おかだ", reading="おかだ", role="営業部部長"))
        self.assertEqual(kana.judge_names(), {})   # ひらがなのお名前は、今の形ではそのまま
        self.assertEqual(kana.judge_names(sees_target=False), {"「おかだ」": HIDDEN_TARGET})   # 伏せる形では、ひらがなのお名前も伏せる
        self.assertEqual(dataclasses.replace(b, target=Target(role="社長")).judge_names(sees_target=False), {})   # お名前の無い呼び方は、伏せるものが無い

    def test_seam_cut_continues_the_wave_across_zero(self):
        # G-69 のつなぎ目（g69_vowel_seam.align）：続く言葉は、名前の部分と同じ向きに波が0をまたぐ所で切る＝つなぎ目の1標本の跳びが、0をまたぐ所の
        # 自然な跳びと同じ大きさになる。⛔ 2026-10-29 G-69 の8回目（「『の』のあたりでラップ音がなる」）：1周期の長さの読みが数標本ずれると、形の一番
        # 近い所が0をまたぐ所からずれ、続く言葉が山へ上がる途中から始まっていた（1標本で 13,859 の跳び）
        import numpy as np
        from g69_vowel_seam import align, pulse_cut, seam_step
        rate = 24000
        ph = 2 * np.pi * 200.0 * np.arange(int(0.3 * rate)) / rate   # 1周期 120標本・0をまたいで上がる所は1周期に1つ

        def voice(p):
            return 0.3 * np.sin(p) + 0.2 * np.sin(2 * p) + 0.1 * np.sin(3 * p)
        H = self.pcm(voice(ph))
        hc = pulse_cut(H, rate, 0.15, 1, 120)
        for shift in (1.1, 1.2):   # 同じ声の、周期の中の位置が違う録音（0をまたぐ所が、標本と標本の間の後ろ寄り・前寄り）
            T = self.pcm(voice(ph + shift))
            x = np.frombuffer(T, dtype="<i2").astype(int)
            for per in (120, 126, 114):   # 1周期の長さの読みが正しいとき・数標本ずれたとき
                cut, _ = align(H, hc, per, T, rate, 0.15)
                k = cut if x[cut - 1] < 0 <= x[cut] else cut + 1   # 続く言葉は、0をまたぐ直後か直前の標本から始まる
                self.assertTrue(x[k - 1] < 0 <= x[k], (shift, per))
                jump, natural = seam_step(H, hc, T, cut)
                # 0をまたぐ所の自然な跳び（名前の部分・続く言葉の大きいほう）と同じ大きさ（標本の間の端数の分だけ超えうる）
                self.assertLessEqual(jump, 1.1 * max(natural, abs(x[k] - x[k - 1])), (shift, per))

    def test_role_take_keeps_the_whole_pitch_rule(self):
        # 役職の録音も、録音全体の声の高さが名前の部分の録音と name_clips.MAX_ST（半音 2.4）以内のものを選ぶ（名前の部分｜続く言葉と同じ1か所＝
        # g66_role_seam.pitch_over）。⛔ 2026-10-28 G-69 の4回目：S2 の役職は 3.4半音高い録音を選び「『営業部部長の』と『岡田様』以降の声質が違う」
        import numpy as np
        from g66_role_seam import delta, over_by, pick_role, pitch_over, seam_features
        from voice_features import features
        rate = 24000

        def voice(hz, s=1.0):
            t = np.arange(int(s * rate)) / rate
            return self.pcm(0.3 * np.sin(2 * np.pi * hz * t) + 0.2 * np.sin(4 * np.pi * hz * t) + 0.1 * np.sin(6 * np.pi * hz * t))
        y = voice(150.0)
        high, near = voice(150.0 * 2 ** (5 / 12)), voice(150.0 * 2 ** (1 / 12))
        st, over = pitch_over(features(y, rate), features(high, rate))
        self.assertAlmostEqual(st, 5.0, delta=0.3)
        from name_clips import MAX_ST
        self.assertAlmostEqual(over, over_by(st, MAX_ST, 1.0))
        self.assertGreater(over, 100.0)
        self.assertEqual(pitch_over(features(y, rate), features(near, rate))[1], 0.0)
        self.assertEqual(pitch_over(None, features(y, rate)), (None, 100.0))   # 読めない録音は、ほかに無いときだけ
        fs = seam_features(y, rate, 0.0, 0.35)
        end = {"hz": 150.0, "db": fs["db"], "bright": fs["bright"]}
        target = delta(end, fs)
        # 高い録音は、つなぎ目の前後の変わり方が文まるごとにぴったりそろう（ずれ 0）が、全体の高さが5半音違う／もう1つは変わり方が半音1つずれる
        roles = [{"pcm": high, "pause": (0.5, 0.6), "end": end}, {"pcm": near, "pause": (0.5, 0.6), "end": {**end, "hz": 150.0 * 2 ** (1 / 12)}}]
        _, info = pick_role(roles, target, y, rate, 0.0, 0.0)
        self.assertEqual(info["役職の録音"], 2)
        self.assertAlmostEqual(info["全体の高さの差（半音）"], 1.0, delta=0.3)
        _, only = pick_role(roles[:1], target, y, rate, 0.0, 0.0)               # ほかに無いときは、高い録音でも選ぶ
        self.assertEqual(only["役職の録音"], 1)
        # いつもの声（通話で一緒に流す文の録音）の高さとも半音 MAX_ST 以内を選ぶ（⛔ 2026-10-29 G-69 の6回目：S2 の組の材料はどれも文の録音より
        # +3.5〜3.8半音高く、「声質がいつもと違う」）。文の録音の高さは g66_role_seam.usual_voice の1か所で読む
        import tempfile
        from pathlib import Path as _P
        from common import write_wav
        from g66_role_seam import usual_voice
        with tempfile.TemporaryDirectory() as d:
            for n, hz in enumerate((150.0, 152.0, 300.0)):
                write_wav(_P(d) / f"S9_Q{n}.wav", voice(hz), rate)
            write_wav(_P(d) / "L9_Q0.wav", voice(200.0), rate)
            ref = usual_voice("S9", _P(d))
            self.assertAlmostEqual(ref["pitch_hz"], 152.0, delta=3)                  # 中央（はずれた1本に引かれない）
            self.assertIsNone(usual_voice("X9", _P(d)))
        near_ref = pitch_over({"pitch_hz": 150.0 * 2 ** (1 / 12)}, features(near, rate))
        self.assertLess(near_ref[1], 1e-9)
        _, both = pick_role(roles, target, y, rate, 0.0, 0.0, usual={"pitch_hz": 150.0 * 2 ** (1 / 12)})
        self.assertLessEqual(both["いつもの声との高さの差（半音）"], 2.4)


class ClipTablesTest(unittest.TestCase):
    """録音を作る表（make_ack_clips）に、どの録音にも読み方と長さの上限がある（⛔ 2026-10-19 の見直しで見つけた漏れ：かけ直しの質問を
    共通の一言の録音に足したとき、読み方も上限も無く、作ると止まった）。依頼主の単位の録音には「AIですか」への言い方と伝言も入る。"""

    def test_chosen_recordings_are_usable(self):
        # 人が聞いて選んだ録音（間の確かめに通っていない＝ok は偽）も使う録音（作る道具が作り直さない・試験の通話が「無い」と止まらない）。
        # 文が変わった録音・音声の無い行は使わない（⛔ 2026-10-24 の見直し：ok だけで見ていた）
        import json
        import convo
        from make_ack_clips import OUT, usable, words
        table = words(False)[0]
        text = table["hold_timeout"][0]
        self.assertTrue(usable({"id": "hold_timeout", "text": text, "wav": "x.wav", "ok": False, "chosen_by": "人"}, table))
        self.assertTrue(usable({"id": "hold_timeout", "text": text, "wav": "x.wav", "ok": True}, table))
        self.assertFalse(usable({"id": "hold_timeout", "text": text, "wav": "x.wav", "ok": False}, table))
        self.assertFalse(usable({"id": "hold_timeout", "text": text + "。", "wav": "x.wav", "ok": True, "chosen_by": "人"}, table))
        self.assertFalse(usable({"id": "hold_timeout", "text": text, "ok": True}, table))
        chosen = next(m for m in json.loads((OUT / "index.json").read_text(encoding="utf-8"))
                      if m.get("chosen_by") == "人" and not m.get("ok") and usable(m, table))
        self.assertGreater(convo.recording_seconds(chosen["type"], chosen["id"]), 0)

    def test_misread_words_get_their_reading(self):
        # ✅ 2026-10-24 ユーザー：「『前回』を『せんかい』と言っている」＝その言葉を含むどの録音も、声のAIには読みのかなで渡す（1か所）。
        # ⛔ 1回目は指示に読みを添えただけで、半分ほどが「せんかい」のままだった
        from make_ack_clips import READ_AS, spoken_input
        from phrases import APOLOGY_FIRST, NUMBER_AGAIN
        for text in (*NUMBER_AGAIN.values(), APOLOGY_FIRST["cut_off"]):
            self.assertTrue(spoken_input(text).startswith("ぜんかい"), text)
            self.assertNotIn("前回", spoken_input(text))
        same = "恐れ入りますがいつ頃でしたらお分かりになりますでしょうか？"
        self.assertEqual((spoken_input(same), READ_AS["前回"]), (same, "ぜんかい"))

    def test_every_recording_has_a_style_and_a_limit(self):
        import dataclasses
        from g22_opening import BUSINESS
        from make_ack_clips import HOW, MAX_S, script_table, words
        from phrases import BUSY_ASK
        table = {**words(False)[0], **script_table(dataclasses.replace(BUSINESS, voicemail_message="株式会社アオバ物流の佐藤でございます。",
                                                                        answers=[("番号の出どころ", "以前ご予約の際にいただいたお電話番号です。")],
                                                                        ai_answer="どういったことでしょうか？", busy_ask=BUSY_ASK))[0]}
        from make_ack_clips import CHAR_S
        for aid, (text, how) in table.items():
            self.assertIn(how, MAX_S, aid)
            from phrases import ACK
            self.assertTrue(how in HOW or aid in ACK, aid)   # 相づちの録音は既定の読み方
            # 長い文の上限が、文の長さの見込みに届いている（⛔ 2026-10-22 の4回目：言い方を長くしたのに上限がそのままだと、作っても全部落ちる）
            if len(text) >= 15:
                self.assertLessEqual(len(text) * CHAR_S * 1.15, MAX_S[how], aid)
        self.assertIn("ai", table)                  # 業務が書いた「AIですか？」の答え（依頼主の単位）
        self.assertIn("ai_answer", table)           # 標準の答え（共通の一言＝phrases.STANDARD_PARTS）
        self.assertIn("busy", table)                # 業務で選んだ引き止めの一言（依頼主の単位）
        self.assertIn("voicemail", table)
        self.assertIn("callback_back_time", table)
        self.assertIn("callback_authority", table)  # 代わりの方に判断いただけるお立場かを聞く一言（共通の一言）
        self.assertIn("offer_thanks", table)        # 申し出へのお礼（共通の一言）
        self.assertIn("successor_call", table)      # 後任の方をお呼びする一言（共通の一言）
        self.assertIn("answer_番号の出どころ", table)

    def test_words_after_a_name_are_read_in_context(self):
        # ⛔ 2026-10-19：名前の後ろの「様はいらっしゃいますでしょうか？」だけを読むと「様」が「よう」になり、名前の入る文の録音が全部落ちた
        from make_ack_clips import heard_ok
        text = "営業部部長の「おかだ」様はいらっしゃいますでしょうか？"
        self.assertTrue(heard_ok(text, {"0.0": "営業部部長の岡田様はいらっしゃいますでしょうか？", "1.0": "営業部部長の岡田様はいらっしゃいますでしょうか？"}))
        self.assertFalse(heard_ok(text, {"0.0": "営業部部長の岡田様はいらっしゃいますか？", "1.0": "営業部部長の岡田様はいらっしゃいますか？"}))


class AIQuestionTest(unittest.TestCase):
    """「AIですか？」と聞かれたとき（Intent.md 9-4・原則8）。✅ 2026-10-19 ユーザー：「絶対にAIであることを伝えてはいけない」「人だと断定するのも
    問題がある」⇒ 1回目は決まった言い方「何か問題でもございましたでしょうか？」（業務設定 Business.ai_answer、無ければ phrases.AI_ANSWER）を
    流して相手の返事を待つ。問題は無いと言われたら「失礼いたしました。」のあと、いまの位置へ戻る。⛔ 打ち消し（「いえ」）・人だという答えは
    言わない（Intent.md 9-4「人間だとは答えない」）。重ねて聞かれたら（⏳ ユーザーに確かめる）、決まるまでは人ともAIとも言わずに丁寧に終える。
    冒頭でAIだとは名乗らない（2026-10-12 ユーザー確定）。"""

    def business(self, **kw):
        from flowctl import Question
        from instruction import Business
        return Business(company="株式会社アオバ物流", caller="佐藤", purpose="ご予約の確認",
                        questions=[Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ")),
                                   Question("Q2", "ご来店の日にちを教えていただけますでしょうか？", "date", conditions=("答えた",))], **kw)

    def flow(self, recorded=True, **kw):
        from flowctl import Flow
        b = self.business(**kw)
        return Flow(b.questions, play_recordings=recorded, opening=b.replay_parts() if recorded else None)

    def test_the_words_neither_deny_nor_tell(self):
        from phrases import AI_ANSWER
        self.assertEqual(AI_ANSWER, "何か問題でもございましたでしょうか？")                 # ✅ ユーザーの言い方のまま
        for w in ("いえ", "人間", "エーアイ", "AI", "機械", "自動"):
            self.assertNotIn(w, AI_ANSWER)
        self.assertNotIn("、", AI_ANSWER)                                             # 決まった言い方には読点を入れない（10-15）

    def test_rule_hands_the_answer_to_the_program(self):
        from flowctl import PART_LABEL
        from instruction import build
        for m in ("ai", "recorded"):
            t = build(self.business(), "S2", opening_mode=m)[1]
            self.assertIn(f"replay_opening を「{PART_LABEL['ai']}」で呼びます", t)
            self.assertIn("人間だとも、エーアイだとも、自分では言いません", t)
        mine = "どういったことでしょうか？"
        self.assertEqual(self.business(ai_answer=mine).replay_parts()["ai"], mine)
        # 業務が書かなければ、業務の録音の部分には入らない（標準は共通の一言の録音＝StandardPartsTest）
        self.assertNotIn("ai", self.business().replay_parts())

    def test_first_ask_plays_the_words_and_waits(self):
        # 決まった言い方の録音だけを流し、質問の録音は続けない（相手に聞き返したので、返事を待つ）。頭にお詫びは重ねない
        f = self.flow()
        f.on_callee()
        r = f.apply("replay_opening", {"part": "ai"})
        from phrases import STANDARD_PARTS
        self.assertEqual(([p.get("part") or p.get("id") for p in r["play"]], r["ack"], r["result"]), ([STANDARD_PARTS["ai"]], None, "ai_question"))
        self.assertEqual((f.current, f.ai_pending, [x["turn"] for x in f.facts["ai_question"]]), ("Q1", True, [1]))
        self.assertIn("質問に戻る", r["message"])

    def test_no_problem_goes_back_to_the_question(self):
        f = self.flow()
        f.on_callee()
        f.apply("replay_opening", {"part": "ai"})
        f.on_callee()                                                              # 「いや、なんか機械っぽかったので」
        r = f.apply("replay_opening", {"part": "resume"})
        self.assertEqual(([p.get("id") for p in r["play"]], r["ack"]), (["Q1"], "shitsurei"))   # 「失礼いたしました。」＋いまの質問の録音
        self.assertFalse(f.ai_pending)
        self.assertEqual(f.apply("replay_opening", {"part": "resume"})["result"], "rejected")     # 戻るのは1回だけ

    def test_resume_while_a_restatement_waits(self):
        # 言い直しの返事を待っている間に聞かれた：戻るときは、AIが言い直しをもう一度言う（録音の質問ではない）
        f = self.flow()
        f.on_callee(); f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい"})
        f.on_callee(); r = f.apply("record_answer", {"question_id": "Q2", "condition_id": "答えた", "value": "15日"})
        self.assertEqual(r["result"], "confirm_required")
        f.on_callee(); f.apply("replay_opening", {"part": "ai"})
        f.on_callee(); r = f.apply("replay_opening", {"part": "resume"})
        self.assertTrue(r.get("speak"))
        # 言い直しの頭の受けの言葉（「ありがとうございます。」＝前の答えへのお礼）は言い直さず、もう伺ったことへ戻る頭「それでは」から（B-1）
        self.assertEqual(f.awaiting_say, "ありがとうございます。15日でよろしいでしょうか？")
        self.assertIn("「それでは15日でよろしいでしょうか？」", r["message"])

    def test_an_answer_instead_ends_the_wait(self):
        f = self.flow()
        f.on_callee(); f.apply("replay_opening", {"part": "ai"})
        f.on_callee(); f.apply("record_answer", {"question_id": "Q1", "condition_id": "はい"})       # 返事の代わりに答えた
        self.assertFalse(f.ai_pending)
        self.assertEqual(f.apply("replay_opening", {"part": "resume"})["result"], "rejected")

    def test_asked_again_never_closes(self):
        # ✅ 2026-10-19 ユーザー：重ねて聞かれて終えるのは「あまりにも失礼だし、AIだと認めているのと同じ」⇒ お詫びと約束の録音のあと、いまの質問へ。
        # ✅ 同日：「2回目だろうと、3回目だろうと、相手に不信感を与えることに変わりないでしょ」⇒ 3回目からも終えない。「いかがなさいましたか？」
        #    「どうなさいましたか？」を交互に聞いて、相手の返事を待つ（1回目と同じ）
        from phrases import AI_ASKED_AGAIN, SILENCE_PROMPT
        f = self.flow()
        f.on_callee(); f.apply("replay_opening", {"part": "ai"})
        f.on_callee(); r = f.apply("replay_opening", {"part": "ai"})               # 「本当に人ですか？」
        self.assertEqual([(p["kind"], p.get("id")) for p in r["play"]], [("recorded", "ai_again"), ("question", "Q1")])
        self.assertEqual((r["play"][0]["text"], f.end_reason, f.current), (AI_ASKED_AGAIN, None, "Q1"))
        for w in ("違います", "人です", "人間", "エーアイ"):
            self.assertNotIn(w, AI_ASKED_AGAIN)
        for n, (rid, text) in enumerate([("ikaga", SILENCE_PROMPT[0]), ("dou", SILENCE_PROMPT[1]), ("ikaga", SILENCE_PROMPT[0])], 3):
            f.on_callee(); r = f.apply("replay_opening", {"part": "ai"})           # 3回目・4回目・5回目
            self.assertEqual((r["result"], [(p["kind"], p.get("id"), p["text"]) for p in r["play"]]), ("ai_question", [("recorded", rid, text)]), n)
            self.assertEqual((f.end_reason, f.ai_pending, f.current), (None, True, "Q1"), n)
            self.assertIn(f"「{text}」への、相手の返事を待っています", r["message"])
        f.on_callee(); r = f.apply("replay_opening", {"part": "resume"})           # 「いや、ちょっと気になっただけです。」
        self.assertEqual((f.end_reason, f.ai_pending, f.current), (None, False, "Q1"))
        self.assertEqual([x["turn"] for x in f.facts["ai_question"]], [1, 2, 3, 4, 5])

    def test_ai_speaking_mode_says_the_same_words(self):
        # AIが話す形（名乗りの録音が無い）でも、言い方はプログラムが渡す（AIに自分で答えさせない）
        from phrases import AI_ANSWER
        f = self.flow(recorded=False)
        f.on_callee()
        r = f.apply("replay_opening", {"part": "ai"})
        self.assertEqual((r["result"], r["say"]), ("ai_question", AI_ANSWER))
        f.on_callee()
        r = f.apply("replay_opening", {"part": "resume"})
        self.assertTrue(r.get("speak"))
        self.assertIn("Q1", r["message"])

    def test_rule_survives_a_session_swap(self):
        # 張り替えたあとのセッションにも同じ決まり（決まりは system_rules の1か所＝どのセッションの指示にも入る）
        from flowctl import Flow, PART_LABEL
        from instruction import build
        b = self.business()
        self.assertIn(f"「{PART_LABEL['ai']}」で呼びます", build(b, "S2", resume=Flow(b.questions))[1])

    def test_not_announced_at_the_start(self):
        b = self.business()
        self.assertNotIn("エーアイ", b.opening() + "".join(b.opening_parts()))


class EndJudgedTest(unittest.TestCase):
    """電話を終えるか（終わりの理由・理由を言わずに取り次げないか）は、判定AIだけが決める（Flow._end_judged の1か所）。会話AIの終わりの報告は、
    判定を待つきっかけだけ。報告が無くても、判定が電話を終える言葉と読めばプログラムが締める。判定でも決まらなければ、判定の寄りで場面を選ぶ。
    ✅ 2026-11-01 日本時間16時56分 ユーザー：「会話AIは正しい判断ができるの？できないから、別のAIを使ったんじゃないのか？」・17時04分「(a) OK、(b) OK」"""

    @staticmethod
    def R(cond, end, lean=()):
        from meaning_judge import Reading
        r = Reading(cond)
        r.end, r.end_lean = end, tuple(lean)
        return r

    def flow(self):
        from flowctl import Flow, Question
        f = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                           meanings={"はい": "パンフレットをお送りして大丈夫だということ", "いいえ": "パンフレットはお送りしなくて大丈夫だということ"},
                           doubt_words={"はい": "パンフレットをお送りした方がいい", "いいえ": "パンフレットはお送りしない方がいい"}),
                  Question("Q2", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))], play_recordings=True)
        f.use_checks("judge")
        self.assertEqual(f.current, "Q1")
        return f

    def heard(self, f, text, reading):
        f.on_callee(); f.on_heard(text); f.on_check("judge", reading)

    def test_cut_says_when_our_voice_did_not_reach(self):
        # ✅ 2026-11-02 日本時間21時16分 ユーザー「(ア) OK、お勧めの形で進めてください」＝お客様にこちらの声が届いていない様子を、言葉の形で
        # 拾わず判定AIで読み、切れ方の callee_cannot_hear に（CL-2 の 4-166：営業拒否にせず、お詫びとともにかけ直す）
        from flowctl import END_NONE, HEAR_LOST, HEAR_OK
        def R(hear):
            r = self.R("はい", END_NONE)
            r.hear = hear
            return r
        f = self.flow()
        self.heard(f, "もしもし？聞こえてますか？", R(HEAR_LOST))
        self.assertTrue(f.on_line_end(ai_speaking=False)["callee_cannot_hear"])
        g = self.flow()                                                       # 切れる直前の言葉の読みは、切れたあとに届くことが多い
        g.on_callee(); g.on_heard("もしもし？")
        self.assertFalse(g.on_line_end(ai_speaking=False)["callee_cannot_hear"])
        g.on_check("judge", R(HEAR_LOST))
        self.assertTrue(g.cut["callee_cannot_hear"])                          # 報告を作るとき（cut を読むとき）に決める
        h = self.flow()                                                       # 確かでない読みでも数える（読み過ぎても取り消せる側）
        h.on_callee(); h.on_heard("もしもーし")
        h.on_unsure("judge", "はい", hear=(HEAR_LOST,))
        self.assertTrue(h.on_line_end(ai_speaking=False)["callee_cannot_hear"])
        k = self.flow()                                                       # 前の言葉でそう読んでも、最後の言葉がふつうなら数えない
        self.heard(k, "もしもし？", R(HEAR_LOST))
        self.heard(k, "あ、聞こえました。はい、大丈夫です。", R(HEAR_OK))
        self.assertFalse(k.on_line_end(ai_speaking=False)["callee_cannot_hear"])
        self.assertIsNone(self.flow().cut)                                    # 切れていなければ None

    def test_the_judge_decides_the_reason_not_the_ai(self):
        from flowctl import END_NONE, END_REFUSED
        # 判定が「断った」と読めば、会話AIが「急いでいる」と報告しても、発信の拒否で締める（もうかけない＝原則14）
        f = self.flow()
        self.heard(f, "結構です。もうかけてこないでください。", self.R("いいえ", END_REFUSED))
        r = f.apply("request_end", {"reason": "callee_hurry"})
        self.assertEqual((r["result"], f.end_reason, bool(f.facts.get("do_not_call"))), ("end", "callee_refused_call", True))
        # 判定が「言っていない」と読めば、会話AIの終わりの報告は受け付けず、会話を続ける（締めない・もうかけないにしない）
        g = self.flow()
        self.heard(g, "いいえ、大丈夫です。", self.R("いいえ", END_NONE))
        r = g.apply("request_end", {"reason": "callee_refused_call"})
        self.assertEqual((r["result"], g.end_reason, bool(g.facts.get("do_not_call"))), ("rejected", None, False))
        # 会話AIが「質問が終わった」と報告しても、判定が断ったと読めば、もうかけない（お礼の締めにしない）
        h = self.flow()
        self.heard(h, "もうかけてこないでください。", self.R("いいえ", END_REFUSED))
        r = h.apply("request_end", {"reason": "done"})
        self.assertEqual((r["result"], h.end_reason, bool(h.facts.get("do_not_call"))), ("end", "callee_refused_call", True))

    def test_irreversible_check_says_whether_the_judge_agreed(self):
        # ✅ 2026-10-30 管理者のご決定 (6)：取り消せない決定は、2つ目の判定とそろったときだけその場で決める（CL-2 の連絡帳 4-182 の (1)：
        # 報告に irreversible_check が無く、そろった断りも毎回録音の確かめまで保留になっていた）
        from flowctl import END_NONE, END_REFUSED
        f = self.flow()
        self.heard(f, "もうかけてこないでください。", self.R("いいえ", END_REFUSED))
        f.apply("request_end", {"reason": "callee_hurry"})          # 会話AIの理由ではなく、判定の読みで締めた
        self.assertEqual((f.end_reason, f.irreversible_check), ("callee_refused_call", "agreed"))
        self.heard(f, "いえ、そういうわけでは。", self.R("いいえ", END_NONE))
        f.apply("request_end", {"reason": "callee_refused_call"})   # 締めたあとの会話AIの断りの報告を、判定は「言っていない」と読んだ
        self.assertEqual((len(f.facts["do_not_call"]), f.irreversible_check), (2, "disagreed"))
        g = self.flow()
        self.heard(g, "はい、予約しています。", self.R("はい", END_NONE))
        self.assertEqual(g.irreversible_check, "agreed")             # 取り消せない事実が無い

    def test_answers_decided_in_their_own_turn_read_their_own_judgments(self):
        # ⛔ 2026-11-08 日本時間10時台（F0 の試験の書き直しのあとの確かめ）で見つけた：答えを受け取った操作の中で決める所（急いでいる方への「また改めて…」の
        #    「いいえ」・ご遠慮の一言への「はい」＝取り消せない事実のそろい）が、受け取りの記録（taken＝操作のあとに書く）を読んでいた＝いまの答えの判定がそろって
        #    いても「判定が無い（none）」になり、CL-2 はそろった断りも録音の確かめまで保留にした（10-30 管理者のご決定 (6)「2つ目の判定とそろったときだけその場で
        #    決め」＝CL-2 の 4-182 の (1) と同じ穴）
        # ⇒ 受け取った答えの材料（その発話の番号・言葉・確かめ）を読む1か所 Flow._material（記録の前なら、いまの言葉）
        from flowctl import CALLBACK_IDS, END_HURRY, END_NONE, END_REFUSED, Flow, Question, UNDECIDED
        g = self.flow()
        self.heard(g, "今ちょっとバタバタしてて。", self.R(UNDECIDED, UNDECIDED, (END_HURRY,)))
        h1 = g.apply("request_end", {"reason": "callee_refused_call"})["question_id"]
        self.heard(g, "いいえ、もう結構です。", self.R("いいえ", END_NONE))
        r = g.apply("record_answer", {"question_id": h1, "condition_id": "いいえ"})
        self.assertEqual((r["result"], bool(g.facts.get("do_not_call")), g.irreversible_check), ("end", True, "agreed"))
        # ご遠慮の一言（R1）への「はい」も同じ（判定2つが割れて R1 を伺った電話）
        f = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                           meanings={"はい": "パンフレットをお送りして大丈夫だということ", "いいえ": "パンフレットはお送りしなくて大丈夫だということ"})],
                 play_recordings=True)
        f.use_checks("judge", "judge2")
        f.on_callee(); f.on_heard("いい加減にしてもらえますか。")
        f.on_check("judge", self.R(UNDECIDED, END_NONE)); f.on_check("judge2", self.R(UNDECIDED, END_REFUSED))
        self.assertEqual(f.judged_turn(voiced=False)["question_id"], CALLBACK_IDS["refusal"])
        f.on_callee(); f.on_heard("はい、もうかけてこないでください。")
        f.on_check("judge", self.R("はい", END_NONE)); f.on_check("judge2", self.R("はい", END_NONE))
        r = f.apply("record_answer", {"question_id": CALLBACK_IDS["refusal"], "condition_id": "はい"})
        self.assertEqual((r["result"], bool(f.facts.get("do_not_call")), f.irreversible_check), ("end", True, "agreed"))

    def test_other_reports_and_no_report_also_end_when_the_judge_reads_it(self):
        from flowctl import END_REFUSED
        # 会話AIが答えの報告をしても、判定が電話を終える言葉と読めば、先にそちらを当てる（答えだけ受け取って次の質問を流さない）
        f = self.flow()
        self.heard(f, "結構です。もうかけてこないでください。", self.R("いいえ", END_REFUSED))
        r = f.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        self.assertEqual((r["result"], f.end_reason), ("end", "callee_refused_call"))
        # 会話AIが何も報告しないターンのあとも、プログラムが締める（電話接続側が判定を待ってから呼ぶ）
        g = self.flow()
        self.heard(g, "もうかけてこないでください。", self.R("いいえ", END_REFUSED))
        r = g.judged_turn(voiced=False)
        self.assertEqual((r["result"], g.end_reason, g.log[-1]["op"]), ("end", "callee_refused_call", "judged_turn"))
        self.assertIsNone(g.judged_turn(voiced=False))   # 締めたあとは何もしない
        # 前の発話の判定があとから届いて、電話を終える言葉と読んだ：次の報告で締める（届いた時点で同じ決まりで当てる）
        h = self.flow()
        h.on_callee(); h.on_heard("もうかけないでって言ってるでしょう。")
        h.on_callee(); h.on_heard("ちょっと。")
        h.on_check("judge", self.R("いいえ", END_REFUSED), turn=1)
        r = h.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        self.assertEqual((r["result"], h.end_reason), ("end", "callee_refused_call"))

    def test_undecided_end_picks_the_scene_by_the_judges_lean(self):
        # 判定でも決まらないときの場面（✅ 11-01 17時04分 (a)(b)・20時56分のご判断）：表の行ごとに1つずつ
        from flowctl import CALLBACK_IDS, END_ANGRY, END_HURRY, END_REFUSED, UNDECIDED
        from phrases import BACK_TO, CALLBACK_ASK
        R1 = CALLBACK_IDS["refusal"]
        # 怒っている・苦情に寄る：確かめずに締めて、人に引き継ぐ印（特例）
        f = self.flow()
        self.heard(f, "何回かけてくるんですか。", self.R(UNDECIDED, UNDECIDED, (END_ANGRY,)))
        r = f.apply("request_end", {"reason": "callee_refused_call"})
        self.assertEqual((r["result"], f.end_reason, bool(f.facts.get("complaint"))), ("end", "callee_complaint", True))
        # 急いでいるだけに寄る：急いでいるときの伺い（「はい、」＋「それではまた改めてお掛けしてもよろしいでしょうか？」。もうかけないにはしない）
        g = self.flow()
        self.heard(g, "今ちょっとバタバタしてて。", self.R(UNDECIDED, UNDECIDED, (END_HURRY,)))
        r = g.apply("request_end", {"reason": "callee_refused_call"})
        self.assertEqual((r["result"], r["question_id"], r["play"][0]["text"], r["ack"], bool(g.facts.get("do_not_call"))),
                         ("next", CALLBACK_IDS["hurry"], CALLBACK_ASK["hurry_again"], "hai", False))
        # 断ったに寄り、いまの質問への答えとも読める（「もういいです。」＝送らない）：ご遠慮の一言は伺わず、会話AIが聞いた答えを報告し、その答えは
        # 受け取る前に向きを確かめる（✅ 20時56分「「パンフレットはお送りしない方がいいということでしょうか？」のような流れが普通じゃないですか？」）
        h = self.flow()
        self.heard(h, "もういいです。", self.R("いいえ", UNDECIDED, (END_REFUSED,)))
        r = h.apply("request_end", {"reason": "callee_refused_call"})
        self.assertEqual(r["result"], "rejected")
        self.assertIn("record_answer", r["message"])
        self.assertNotIn(R1, h.items)
        r = h.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        self.assertEqual((r["result"], h.current, h.items["Q1"].condition, h.end_reason), ("confirm_required", "Q1", "いいえ", None))
        # ✅ 22時31分 ユーザー：「「もういいです。」のパターンでも、「パンフレットはお送りしない方がいいということでしょうか？」の方がよくないですか？」
        # （選択肢ごとの取込の言葉 doubt_words。頭の「念のため」は付けない。相づちは「はい、」）
        self.assertEqual((r["say"], r["ack"]), ("パンフレットはお送りしない方がいいということでしょうか？", "hai"))
        # 必須でない質問でも同じ（確かめるのは答えの正しさではなく、電話を続けてよいか）。判定が「答えたくない」とだけ読んだ（向きが無い）なら、
        # いまの話への返事としては扱わず、ご遠慮の一言
        from flowctl import Flow, Question
        n = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", required=False, conditions=("はい", "いいえ"),
                           meanings={"はい": "パンフレットをお送りして大丈夫だということ", "いいえ": "パンフレットはお送りしなくて大丈夫だということ"})],
                 play_recordings=True)
        n.use_checks("judge")
        self.heard(n, "もういいです。", self.R("いいえ", UNDECIDED, (END_REFUSED,)))
        n.apply("request_end", {"reason": "callee_refused_call"})
        r = n.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        # 取込の言葉（doubt_words）がまだ無い質問は、曖昧な答えと同じ確かめ（止めない）
        self.assertEqual((r["result"], r["say"]), ("confirm_required", "念のためパンフレットはお送りしなくて大丈夫だということでよろしいでしょうか？"))
        w = self.flow()
        self.heard(w, "もういいです。", self.R("refused", UNDECIDED, (END_REFUSED,)))
        self.assertEqual(w.apply("request_end", {"reason": "callee_refused_call"})["question_id"], R1)
        # 断ったに寄り、いまの質問への答えとは読めない：その場で1回だけ「失礼いたしました。」＋「今後このようなお電話はご遠慮…」
        # （✅ 22時31分 ユーザー：「「うーん？」は悩んでいる最中なので、少し待って…」＝「うーん。」はこの例にしない）
        for said, cond, end in (("はい、もうかけないでください。", "はい", "callee_refused_call"), ("いえ、そういうわけでは。", "いいえ", None)):
            k = self.flow()
            self.heard(k, "そういうお電話はちょっと……。", self.R(UNDECIDED, UNDECIDED, (END_REFUSED,)))
            r = k.apply("request_end", {"reason": "callee_refused_call"})
            self.assertEqual((r["result"], r["question_id"], r["play"][0]["id"], r["play"][0]["text"]),
                             ("next", R1, "callback_refusal", CALLBACK_ASK["refusal"]))
            self.assertEqual(k._ack("request_end", {"reason": "callee_refused_call"}, r), "shitsurei")   # 頭の「失礼いたしました。」は相づちの録音
            self.assertEqual(k.apply("request_end", {"reason": "callee_refused_call"})["result"], "rejected")   # 同じ発話の報告は1回だけ
            k.on_callee(); k.on_heard(said); k.on_check("judge", self.R(cond, "言っていない"))
            r = k.apply("record_answer", {"question_id": R1, "condition_id": cond})
            if end:   # はい＝もうかけない
                self.assertEqual((r["result"], k.end_reason, bool(k.facts.get("do_not_call"))), ("end", end, True))
            else:     # いいえ＝「話を戻させていただきますね。」から質問へ（10-23）＝同じ質問をそのまま2度は流さない
                self.assertEqual([p["text"] for p in r["play"]][0], BACK_TO)
                self.assertEqual((k.current, k.items["Q1"].state), ("Q1", "empty"))
        # 言い直しの返事待ちの間にご遠慮の一言を伺い、「いいえ」：言い直しへ戻るときも「話を戻させていただきますね。」から（戻る1か所 _continue の
        # 言い直しの返事待ちの枝。⛔ 2026-11-06 日本時間10時台に見つけた：この枝だけ、戻る一言を作って捨てていた＝言い直しをそのまま言い直した）
        d = self.flow()
        self.heard(d, "もういいです。", self.R("いいえ", UNDECIDED, (END_REFUSED,)))
        d.apply("request_end", {"reason": "callee_refused_call"})
        say = d.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})["say"]
        self.heard(d, "そういうお電話はちょっと……。", self.R(UNDECIDED, UNDECIDED, (END_REFUSED,)))
        self.assertEqual(d.apply("request_end", {"reason": "callee_refused_call"})["question_id"], R1)
        d.on_callee(); d.on_heard("いえ、そういうわけでは。"); d.on_check("judge", self.R("いいえ", "言っていない"))
        r = d.apply("record_answer", {"question_id": R1, "condition_id": "いいえ"})
        # 戻る一言のあとは、質問へ戻るときと同じく頭に「それでは」（B-1）
        self.assertEqual(([p["text"] for p in r["play"]], r["say"], d.awaiting_confirm), ([BACK_TO], "それでは" + say, "Q1"))
        # 伺うのは1回だけ：もう一度決まらなければ、受け付けず会話を続ける
        m = self.flow()
        self.heard(m, "そういうお電話はちょっと……。", self.R(UNDECIDED, UNDECIDED, (END_REFUSED,)))
        m.apply("request_end", {"reason": "callee_refused_call"})
        m.on_callee(); m.on_heard("ですから、そういうのは……。"); m.on_check("judge", self.R(UNDECIDED, UNDECIDED, (END_REFUSED,)))
        self.assertEqual(m.apply("request_end", {"reason": "callee_refused_call"})["result"], "rejected")

    def test_split_readings_with_an_end_lean_are_confirmed_without_a_report(self):
        # ⛔ 2026-11-01 の見直し（ユーザー：「ここまででミスや不具合はないですか？」）：判定が割れて「決められない」になると、会話AIが報告しない限り
        #    何もせず、組が「断った」と確かに読んだお客様に次の質問を流していた ⇒ 割れた・確かでない読みに電話を終える寄りがあれば、報告が無くても
        #    決まらないときの場面へ。寄りが無ければ何もしない
        from flowctl import CALLBACK_IDS, END_NONE, END_REFUSED, Flow, Question, UNDECIDED
        def two(words="もうかけてこないでください。"):
            f = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                               meanings={"はい": "パンフレットをお送りして大丈夫だということ", "いいえ": "パンフレットはお送りしなくて大丈夫だということ"}),
                      Question("Q2", "ご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",))], play_recordings=True)
            f.use_checks("judge", "judge2")
            f.on_callee(); f.on_heard(words)
            return f
        # いまの質問への答えとは読めない：報告の無いターンのあとでも、ご遠慮の一言（相づち「失礼いたしました。」も返事に付ける）
        f = two("いい加減にしてもらえますか。")
        f.on_check("judge", self.R(UNDECIDED, END_NONE)); f.on_check("judge2", self.R(UNDECIDED, END_REFUSED))
        r = f.judged_turn(voiced=False)
        self.assertEqual((r["result"], r["question_id"], r["ack"], f.end_reason), ("next", CALLBACK_IDS["refusal"], "shitsurei", None))
        # 確かでない読みだけが断ったに寄る（確かな読みが1つも無い）：同じく、ご遠慮の一言（⛔ 前は、割れたときだけで、ここでは何もしなかった）
        u = two("いい加減にしてもらえますか。")
        u.on_unsure("judge", UNDECIDED, end=(END_REFUSED,)); u.on_unsure("judge2", UNDECIDED)
        self.assertEqual(u.judged_turn(voiced=False)["question_id"], CALLBACK_IDS["refusal"])
        # いまの質問への答え（いいえ＝送らない）とも読める：報告の無いターンのあとは何もしない（会話AIに答えの報告を促す＝unreported_note）。
        # 答えの報告は、判定より先に締めず、受け取る前に向きを確かめる（✅ 20時56分のご判断）
        g = two()
        g.on_check("judge", self.R("いいえ", END_NONE)); g.on_check("judge2", self.R("いいえ", END_REFUSED))
        self.assertIsNone(g.judged_turn(voiced=False))
        r = g.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        self.assertEqual((r["result"], g.current, g.end_reason), ("confirm_required", "Q1", None))
        # 確かでない答えの読みだけでも同じ（いまの話への返事とも取れる）
        v = two("もういいです。")
        v.on_unsure("judge", "いいえ", end=(END_REFUSED,)); v.on_unsure("judge2", "いいえ")
        self.assertIsNone(v.judged_turn(voiced=False))
        h = two()
        h.on_check("judge", self.R("いいえ", END_NONE)); h.on_check("judge2", self.R("いいえ", END_NONE))
        self.assertIsNone(h.judged_turn(voiced=False))   # そろって「言っていない」：何もしない
        r = h.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        self.assertEqual(r["result"], "next")   # 向きの確かめは、電話を終える言葉か決まらなかった言葉だけ

    def test_late_judges_wait_once_more_then_close_politely(self):
        # (エ) ✅ 2026-11-01 日本時間20時56分 ユーザー「OK」：判定の答えが2秒の待ちに間に合わなければ、もう一度だけ最大2秒黙って待つ（waits_again）。
        # 届けばその読みで決め、それでも届かなければ、判定が止まったときの決まりで丁寧に締める（もうかけない・苦情の印は付けず、通話のあとの確かめへ）
        from flowctl import END_HURRY, END_REFUSED, Flow, Question
        from phrases import CLOSE_DECLINED
        def flow():
            f = Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], play_recordings=True)
            f.use_checks("judge", "judge2")
            f.on_callee(); f.on_heard("ごめんなさい、今から出かけるので切りますね。")
            return f
        f = flow()
        f.on_judging("judge", None, f.callee_said); f.on_judging("judge2", None, f.callee_said)
        self.assertTrue(f.waits_again("request_end", {"reason": "callee_hurry"}))   # 会話AIが終わりを報告・判定がまだ届いていない
        self.assertFalse(f.waits_again("record_answer", {"question_id": "Q1"}))     # 電話を終える読みが無い報告は待たない
        for reason in ("callee_hurry", "callee_refused_call", "callee_complaint"):
            f = flow()
            f.on_judging("judge2", None, f.callee_said)   # 2回待っても届かない
            r = f.apply("request_end", {"reason": reason})
            self.assertEqual((r["result"], r["play"][0]["text"], f.end_reason, f.facts["end_unjudged"][0]["reason"],
                              bool(f.facts.get("do_not_call")), bool(f.facts.get("complaint"))),
                             ("end", CLOSE_DECLINED, reason, reason, False, False), reason)
        # 待つ間に届いた：その読みで決める（この例なら急いでいる＝急いでいるときの伺い）
        g = flow()
        g.on_judging("judge2", None, g.callee_said)
        g.on_check("judge2", self.R("いいえ", END_HURRY), said=g.callee_said); g.on_judged("judge2", None, g.callee_said)
        self.assertFalse(g.waits_again("request_end", {"reason": "callee_hurry"}))
        self.assertEqual(g.apply("request_end", {"reason": "callee_hurry"})["question_id"], "H1")
        # 会話AIが答えを報告した発話でも、届いた読みに電話を終える読みがあり、まだ届いていない判定があれば、もう一度だけ待つ（一部の読みで締めない）
        h = flow()
        h.on_check("judge", self.R("いいえ", END_REFUSED), said=h.callee_said); h.on_judging("judge2", None, h.callee_said)
        self.assertTrue(h.waits_again("record_answer", {"question_id": "Q1"}))
        h.on_callee()
        self.assertFalse(h.waits_again("request_end", {"reason": "callee_hurry"}))   # 次の発話では、前の発話の判定は待たない

    def test_hurry_asks_to_call_back_later_then_the_date(self):
        # ✅ 2026-11-01 日本時間20時56分 ユーザー (b)：「いま時間がないので結構です。」→「それではまた改めてお掛けしてもよろしいでしょうか？」→ OK なら
        # 「ご都合のいい日時はいつ頃でしょうか？」で日時を伺って締める／NO なら締めて、もうかけない（営業拒否）
        from flowctl import CALLBACK_IDS, END_HURRY, Flow, Question
        from phrases import CALLBACK_ASK, CLOSE_DECLINED, CLOSING
        def hurried():
            f = Flow([Question("Q1", "担当者から詳しいご案内のお電話を差し上げてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"))],
                     play_recordings=True)
            f.use_checks("judge")
            f.on_callee(); f.on_heard("いま時間がないので結構です。"); f.on_check("judge", self.R("いいえ", END_HURRY))
            r = f.apply("request_end", {"reason": "callee_hurry"})
            self.assertEqual((r["question_id"], r["play"][0]["id"], r["play"][0]["text"], r["ack"]),
                             (CALLBACK_IDS["hurry"], "callback_hurry_again", CALLBACK_ASK["hurry_again"], "hai"))
            return f
        # はい ⇒ ご都合のいい日時を伺う（日時の型＝言い直して確かめる）⇒ ふつうの締め。かけ直しの記録（あとで・時刻）に残る
        f = hurried()
        f.on_callee(); f.on_heard("はい、大丈夫です。"); f.on_check("judge", self.R("はい", "言っていない"))
        r = f.apply("record_answer", {"question_id": "H1", "condition_id": "はい"})
        self.assertEqual((r["result"], r["question_id"], r["play"][0]["text"]), ("next", "C1", CALLBACK_ASK["hurry_when"]))
        f.on_callee(); f.on_heard("明日の午後3時でお願いします。")
        f.apply("record_answer", {"question_id": "C1", "condition_id": "答えた", "value": "明日の午後3時"})
        f.on_callee(); f.on_heard("はい。")
        r = f.apply("confirm_field", {"question_id": "C1", "result": "affirmed"})
        self.assertEqual((r["result"], r["play"][0]["text"], f.end_reason), ("end", CLOSING, "callback"))
        self.assertEqual((f.facts["callback"][0]["why"], f.facts["callback"][0]["time"], bool(f.facts.get("do_not_call"))),
                         ("later", "明日の午後3時", False))
        # いいえ ⇒ 締めて、もうかけない（営業拒否）
        g = hurried()
        g.on_callee(); g.on_heard("いえ、結構です。"); g.on_check("judge", self.R("いいえ", "言っていない"))
        r = g.apply("record_answer", {"question_id": "H1", "condition_id": "いいえ"})
        self.assertEqual((r["result"], r["play"][0]["text"], g.end_reason, bool(g.facts.get("do_not_call"))),
                         ("end", CLOSE_DECLINED, "callee_refused_call", True))
        # はっきりしない（わからない）⇒ もうかけないとは言われていないので、印を付けずに丁寧に締める
        h = hurried()
        h.on_callee(); h.on_heard("ちょっと分からないです。"); h.on_check("judge", self.R("unknown", "言っていない"))
        r = h.apply("record_answer", {"question_id": "H1", "condition_id": "unknown"})
        self.assertEqual((r["result"], h.end_reason, bool(h.facts.get("do_not_call"))), ("end", "callee_hurry", False))
        # 伺っている途中で、また急いでいると言われた ⇒ 伺わずに締める（2回目の「急いでいる」）
        k = hurried()
        k.on_callee(); k.on_heard("急いでるので失礼します。"); k.on_check("judge", self.R("unknown", END_HURRY))
        r = k.apply("request_end", {"reason": "callee_hurry"})
        self.assertEqual((r["result"], k.end_reason), ("end", "callee_hurry"))

    def test_thinking_prompts_in_order(self):
        # ✅ 2026-11-01 日本時間23時04分 ユーザー：5秒黙られたら「どうなさいますか？」、さらに5秒黙られたら「いかがなさいましたか？」（どの質問でも）
        # ⇒ ✅ 2026-11-07 日本時間18時03分49秒 ユーザー「(2) イ」：5秒の一言は、急かさない「何か気になる点がございましたらお気軽にお聞かせくださいね。」
        #    （13時05分06秒「迷っていると言っているのに…どうなさいましたか と 急かすのは最悪な手ですよ。」と同じ理由）。さらに5秒は今のまま
        from phrases import RECORDED, THINKING_PROMPT, THINKING_PROMPT_IDS
        self.assertEqual(THINKING_PROMPT, ("何か気になる点がございましたらお気軽にお聞かせくださいね。", "いかがなさいましたか？"))
        self.assertEqual([RECORDED[k] for k in THINKING_PROMPT_IDS], list(THINKING_PROMPT))   # 録音は共通の一言（「いかがなさいましたか？」は今の録音）
        self.assertNotIn("、", THINKING_PROMPT[0])   # 決まった言い方なので言葉の途中に読点を入れない（10-15）
        self.assertNotIn("dounasaimasu", RECORDED)   # 使わなくなった録音の名前は残さない（CL-2 の一覧から外すのは CL2_RETIRED が待つ）

    def test_enough_in_the_main_talk_asks_what_was_wrong_before_the_refusal_line(self):
        # ✅ 2026-11-08 日本時間2時21分15秒 ユーザー：「本題に入った状況での「もういいです。」に、序盤の「失礼いたしました。今後このようなお電話はご遠慮したほうが
        # よろしいでしょうか？」はすぐには使わない。⇒「何か問題でもございましたでしょうか？（別の言い回しでもOK）」などで相手の本心を伺った方がいいんじゃない
        # でしょうか？…本題のクロージングまで入っている段階で、もういいですなどという言葉が出た場合は、そのクロージングのアプローチに対して問題があった可能性が
        # あります。それが何なのかということをきっちりお聞きしないと、もしかしたら本音を聞けば取り戻せる内容を失ってしまう可能性がある上、今後の改善にもつながり
        # ません。」⇒ 本題（この電話で業務の質問の答えを1つ以上いただいた）では、ご遠慮の一言より先に「失礼いたしました。」＋「何か問題でもございましたでしょうか？」
        # （「AIですか」に応える一言と同じ共通の録音 ai_answer）。問題は無い＝伺う前の質問へ戻る／問題を言った＝会話AIが業務の情報の範囲で応え、依頼者へ渡す記録に
        # 残す（今後の改善）／まだ終えたい＝ここでご遠慮の一言。序盤（まだ業務の答えをいただいていない）は今までどおりご遠慮の一言
        from end_words import PAMPHLET, YES_NO, _reading, _spoken, question
        from flowctl import CALLBACK_IDS, UNDECIDED, Flow, Question
        from meaning_judge import Reading
        from phrases import AI_ANSWER
        r1 = "失礼いたしました。今後このようなお電話はご遠慮したほうがよろしいでしょうか？"
        cid = CALLBACK_IDS["concern"]

        def say(f, words, reading, qid=None, cond=None, **extra):
            f.on_callee(); f.on_heard(words); f.on_check("judge", reading)
            if qid is None:
                return f.judged_turn(voiced=False)
            return f.apply("record_answer", {"question_id": qid, "condition_id": cond, **extra})

        def flow(main=True):
            first = Question("Q0", "ご予約はされていますでしょうか？", "yes_no", conditions=YES_NO, asks_fact=True)
            qs = ([first] if main else []) + [question(PAMPHLET, qid="Q1"), Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=YES_NO)]
            f = Flow(qs, play_recordings=True)
            f.use_checks("judge")
            if main:
                say(f, "はい、予約しています。", Reading("はい"), "Q0", "はい")
            self.assertEqual(f.current, "Q1")
            return f, say(f, "もういいです。", _reading(UNDECIDED, UNDECIDED))
        f, r = flow(main=False)
        self.assertEqual(_spoken(r), r1)   # 序盤は今までどおり
        # (ア) 本題の始まりは業務ごとに選べる（✅ 2026-11-08 日本時間3時15分04秒 ユーザー「(ア)業務ごとに選択できるようにしてください。」）：既定＝最初の業務の
        # 質問を流したあと（asked＝名乗り・用件のあと最初の質問への「もういいです。」も本心を伺う。✅ 3時48分03秒 ユーザー「(ア)既定は「最初の質問を流したあと」」）
        # ／この電話で業務の答えを1つ以上いただいたあと（answered）。続きの電話はどちらでも本題。業務設定の欄は instruction.Business.main_talk_policy（取込＝CL-2）
        from flowctl import POLICIES, check_policies
        from instruction import Business
        self.assertEqual(POLICIES["main_talk"], ("asked", "answered"))
        self.assertEqual(Business(company="株式会社テスト", caller="佐藤", purpose="ご案内", questions=[]).policies()["main_talk"], "asked")
        with self.assertRaises(ValueError):
            check_policies({"main_talk": "never"})
        def early(policy):
            # 本番と同じく、第一声のあとに名乗り・用件・最初の質問を流してから（最初の質問を流した印＝Item.played）
            b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料のご案内", main_talk_policy=policy,
                         questions=[question(PAMPHLET, qid="Q1"), Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=YES_NO)])
            f = b.flow(play_recordings=True)
            f.use_checks("judge")
            f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
            if f.apply("report_party", {"party": "person"}).get("result") not in ("opening", "end"):
                f.on_first_words_end()
            self.assertTrue(f.items["Q1"].played)
            return say(f, "もういいです。", _reading(UNDECIDED, UNDECIDED))
        self.assertEqual((_spoken(early("answered")), _spoken(early("asked"))), (r1, "失礼いたしました。" + AI_ANSWER))
        f, r = flow()
        self.assertEqual((_spoken(r), f.current, f.end_reason), ("失礼いたしました。" + AI_ANSWER, cid, None))
        # 問題は無い：断ったとは言われていない＝伺う前の質問へ戻る（ご遠慮の一言の「いいえ」と同じ1か所）
        r = say(f, "いえ、別に問題はないです。", Reading("問題は無い"), cid, "問題は無い")
        self.assertEqual((f.current, "話を戻させていただきますね。" in _spoken(r), PAMPHLET in _spoken(r)), ("Q1", True, True))
        # 問題を言った：質問は流し直さず、会話AIが業務の情報の範囲で応える（尋ねられて答える1か所と同じ道）。言っていただいた点は依頼者へ渡す記録に残す
        g, _ = flow()
        r = say(g, "説明が長くてよく分からないんですよ。", Reading("問題を言った"), cid, "問題を言った", value="説明が長くてよく分からない")
        self.assertEqual((_spoken(r), g.end_reason), ("", None))
        self.assertIn("説明が長くて", r["message"])
        # 会話AIへの知らせは、こちらの考えを尋ねられたとき（「こちらに尋ねています」）の文ではなく、言っていただいた気になる点に応える文
        self.assertNotIn("こちらに尋ねています", r["message"])
        self.assertIn("気になる点", r["message"])
        # 応える文が使えない（中身を確かめられない）：尋ねられる前の流れ（パンフレットの答えとして報告し直す＝_asked_skip）へは進まず、ご承認の手順でご説明
        # できないときと同じ一言（言ったことの種類＝ご意見）で申し伝える。業務の情報の文で応える形は、使えないときの業務の情報の文を選ばせる
        from phrases import point_fallback, point_fallback_id
        k, _ = flow()
        say(k, "説明が長くてよく分からないんですよ。", Reading("問題を言った"), cid, "問題を言った", value="説明が長くてよく分からない")
        r = k.apply("replay_opening", {"part": "own", "answer": "大変失礼いたしました。パンフレットは無料でお送りしております。"})
        self.assertEqual((k.asked_skip == k.callee_turns, "業務の情報の文" in r["message"]), (False, True), r)
        r = k.apply("replay_opening", {"part": "no_answer", "answer": "大変失礼いたしました。ご意見は担当の者に申し伝えます。", "fallback": "opinion"})
        self.assertEqual([(p["id"], p["text"]) for p in r.get("play", [])], [(point_fallback_id("opinion", False), point_fallback("opinion", False))], r)
        self.assertEqual((k.asked_skip == k.callee_turns, k.current, k.end_reason), (False, "Q1", None))
        line = "大変失礼いたしました。要点だけ申し上げますと、パンフレットは無料でお送りしております。"
        grounded(g, line)
        self.assertEqual(g.apply("replay_opening", {"part": "own", "answer": line})["result"], "own_answer")
        # 言っていただいた点は、お客様の質問（callee_question）ではなく、気になる点の事実 concern に残る（そのとき伺っていた質問・お客様の言葉・応えた文）
        self.assertEqual([(x["question"], "説明が長くて" in x["said"], x["answered"], x["answer"]) for x in g.facts.get("concern", [])],
                         [("Q1", True, True, line)], g.facts)
        self.assertNotIn("callee_question", g.facts)
        say(g, "それなら送ってください。", Reading("はい"), "Q1", "はい")
        self.assertEqual(g.export()["Q1"], "はい")
        # まだ電話を終えたい（断ろうとしている）：ここでご遠慮の一言
        h, _ = flow()
        r = say(h, "もういいって言ってるでしょう。", Reading("断ろうとしている"), cid, "断ろうとしている")
        self.assertEqual(_spoken(r), r1)

    def test_final_goal_refusal_closes_only_when_the_goal_is_lost(self):
        # ✅ 2026-11-01 日本時間22時31分 ユーザー：「片方だけでも目的が達成できるときは、質問を続け、片方断られたら、目的は達成できない場合は、途中で
        # 締めるという形になるんではないでしょうか。」（20時56分：最終目的は業務ごと・複数ありうる・断られたらその業務だけかけない）
        from flowctl import Flow, Question
        from phrases import CLOSING_AFTER_DECLINE   # お断りのあとの締め（✅ 2026-11-02 日本時間6時33分 ユーザー）
        def goals(mode):
            f = Flow([Question("Q1", "会員登録のご案内をお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                               final_goal=True, declines=("いいえ",)),
                      Question("Q2", "担当者から詳しいご案内のお電話を差し上げてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                               final_goal=True, declines=("いいえ",)),
                      Question("Q3", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], goal_mode=mode)
            f.on_callee(); f.on_heard("いえ、登録は結構です。")
            f.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
            return f
        # どれか1つで目的が果たせる業務：1つ断られても、ほかの最終目的が残れば質問を続ける
        f = goals("any")
        self.assertEqual((f.current, f.end_reason), ("Q2", None))
        f.on_callee(); f.on_heard("いえ、お電話も結構です。")
        r = f.apply("record_answer", {"question_id": "Q2", "condition_id": "いいえ"})   # 全部断られた ⇒ 途中で締める（残りの質問は伺わない）
        self.assertEqual((r["result"], r["say"], f.end_reason, f.facts["goal_refused"][0]["goals"], bool(f.facts.get("do_not_call"))),
                         ("end", CLOSING_AFTER_DECLINE, "goal_refused", ["Q1", "Q2"], False))
        # 全部が要る業務：1つ断られたら、途中で締める
        g = goals("all")
        self.assertEqual((g.end_reason, g.facts["goal_refused"][0]["goals"]), ("goal_refused", ["Q1"]))
        # 断りと一緒に質問をされた（先に質問に答える）：締めの言葉を流す前に電話が切れても、目的が果たせなくなった事実は、答えを受け取った
        # その場で残る（質問に答えたあとの手＝締めを、その場で決めておくため。CL-2 は通話の事実から、その業務をかけないと決める＝4-182 の (e)）
        k = Flow([Question("Q1", "会員登録のご案内をお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                           final_goal=True, declines=("いいえ",)),
                  Question("Q3", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], goal_mode="all")
        k.on_callee(); k.on_heard("いえ、登録は結構です。そもそも、どちらでこの番号を知ったんですか？")
        r = k.apply("record_answer", {"question_id": "Q1", "condition_id": "いいえ"})
        k.on_line_end(ai_speaking=False)
        self.assertEqual((r["result"], k.end_reason, [(x["goals"], x["mode"]) for x in k.facts.get("goal_refused", [])]),
                         ("callee_asked", "goal_refused", [(["Q1"], "all")]))
        # 断る答えでない答え（わからない）は、断られたとはしない
        h = Flow([Question("Q1", "会員登録のご案内をお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                           final_goal=True, declines=("いいえ",)),
                  Question("Q3", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], goal_mode="all")
        h.on_callee(); h.on_heard("ちょっと分からないです。")
        h.apply("record_answer", {"question_id": "Q1", "condition_id": "unknown"})
        self.assertEqual((h.current, h.end_reason), ("Q3", None))

    def test_an_answer_that_turns_down_is_received_with_shouchi_and_closed_with_shouchi_itashimashita(self):
        # お断り・目的から遠ざかる向きの答え（Question.turned_down の1か所）を受け取ったら、次へ進む相づちは「承知しました。」（お礼は返さない。
        # ✅ 2026-11-03 ユーザー：遠ざかる向きに寄った・言った答えは「承知しました。」で次へ）、そのまま締めるなら「はい、承知いたしました。お忙しい
        # ところ…」（✅ 2026-11-02 日本時間6時33分 ユーザー：「…「はい、お忙しいところ…」だと唐突なので、こちら「はい、承知いたしました。お忙しい
        # ところ…」の方がいいんじゃないでしょうか？」）。目的が果たせなくなったか（断りの印）とは別に決まる。⛔ 2026-11-04 日本時間7時台（「最終目的が、
        # 複数あるときでも…本当に大丈夫ですか？」）に見つけた：言い切った遠ざかる答えに順番で「ありがとうございます。」を返し、最終目的が2つの業務で
        # 片方を受けていただいたあとの最後のお断りには「はい、お忙しいところ…」で締めていた
        from flowctl import Flow, Question
        from phrases import CLOSING, CLOSING_AFTER_DECLINE
        yn = lambda i, t, **k: Question(i, t, "yes_no", conditions=("はい", "いいえ"), **k)
        visit = dict(away=("いいえ",), meanings={"はい": "ご来店のご意向があるということ", "いいえ": "ご来店のご意向はないということ"})
        def answer(f, heard, qid, cond):
            f.on_callee(); f.on_heard(heard)
            return f.apply("record_answer", {"question_id": qid, "condition_id": cond})
        # (a) 言い切った遠ざかる答え（最終目的でない質問）：順番が「ありがとうございます。」の位置でも「承知しました。」（前の相づちも「承知しました。」
        # なら「かしこまりました。」＝✅ 2026-11-02 日本時間7時12分）。お礼は返さない
        f = Flow([yn("Q1", "ご予約はされていますでしょうか？", asks_fact=True), yn("Q2", "ご来店のご意向はございますでしょうか？", **visit),
                  yn("Q3", "ご不明な点はございますでしょうか？")])
        answer(f, "はい、しています。", "Q1", "はい")
        r = answer(f, "いえ、来店するつもりはありません。", "Q2", "いいえ")
        self.assertEqual((r["result"], r["ack"]), ("next", "kashikomari"))
        # (b) 最終目的が2つ（どれか1つで果たせる）：1つ目を受けていただき、最後の2つ目を断られた＝目的は果たせている（断りの印は付かない）が、
        # 締めは「はい、承知いたしました。…」。2つ目を受けていただいたときは、今までどおりの締め
        def goals():
            return Flow([yn("G1", "会員登録のご案内をお送りしてもよろしいでしょうか？", final_goal=True, declines=("いいえ",)),
                         yn("G2", "担当者から詳しいご案内のお電話を差し上げてもよろしいでしょうか？", final_goal=True, declines=("いいえ",))],
                        goal_mode="any")
        g = goals()
        answer(g, "はい、お願いします。", "G1", "はい")
        r = answer(g, "いえ、お電話は結構です。", "G2", "いいえ")
        self.assertEqual((r["result"], r["ack"], r["say"], g.end_reason, bool(g.facts.get("goal_refused"))),
                         ("end", "hai", CLOSING_AFTER_DECLINE, "done", False))
        g = goals()
        answer(g, "いえ、登録は結構です。", "G1", "いいえ")
        r = answer(g, "はい、お願いします。", "G2", "はい")
        self.assertEqual((r["result"], r["say"], g.end_reason), ("end", CLOSING, "done"))
        # (c) ここで終える答え：遠ざかる向きの答えなら「はい、承知いたしました。…」・事実を伺う質問の答え（ご予約はされていない）は今までどおり
        e = Flow([yn("Q1", "ご来店のご意向はございますでしょうか？", required=True, ends_on=("いいえ",), **visit), yn("Q2", "ご不明な点はございますでしょうか？")])
        r = answer(e, "いえ、来店するつもりはありません。", "Q1", "いいえ")
        self.assertEqual((r["result"], r["say"], e.end_reason), ("end", CLOSING_AFTER_DECLINE, "done"))
        e = Flow([yn("Q1", "ご予約はされていますでしょうか？", required=True, asks_fact=True, ends_on=("いいえ",)), yn("Q2", "ご不明な点はございますでしょうか？")])
        r = answer(e, "いえ、していません。", "Q1", "いいえ")
        self.assertEqual((r["result"], r["say"]), ("end", CLOSING))
        # (d) 言い切らない遠ざかる答えに業務の手立てがある：今までどおり「はい、」＋「それでは…」（✅ 2026-11-03 日本時間8時10分）
        h = Flow([yn("Q1", "ご来店のご意向はございますでしょうか？", **visit),
                  yn("H1", "オンラインでのご案内もできますがいかがでしょうか？", ask_if=("Q1", ("いいえ",)), ask_if_hedged=True)])
        r = answer(h, "たぶん今回はいいかなと思います。", "Q1", "いいえ")
        self.assertEqual((r["result"], r["ack"], h.current), ("next", "hai", "H1"))

    # ── 11-04 日本時間7時台の4回目のご質問（「他にも、ここまでの実装で、想定との食い違いや不備、1本化漏れはないですか？」）で、別の担当の読み直しが
    #    見つけ、CL-1 が流れの制御に通して確かめた漏れ。どれも「同じ答えなのに、届いた報告の名前・入った道で、聞こえ方や印が変わる」型
    @staticmethod
    def _say(f, heard, op, **args):
        f.on_callee(); f.on_heard(heard)
        return f.apply(op, args)

    def test_the_ack_is_chosen_by_what_was_received_not_by_the_report_name(self):
        # 相づちは、この報告で受け取った答えで選ぶ（唯一の場所＝Flow._received_now）。⛔ 報告の名前で選んでいたので、(a) 言い直しへの返事で届いた
        # 「わからない」に順番の「ありがとうございます。」、(b) 「結構です。」が聞き取れないの報告で届くと、遠ざかる向きの答えと決まっても「はい、」、
        # (c) 「わからない」のすぐあとの締めの前の念のための確認から、重いお詫びが抜けていた、(d) 言い直しへの言い切っていない返事から、業務設定の
        # 追って伺う質問へ入ると「承知しました。」（最初の答えから入ると「はい、」＝✅ 2026-11-03 ユーザーの言い方「はい、それでは…」）
        from flowctl import Flow, Question
        say = self._say
        yn = lambda i, t, **k: Question(i, t, "yes_no", conditions=("はい", "いいえ"), **k)
        pay = lambda: Question("Q2", "お支払いはカードと現金のどちらになさいますか？", "choice", conditions=("カード", "現金"),
                               meanings={"カード": "お支払いはカード", "現金": "お支払いは現金"})
        # (a)
        f = Flow([yn("Q1", "ご予約はされていますでしょうか？"), pay(), yn("Q3", "ご不明な点はございますでしょうか？")], play_recordings=True)
        say(f, "はい、しています。", "record_answer", question_id="Q1", condition_id="はい")
        by_answer = say(f, "ちょっとわからないです。", "record_answer", question_id="Q2", condition_id="unknown")
        f = Flow([yn("Q1", "ご予約はされていますでしょうか？"), pay(), yn("Q3", "ご不明な点はございますでしょうか？")], play_recordings=True)
        say(f, "はい、しています。", "record_answer", question_id="Q1", condition_id="はい")
        say(f, "たぶんカードだと思います。", "record_answer", question_id="Q2", condition_id="カード")
        by_reply = say(f, "いや、ちょっとわからないです。", "confirm_field", question_id="Q2", result="corrected", correction="わからない")
        # どちらも「承知しました。」（答えの報告の道は、直前の相づちも「承知しました。」なので「かしこまりました。」に替わる＝✅ 2026-11-02 日本時間7時12分。
        # 言い直しへの返事の道は、直前が言い直しの「はい、」）
        self.assertEqual([(r["result"], r["ack"]) for r in (by_answer, by_reply)], [("next", "kashikomari"), ("next", "shouchi")])
        # (b)
        def pamphlet():
            return Flow([yn("Q1", "パンフレットをお送りしてもよろしいでしょうか？", away=("いいえ",), reply_meanings={"結構": "いいえ"}),
                         yn("Q2", "ご不明な点はございますでしょうか？")], play_recordings=True)
        f = pamphlet()
        by_answer = say(f, "結構です。", "record_answer", question_id="Q1", condition_id="いいえ")
        g = pamphlet()
        by_unclear = say(g, "結構です。", "report_unclear", question_id="Q1")
        self.assertEqual((g.items["Q1"].state, g.items["Q1"].condition), ("accepted", "いいえ"))
        self.assertEqual([(r["result"], r["ack"]) for r in (by_answer, by_unclear)], [("next", "shouchi"), ("next", "shouchi")])
        # (c)（「わからない」は、ご希望を伺う質問なら保留で締める一言（頭は「承知しました。」）のあと、重いお詫びの録音から念のための確認へ＝✅ 2026-11-06
        # 日本時間11時19分55秒 ユーザー「(2) …「承知しました。それではパンフレットは保留とさせていただきますね。」とパンフレットは締めて、次へ」・
        # ほかのご希望を申し伝える一言のあとの念のための確認と同じ並び＝Flow._advance）
        for heard, cond in (("カードで。", "カード"), ("ちょっとわからないです。", "unknown")):
            f = Flow([yn("Q1", "ご予約はされていますでしょうか？", topic="ご予約"), pay()], play_recordings=True)
            for _ in range(3):
                say(f, "……", "report_unclear", question_id="Q1")
            r = say(f, heard, "record_answer", question_id="Q2", condition_id=cond)
            if cond == "unknown":
                self.assertEqual((r["result"], r["ack"], [p["id"] for p in r["play"]][:2]), ("recheck", "shouchi", ["Q2_pending", "moushiwake_heavy"]))
            else:
                self.assertEqual((r["result"], r["ack"]), ("recheck", "moushiwake_heavy"), heard)
        # (d)
        f = Flow([Question("Q1", "ご来店のご希望の日時をお聞かせいただけますでしょうか？", "datetime", conditions=("答えた",)),
                  yn("Q2", "ほかの日時もご検討いただけますでしょうか？", ask_if=("Q1", ("答えた",)), ask_if_hedged=True),
                  yn("Q3", "ご不明な点はございますでしょうか？")], play_recordings=True)
        say(f, "たぶん15日の午後2時がいいと思います。", "record_answer", question_id="Q1", condition_id="答えた", value="15日の14時")
        r = say(f, "たぶんそれで大丈夫だと思います。", "confirm_field", question_id="Q1", result="affirmed")
        self.assertEqual((r["result"], r["ack"], r.get("question_id")), ("next", "hai", "Q2"))

    def test_a_turned_down_answer_is_never_restated_in_its_own_direction(self):
        # 目的から遠ざかる向きの言葉で言い直さない（✅ 2026-11-03 ユーザー：「最終目的に繋がるクロージングはマイナスの言葉で締めない」）の「遠ざかる向き」は、
        # 相づち・締めと同じ1か所（Question.turned_down）。⛔ 言い直さずに受け取るかを、遠ざかる向きの選択肢（away_answers）と「どれも要らない」だけで
        # 決めていたので、説明した内容のご承認への言い切っていない「いいえ」を「それではご説明した内容ではご承認いただけないということで承りますね？」と
        # 言い直していた。いまは言い直さずに受け取り（「曖昧」の印とお客様の言葉）、ご納得いただけなかった点を伺う（言い切ったときと同じ）
        from flowctl import CALLBACK_IDS, Flow, Question
        say = self._say
        def approval():
            return Flow([Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True,
                                  meanings={"はい": "ご説明した内容でご承認いただける", "いいえ": "ご説明した内容ではご承認いただけない"}),
                         Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], play_recordings=True)
        f = approval()
        hedged = say(f, "うーん、たぶん難しいかもしれません。", "record_answer", question_id="Q1", condition_id="いいえ")
        g = approval()
        firm = say(g, "いいえ、承認できません。", "record_answer", question_id="Q1", condition_id="いいえ")
        self.assertEqual([(r["result"], r["ack"], r.get("question_id")) for r in (hedged, firm)],
                         [("next", "hai", CALLBACK_IDS["not_agreed"])] * 2)
        self.assertEqual((f.items["Q1"].state, f.items["Q1"].hedged, g.items["Q1"].hedged),
                         ("accepted", "うーん、たぶん難しいかもしれません。", None))

    def test_the_hedged_mark_comes_from_the_customers_words_on_every_path(self):
        # 言い切っていないかの印（依頼者へ渡すお客様の言葉 customer_words・最終目的の言い切っていないお断りにほかのご希望を伺うか wish_trigger）は、
        # お客様の言葉で決める（Flow._hedged の1か所）。⛔ 言い直さずに受け取る所（_keep_toward_goal）が、確かめ方の種類が hedged のときだけ印を付けて
        # いたので、(a) 言い直しへの訂正の「いや、たぶん要らないかもしれません。」(b) 事実を伺う質問への言い切っていない答え、では印が付かず、最終目的は
        # ほかのご希望を伺わずに締め（✅ 2026-11-03 日本時間21時38分「はい／いいえで伺う最終目的の質問に、言い切っていないお断りをいただいた場合は、
        # (1) ほかのご希望を1回だけ伺う」）、依頼者へお客様の言葉が渡らなかった（✅ 2026-10-18 ユーザー：案C）
        from flowctl import CALLBACK_IDS, Flow, Question
        say = self._say
        def goal(**kw):
            return Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"), final_goal=True,
                                  declines=("いいえ",), meanings={"はい": "パンフレットをお送りしてよい", "いいえ": "パンフレットはお送りしない"},
                                  do_words={"はい": "パンフレットをお送りさせていただきます"}, **kw),
                         Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], play_recordings=True)
        first = goal()
        say(first, "たぶん要らないかもしれません。", "record_answer", question_id="Q1", condition_id="いいえ")
        corrected = goal()
        say(corrected, "大丈夫です。", "record_answer", question_id="Q1", condition_id="はい")
        say(corrected, "いや、たぶん要らないかもしれません。", "confirm_field", question_id="Q1", result="corrected", correction="いいえ")
        fact = goal(asks_fact=True)
        say(fact, "たぶん要らないかもしれません。", "record_answer", question_id="Q1", condition_id="いいえ")
        self.assertEqual([(f.current, f.end_reason) for f in (first, corrected, fact)], [(CALLBACK_IDS["other_wish"], None)] * 3)
        # 最終目的でない遠ざかる向きの答え：事実を伺う質問かどうかで、依頼者へ渡すお客様の言葉が変わらない
        for asks_fact in (False, True):
            f = Flow([Question("Q1", "今月中のご導入はご検討されていますでしょうか？", "yes_no", conditions=("はい", "いいえ"), away=("いいえ",),
                               asks_fact=asks_fact),
                      Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))])
            say(f, "たぶん今月は難しいかもしれません。", "record_answer", question_id="Q1", condition_id="いいえ")
            self.assertEqual(f.customer_words(), {"Q1": "たぶん今月は難しいかもしれません。"}, asks_fact)

    def test_the_ai_is_told_the_same_lead_in_as_the_recording(self):
        # 次の質問の頭のつなぎの言葉は、録音の形とAIが話す形で同じ1か所（spoken_question）：質問の順番で「それでは」「続きまして」「では」、前の答えで
        # 伺う質問は「それでは」、入る一言があればそれ。⛔ AIが話す形は、つなぎの言葉を流した回数で回していて、前の答えで伺う質問にも「続きまして」、
        # 伺わなかった質問を挟むと順番の言葉がずれた（「はい、届いています。」のあとの Q4 に「それでは」＝録音は「続きまして」）
        from flowctl import Flow, Question
        say = self._say
        yn = lambda i, t, **k: Question(i, t, "yes_no", conditions=("はい", "いいえ"), **k)
        qs = lambda: [yn("Q1", "ご予約はされていますでしょうか？"), yn("Q2", "資料はお手元に届いていますでしょうか？"),
                      yn("Q3", "お送りし直してもよろしいでしょうか？", ask_if=("Q2", ("いいえ",))),
                      yn("Q4", "ご不明な点はございますでしょうか？")]
        for heard, cond, nxt in (("いえ、届いていません。", "いいえ", "Q3"), ("はい、届いています。", "はい", "Q4")):
            told, played = Flow(qs()), Flow(qs(), play_recordings=True)
            replies = []
            for f in (told, played):
                say(f, "はい、しています。", "record_answer", question_id="Q1", condition_id="はい")
                replies.append(say(f, heard, "record_answer", question_id="Q2", condition_id=cond))
            self.assertEqual([r["question_id"] for r in replies], [nxt, nxt])
            lead = replies[1]["play"][0]["lead"]
            self.assertTrue(lead)
            self.assertIn(f"「{lead}」から話し始めてください", replies[0]["message"], nxt)

    def test_the_point_step_does_not_start_from_an_earlier_answer_mid_call(self):
        # 前の通話の答えから、続きの電話の途中で、ほかの答えのすぐあとに追う手順を始めない（ほかのご希望＝_wish_due と同じ決まり。続きの電話の途中で
        # 「ご納得いただけなかった点はどの部分になりますでしょうか？」と伺うと、話がつながらない）。⛔ ご承認いただけなかったときの手順（_point_step）は
        # 前の通話の答えを除いていなかった
        from flowctl import Flow, Question
        say = self._say
        # 前の通話で、ご納得いただけなかったときの手順を伺い終えた答え（"point"＝earlier_point が手順の終わり）。伺い終えていなければ、続きの電話の始めに
        # 伺う（点の答えの前に切れた＝下の試験・点まで伺えた＝ご説明から＝test_a_point_heard_then_cut_resumes_with_the_explanation）
        f = Flow([Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True),
                  Question("Q2", "ご来店の人数をお伺いしてもよろしいでしょうか？", "number", conditions=("答えた",), unit="人"),
                  Question("Q3", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))],
                 play_recordings=True, earlier={"Q1": {"state": "accepted", "condition": "いいえ", "point_fact": {"question": "Q1", "point": None, "outcome": "unresolved"}}})
        self.assertEqual(f.current, "Q2")
        say(f, "3人です。", "record_answer", question_id="Q2", condition_id="答えた", value="3人")
        r = say(f, "はい、3人です。", "confirm_field", question_id="Q2", result="affirmed")
        self.assertEqual((r["result"], r.get("question_id")), ("next", "Q3"))

    def test_a_point_step_cut_off_resumes_right_after_the_apology(self):
        # ✅ 2026-11-04 日本時間18時16分 ユーザー「はい、OK」：ご納得いただけなかった点を伺う途中で切れた電話の続きは、ほかのご希望（11-03 日本時間23時52分36秒の
        # (ア)）と同じく、お詫び（と用件の一文）のすぐあとに「前回お伺いした件でご納得いただけなかった点はどの部分になりますでしょうか？」（共通の一言の録音
        # callback_not_agreed_again）。前の通話の答えに "point" が無い＝N1 の答えをいただく前に切れた（resumed_step の1か所）。名乗りの録音の最後と流れの制御の
        # 始めは同じ質問（opening_question）。手順を伺い終えるまで、最終目的のご承認のお断りでも締めない
        from flowctl import CALLBACK_IDS, Question, earlier_point
        from instruction import Business
        from phrases import CALLBACK_ASK_RESUMED
        say = self._say
        approval = lambda **k: Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                                        approval=True, **k)
        rest = [Question("Q2", "ご来店の人数をお伺いしてもよろしいでしょうか？", "number", conditions=("答えた",), unit="人"),
                Question("Q3", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))]
        def business(earlier, **k):
            return Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付",
                            questions=[approval(**k), *rest], earlier=earlier, apology=("cut_off",))
        resumed = CALLBACK_ASK_RESUMED["not_agreed"]
        self.assertEqual(resumed, "前回お伺いした件でご納得いただけなかった点はどの部分になりますでしょうか？")
        b = business({"Q1": {"state": "accepted", "condition": "いいえ"}})
        f = b.flow(play_recordings=True)
        self.assertEqual((b.first_ask(), f.current), ((CALLBACK_IDS["not_agreed"], resumed), CALLBACK_IDS["not_agreed"]))
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r = r if r.get("result") == "opening" else f.on_first_words_end()
        last = r["play"][-1]
        self.assertEqual((last["id"], last["text"]), ("callback_not_agreed_again", resumed))
        self.assertIn("前回はお電話が途中で切れてしまい大変失礼いたしました。", [p["text"] for p in r["play"]])
        # 点を伺ったあとは、この通話で伺ったときと同じ手順（ご説明の段へ）
        r = say(f, "料金の部分がよく分からなかったんです。", "record_answer", question_id=CALLBACK_IDS["not_agreed"], condition_id="点を言った",
                value="料金の部分")
        self.assertEqual((f.point["stage"], f.facts["not_agreed"][0]["point"]), ("explain", "料金の部分"))
        # 目的のお客様のいる業務：繋がってから、お詫び・用件のあとに「前回お伺いした件で…」（ほかのご希望の続きと同じ順＝NoneOfThemTest.test_cut_during_wish_resumes_after_apology の目的のお客様）
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        from instruction import Target
        t = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"), questions=[approval(), *rest],
                                earlier={"Q1": {"state": "accepted", "condition": "いいえ"}})
        f = Flow(t.questions, play_recordings=True, opening=t.replay_parts(), target=t.replay_parts(), apology=("cut_off",), earlier=t.earlier)
        self.assertIsNone(f.current)
        r = TargetTest.say(f, "はい、岡田は私ですが。", "report_party", party="target")
        self.assertEqual([p.get("part") or p.get("id") or p["kind"] for p in r["play"]], ["apology_cut_off", "purpose", "callback_not_agreed_again"])
        self.assertEqual((r["question_id"], r["play"][-1]["text"]), (CALLBACK_IDS["not_agreed"], resumed))
        # 前の通話で手順を終えた答え（"point" が手順の終わりの結果）には伺わない（点まで伺えた heard は、ご説明から始める＝test_a_point_heard_then_cut_resumes_with_the_explanation）
        for done in ("agreed", "declined", "unresolved"):
            b = business({"Q1": {"state": "accepted", "condition": "いいえ", "point_fact": {"question": "Q1", "point": None, "outcome": done}}})
            self.assertEqual((b.first_ask()[0], b.flow(play_recordings=True).current), ("Q2", "Q2"), done)
        # 最終目的のご承認：手順を伺い終えるまで「目的が果たせない」で締めない
        b = business({"Q1": {"state": "accepted", "condition": "いいえ"}}, final_goal=True)
        f = b.flow(play_recordings=True)
        self.assertEqual((f.current, f._goals_lost()), (CALLBACK_IDS["not_agreed"], None))
        # 前の通話の答えの "point" の読み方（CL-2 が通話の事実 not_agreed の最後のものから入れる）：点を伺った＝heard・手順を終えた＝その結果。
        # 点を伺わずに手順を終えても（N1 の答えがどちらとも取れず、手順を終えた）、事実が残る
        self.assertEqual((earlier_point({"point": "料金"}), earlier_point({"point": None, "outcome": "declined"})), ("heard", "declined"))
        from flowctl import Flow
        g = Flow([approval(meanings={"はい": "ご説明した内容でご承認いただける", "いいえ": "ご説明した内容ではご承認いただけない"}), *rest])
        say(g, "いいえ、承認できません。", "record_answer", question_id="Q1", condition_id="いいえ")
        say(g, "うーん、なんとも言えないですね。", "record_answer", question_id=CALLBACK_IDS["not_agreed"], condition_id="unknown")
        self.assertEqual([(e["question"], e["point"], earlier_point(e)) for e in g.facts["not_agreed"]], [("Q1", None, "unresolved")])

    def test_a_retaken_answer_rests_on_the_answer_that_decided_it(self):
        # この通話で決め直した答え（ご承認いただけなかったときの手順でご納得いただいた＝Flow._point_end・ほかのご希望で元の質問の選択肢を選び直して
        # いただいた＝Flow._wish_step）は、決め直す1か所（Flow._retake）を通る：前の通話で取れた答えでも、この通話の答えとして依頼者へ渡す（export）・
        # 前の答えの言い切っていない言葉は渡さない・その答えのあとに伝える一言はまだ言っていない・前の答えの発話に遅れて届いた確かめは当てない。
        # F0（2026-11-08 日本時間9時台）：決め手の答え（N2・N3・W1）に遅れて届いた確かめは、同じ読みでも食い違っても、決め直した答えに当てず記録（決め手の答えの
        # late）に残すだけ・届かなかった確かめに数える（⛔ F0 の前は、食い違えば決め直した答えを渡さず、決め直す前の答え（11-06 7時台までは「-」）へ戻していた）。
        # ⛔ 2026-11-04 日本時間18時台（18時16分のご承認を入れたあとの見直し）に見つけた：続きの電話でご納得いただいても、依頼者へ渡す答えに「はい」が
        # 入らなかった・この通話でも、前の「いいえ」の発話の判定が遅れて別の読みで届くと、ご納得いただいた「はい」が「-」に戻った・はい／いいえの質問の
        # 選び直しは、同じ向きの確かめが遅れて届いても「-」になった（W1 の選択肢の名前「やはり…」と元の質問の選択肢の名前「はい」が違う）
        from flowctl import CALLBACK_IDS, Flow, Question
        say, n1, n2 = self._say, CALLBACK_IDS["not_agreed"], CALLBACK_IDS["other_point"]
        thanks = "ありがとうございます。それでは今後の流れをご案内いたします。"
        def flow(earlier=None):
            f = Flow([Question("Q1", "以上の内容でよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True, tell_words={"はい": thanks},
                               meanings={"はい": "ご説明した内容でご承認いただける", "いいえ": "ご説明した内容ではご承認いただけない"}),
                      Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))],
                     play_recordings=True, answers={"料金": "料金は月額3,000円で、初月は無料となっております。"}, earlier=earlier, apology=("cut_off",) if earlier else ())
            f.use_checks("judge", "judge2")
            return f
        def agree(f):
            say(f, "料金のところですね。", "record_answer", question_id=n1, condition_id="点を言った", value="料金のところ")
            f.on_check("judge", "点を言った"); f.on_check("judge2", "点を言った")
            ApprovalTest.explained(f, "answer_料金")
            r = say(f, "だいたい分かりました。", "record_answer", question_id=n2, condition_id="分かった")
            f.on_check("judge", "分かった")
            return r, f.callee_turns
        # (1) 続きの電話（前の通話の答えは「いいえ」・言い切っていない）でご納得いただいた：この通話の答え「はい」を渡す・前の言葉は渡さない・一言を流す
        f = flow({"Q1": {"state": "accepted", "condition": "いいえ", "hedged": "ちょっと難しいかもしれません"}})
        r, _ = agree(f)
        self.assertEqual((f.export(), "Q1" in f.customer_words()), ({"Q1": "はい", "Q2": "-"}, False))
        self.assertIn(thanks, [p.get("text") for p in r.get("play") or []])
        # (2) この通話で：ご納得のあと、前の「いいえ」の発話の判定が遅れて別の読みで届いても、ご納得いただいた「はい」のまま
        f = flow()
        say(f, "いいえ、ちょっと承認できません。", "record_answer", question_id="Q1", condition_id="いいえ")
        f.on_check("judge", "いいえ")
        no_turn = f.callee_turns
        _, ok_turn = agree(f)
        f.on_check("judge2", "unknown", turn=no_turn, said="いいえ、ちょっと承認できません。")
        self.assertEqual(f.export()["Q1"], "はい")
        # (3) 決め手の返事（「だいたい分かりました。」）の確かめが遅れて届いた。F0（2026-11-08 日本時間9時台）：同じ読みでも食い違っても「はい」のまま・手順の結果
        # （ご納得）・いまの質問も変えず、決め手の答えの記録（late）に残すだけ（⛔ F0 の前は、食い違えば決め直す前の確かめた「いいえ」へ戻していた）
        f.on_check("judge2", "分かった", turn=ok_turn, said="だいたい分かりました。")
        self.assertEqual(f.export()["Q1"], "はい")
        g = flow()
        say(g, "いいえ、ちょっと承認できません。", "record_answer", question_id="Q1", condition_id="いいえ")
        g.on_check("judge", "いいえ"); g.on_check("judge2", "いいえ")
        _, ok_turn = agree(g)
        before = (g.export(), g.current, g.point["outcome"])
        g.on_check("judge2", "分からない点がある", turn=ok_turn, said="だいたい分かりました。")
        self.assertEqual((g.export()["Q1"], g.items["Q1"].state, (g.export(), g.current, g.point["outcome"])), ("はい", "accepted", before))
        self.assertEqual((before[1:], g.taken[n2]["late"]["judge2"], g.unchecked()[n2]), (("Q2", "agreed"), "分からない点がある", ["judge", "judge2"]))
        # (4) ほかのご希望の選び直し（はい／いいえの質問・W1 の選択肢の名前は「やはり（意味の言葉）」）：同じ向きの確かめが遅れて届いても「はい」のまま
        pick = "やはりパンフレットをお送りしてよいということ"
        h = Flow([Question("Q1", "パンフレットをお送りしてもよろしいでしょうか？", "yes_no", conditions=("はい", "いいえ"), final_goal=True, declines=("いいえ",),
                           meanings={"はい": "パンフレットをお送りしてよいということ", "いいえ": "パンフレットはお送りしないということ"}),
                  Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))],
                 earlier={"Q1": {"state": "accepted", "condition": "いいえ", "hedged": "届いても見るか分からなくて"}})
        h.use_checks("judge", "judge2")
        self.assertEqual(h.current, "W1")
        say(h, "うーん、やっぱり送ってください。", "record_answer", question_id="W1", condition_id=pick)
        h.on_check("judge", pick)
        self.assertEqual(h.export()["Q1"], "はい")
        h.on_check("judge2", pick, turn=h.callee_turns, said="うーん、やっぱり送ってください。")
        self.assertEqual((h.export()["Q1"], "Q1" in h.customer_words()), ("はい", False))
        # 決め手の発話（選び直した発話）は、決め直した答えの根拠として読める（ここで終える答えの根拠など＝Flow._evidence の1か所）
        self.assertEqual(h._evidence("Q1")["said"], "うーん、やっぱり送ってください。")

    def test_a_substitute_on_a_continued_call_starts_the_sales_from_the_beginning(self):
        # ✅ 2026-11-07 日本時間3時14分01秒 ユーザー「(3) H6：なぜ判断いただける方に対して電話を切ろうとするんですか？しかも電話が途中で切れることは代わりの方には
        # 関係ない話ですよね。しっかりと営業の最初からもしくは引き継がれている部分から確認していかないといけないんじゃないですか。」＝本書 9-4 の「代わりの方の申し出」
        # （判断いただけるなら代わりの方として話す・依頼者へ渡す答えは代わりの方の答えと印を付ける）：前の通話の答えはお呼びした方ご本人の答えなので、続きの電話で
        # 判断いただける代わりの方に繋がったら、前の通話の答えで伺わずに済ませていた質問・続きの電話の始めの段（申し伝え直し・ほかのご希望・ご承認の手順）を外し、
        # 営業の最初の質問から伺う（お詫び・申し伝える一言は流さない）。⛔ それまでは申し伝え直す電話（ご承認が最終目的）で「お忙しいところ…」と締め、
        # 前の答えのある続きの電話では残りの質問だけを伺った
        from flowctl import TARGET_IS_AWAY, Question
        from instruction import Business, Target
        from phrases import APOLOGY_CUT_END, TOLD_AGAIN
        told = {"Q1": {"state": "accepted", "condition": "いいえ",
                       "point_fact": {"question": "Q1", "point": "料金のところ", "said": "料金のところがよく分からなかったんです。", "explained": False,
                                      "told": "request", "outcome": None}}}
        q1 = Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True, final_goal=True,
                      declines=("いいえ",))
        q1b = Question("Q1", q1.text, "yes_no", conditions=("はい", "いいえ"), approval=True, declines=("いいえ",))
        q2 = Question("Q2", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",))
        for name, qs, earlier in (("told/final", [q1], told), ("told/rest", [q1b, q2], told),
                                  ("plain resumed", [q1b, q2], {"Q1": {"state": "accepted", "condition": "はい"}})):
            b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=qs,
                         purpose_line="資料送付の件でお電話いたしました。", earlier=earlier, apology=("cut_off",), apology_when="later",
                         target=Target(name="岡田", reading="おかだ", role="営業部部長"))
            f = b.flow(play_recordings=True)
            f.use_checks("judge")
            f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
            r = f.apply("report_party", {"party": "person"})
            r if r.get("result") in ("opening", "end") else f.on_first_words_end()
            f.on_callee(); f.on_heard("岡田は本日不在にしておりまして、代わりに私がご用件を伺います。"); f.on_check("judge", TARGET_IS_AWAY)
            f.apply("report_party", {"party": "substitute"})
            f.on_callee(); f.on_heard("はい、私が責任者ですので大丈夫です。"); f.on_check("judge", "判断できる")
            r = f.apply("record_answer", {"question_id": "S1", "condition_id": "判断できる"})
            said = "".join(p["text"] for p in r.get("play") or [])
            self.assertEqual((r.get("result"), r.get("question_id"), f.end_reason), ("next", "Q1", None), name)
            self.assertFalse(any(t in said for t in (*APOLOGY_CUT_END.values(), *TOLD_AGAIN.values(), "途中で切れて")), (name, said))
            self.assertTrue(said.endswith(q1.text), (name, said))

    # 続きの電話の始めの段（前の通話で伺っている途中で切れた手順＝resumed_step）の場面：前の通話の答えと、その答えの業務の質問
    _CUT_CONTACT = "ご連絡はお電話とメールのどちらがよろしいでしょうか？"

    def _cut_scenes(self):
        from flowctl import Question
        qc = Question("Q1", self._CUT_CONTACT, "choice", conditions=("電話", "メール"), final_goal=True, topic="ご連絡の方法")
        qd = Question("Q2", "ご不明な点はございますでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        q1 = Question("Q1", "当日はお車でお越しでしょうか？", "yes_no", conditions=("はい", "いいえ"))
        q2 = Question("Q2", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True,
                      declines=("いいえ",), intro="ご説明させていただきます。初期費用はかかりません。")
        none = {"state": "accepted", "value": None, "condition": "どれも要らない"}
        declined = {"Q1": {"state": "accepted", "condition": "はい"}, "Q2": {"state": "accepted", "condition": "いいえ"}}
        point = {"question": "Q2", "point": "料金のところ", "said": "料金のところがよく分からなかったんです。", "explained": None, "outcome": None}
        return {
            "other_wish": ([qc, qd], {"Q1": {**none, "wish_fact": {"question": "Q1", "means": None, "contact": None, "outcome": None, "via": None}}}),
            "email": ([qc, qd], {"Q1": {**none, "wish_fact": {"question": "Q1", "means": "email", "contact": None, "outcome": None, "via": None}}}),
            "not_agreed": ([q1, q2], declined),
            "explain": ([q1, q2], {**declined, "Q2": {**declined["Q2"], "point_fact": point}}),
            "told": ([q1, q2], {**declined, "Q2": {**declined["Q2"], "point_fact": {**point, "explained": False, "told": "request"}}}),
        }

    @staticmethod
    def _cut_call(qs, earlier):
        from instruction import Business, Target
        b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=qs,
                     purpose_line="資料送付の件でお電話いたしました。", earlier=earlier, apology=("cut_off",), apology_when="later",
                     target=Target(name="岡田", reading="おかだ", role="営業部部長"))
        f = b.flow(play_recordings=True)
        f.use_checks("judge")
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r if r.get("result") in ("opening", "end") else f.on_first_words_end()
        return f

    def test_a_substitute_on_a_continued_call_is_spoken_to_as_on_a_first_call(self):
        # ✅ 2026-11-07 日本時間3時14分01秒 ユーザー「(3) H6：…電話が途中で切れることは代わりの方には関係ない話ですよね。しっかりと営業の最初からもしくは
        # 引き継がれている部分から確認していかないといけないんじゃないですか。」＝続きの電話で判断いただける代わりの方に繋がったら、前の通話の答え（お呼びした方
        # ご本人の答え）から作るもの（続きの電話の始めの段）は何も残さず、前の通話の答えの無い電話で同じ手順を通ったときと、流れの制御の状態も、そのあとの
        # お客様に聞こえる言葉も同じ。⛔ 2026-11-08 日本時間0時台（11-07 23時26分13秒のご質問の見直し B-7）：始めの段を電話の始めに作り、代わりの方のときに
        # 外す所（_start_over）が一部しか外さなかったので、(1) ご承認のお断りで例外（KeyError 'N1'）で止まった (2) 「どれも要らない」に W1 を伺わなかった
        # (3) 前の電話がご説明の途中で切れていると、代わりの方の「判断できる」を受け取らず、何も流さなかった
        from flowctl import NONE, TARGET_IS_AWAY
        from meaning_judge import Reading

        def substitute(qs, earlier):
            f = self._cut_call(qs, earlier)
            f.on_callee(); f.on_heard("岡田は本日不在にしておりまして、代わりに私がご用件を伺います。"); f.on_check("judge", TARGET_IS_AWAY)
            f.apply("report_party", {"party": "substitute"})
            f.on_callee(); f.on_heard("はい、私が責任者ですので大丈夫です。"); f.on_check("judge", "判断できる")
            return f, f.apply("record_answer", {"question_id": "S1", "condition_id": "判断できる"})

        def answer(f, qid, cond, words):
            f.on_callee(); f.on_heard(words); f.on_check("judge", Reading(cond))
            return f.apply("record_answer", {"question_id": qid, "condition_id": cond})

        def same(a, b, ra, rb, name):
            self.assertEqual((ra.get("result"), ra.get("question_id"), ra.get("play"), ra.get("say")),
                             (rb.get("result"), rb.get("question_id"), rb.get("play"), rb.get("say")), name)
            va, vb = vars(a), vars(b)
            self.assertEqual({k: repr(va.get(k)) for k in set(va) | set(vb) if k not in ("earlier", "earlier_all") and repr(va.get(k)) != repr(vb.get(k))},
                             {}, name)

        for name, (qs, earlier) in self._cut_scenes().items():
            (a, ra), (b, rb) = substitute(qs, earlier), substitute(qs, {})
            self.assertEqual((ra.get("result"), ra.get("question_id")), ("next", "Q1"), name)
            same(a, b, ra, rb, name)
            if qs[0].text == self._CUT_CONTACT:   # 代わりの方の「どれも要らない」にも、ほかのご希望を1回伺う（W1）
                ra, rb = (answer(f, "Q1", NONE, "うーん、どちらも要らないですね。") for f in (a, b))
                self.assertEqual(ra.get("question_id"), "W1", name)
            else:                                 # 代わりの方のご承認のお断りにも、ご納得いただけなかった点を伺う（N1）
                ra, rb = answer(a, "Q1", "はい", "はい、車で行きます。"), answer(b, "Q1", "はい", "はい、車で行きます。")
                same(a, b, ra, rb, name)
                ra, rb = answer(a, "Q2", "いいえ", "いや、それはちょっと。"), answer(b, "Q2", "いいえ", "いや、それはちょっと。")
                self.assertEqual(ra.get("question_id"), "N1", name)
            same(a, b, ra, rb, name)

    def test_a_continued_call_resumes_where_it_was_cut_also_after_the_person_comes_back(self):
        # 続きの電話の始めの段は、お呼びした方ご本人に繋がったときに、どの道で繋がっても同じに伺う（前の通話の答えはご本人の答え）：受付の方の「不在」から
        # かけ直しの質問を伺ったあとにご本人が戻られて繋がっても、すぐご本人が出たときと同じく、切れた所から伺う（お詫び・申し伝え直しも同じ）。
        # ⛔ 2026-11-08 日本時間0時台（11-07 23時26分13秒のご質問の見直しの B-7 の確かめで見つけた）：始めの段を電話の始めに作っていたので、並びを業務の
        # 質問に戻す所（_target_back）が始めの段の質問を消し、W1 の続きは伺わずに次の質問へ・ご承認の手順の続きは、お詫びのあとすぐ「お忙しいところお時間を
        # いただきましてありがとうございました。それでは失礼いたします。」で締めた
        from flowctl import HOLD, TARGET_IS_AWAY, TARGET_IS_THERE

        def connected(qs, earlier, back):
            f = self._cut_call(qs, earlier)
            if back:
                f.on_callee(); f.on_heard("あいにく岡田は席を外しております。"); f.on_check("judge", TARGET_IS_AWAY)
                self.assertEqual(f.apply("request_callback", {"why": "absent"})["question_id"], "C1")
                f.on_callee(); f.on_heard("あ、ちょうど戻ってまいりました。少々お待ちください。"); f.on_check("judge", HOLD)
                f.apply("report_party", {"party": "reception"})
                f.on_callee(); f.on_heard("お電話代わりました。岡田です。"); f.on_check("judge", TARGET_IS_THERE)
                self.assertEqual(f.apply("report_party", {"party": "target"})["result"], "confirm_target")
                f.on_callee(); f.on_heard("はい、そうです。"); f.on_check("judge", TARGET_IS_THERE)
            else:
                f.on_callee(); f.on_heard("お電話代わりました。岡田です。"); f.on_check("judge", TARGET_IS_THERE)
            r = f.apply("report_party", {"party": "target"})
            # 名乗りの前（すぐ出たご本人には名乗りは流してある）を除いた、お詫びからあとの声
            play = r.get("play") or []
            at = next(i for i, p in enumerate(play) if p.get("kind") == "recorded" and p["id"].startswith("apology_"))
            return f, r, play[at:]

        for name, (qs, earlier) in self._cut_scenes().items():
            (a, ra, pa), (b, rb, pb) = connected(qs, earlier, False), connected(qs, earlier, True)
            self.assertEqual((rb.get("result"), rb.get("question_id"), pb, rb.get("speak"), b.end_reason),
                             (ra.get("result"), ra.get("question_id"), pa, ra.get("speak"), a.end_reason), name)
            self.assertEqual((b.order, b.current, b.follow_ups, b.wish, b.point), (a.order, a.current, a.follow_ups, a.wish, a.point), name)
            self.assertIsNone(b.end_reason if name != "told" else None, name)
        # ご本人に繋がる前（受付の方の不在・かけ直しの質問のあと）に切れても、前の通話から続く手順は伺い終えていない（報告の unfinished＝次の電話でまた切れた
        # 所から。前の通話の答えから読む決まりは、始めの段と同じ1か所＝申し伝え直す一言を言う前に切れたときも）
        from flowctl import resumed_step
        for name, (qs, earlier) in self._cut_scenes().items():
            f = self._cut_call(qs, earlier)
            f.on_callee(); f.on_heard("あいにく岡田は席を外しております。"); f.on_check("judge", TARGET_IS_AWAY)
            f.apply("request_callback", {"why": "absent"})
            self.assertEqual(f.report()["unfinished"], [resumed_step(qs, earlier)[1].id], name)

    def test_told_then_cut_says_it_again_after_the_apology_and_closes(self):
        # ✅ 2026-11-06 日本時間9時05分17秒 ユーザー：「(b) 前の電話で「…担当の者に申し伝えさせていただきますね。」まで言ったあとに切れた場合：「先ほどは（前回は）、
        # お話の最後に通信が悪く、お電話が切れてしまい申し訳ございませんでした。」「～の件は、担当の者に申し伝えさせていただきますね。」もしくは「折り返し、担当の者より
        # ご連絡させていただきますね。」と言って、最後の挨拶で締めくくる。」
        # ⇒ 前の電話で、ご説明できない点の一言（申し伝える一言）を流したあと、お客様の返事の前に切れた（記録はご説明できなかった＝explained False・手順の終わりは無い）：
        # 前の通話の答えの読み方は「申し伝えた（told）」（⛔ それまでは「点は伺った（heard）」と読み、次の電話で同じ申し伝える一言をくり返した＝5時56分55秒の
        # ご質問の読み直し EN-D の指摘7）。次の電話は、名乗りのあとにお詫び（お話の最後に切れた＝同じ日は「先ほどは」・あとの日は「前回は」）と、申し伝える一言
        # （前の電話の種類＝ご質問・ご要望・ご意見の件。担当から連絡すると申し出てよい業務は「折り返し…」）を流し、残りの質問が無ければ最後のあいさつで締める
        from flowctl import POINT_OUTCOMES, earlier_point, resumed_step
        from instruction import Business
        from phrases import APOLOGY_CUT_END, CLOSING, TOLD_AGAIN, TOLD_FOLLOW_UP
        from flowctl import Question
        q1 = Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True,
                      final_goal=True, declines=("いいえ",))
        told = {"Q1": {"state": "accepted", "condition": "いいえ",
                       "point_fact": {"question": "Q1", "point": "料金のところ", "said": "料金のところがよく分からなかったんです。", "explained": False,
                                      "told": "request", "outcome": None}}}
        self.assertEqual(("told" in POINT_OUTCOMES, earlier_point(told["Q1"]["point_fact"])), (True, "told"))

        def business(when="later", follow_up=False, rest=()):
            return Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=[q1, *rest],
                            purpose_line="資料送付の件でお電話いたしました。", earlier=told, apology=("cut_off",), apology_when=when, follow_up=follow_up)
        self.assertEqual(resumed_step(business().questions, told)[0], "told")
        for when, follow_up in (("later", False), ("same_day", False), ("later", True)):
            b = business(when, follow_up)
            self.assertEqual((b.first_ask(), b.first_question()), (None, None))
            f = b.flow(play_recordings=True)
            f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
            r = f.apply("report_party", {"party": "person"})
            r = r if r.get("result") in ("opening", "end") else f.on_first_words_end()   # 残りの質問が無ければ、名乗りの返事で締める
            said = [p["text"] for p in r["play"]]
            # 申し伝える一言の「先ほど」「前回」は、お詫びと同じ（同じ日＝先ほど・あとの日＝前回）。⛔ 2026-11-06 日本時間23時22分41秒のご質問の見直し（H10）：
            # 申し伝える一言はいつも「前回お伺いした…」で、同じ日は「先ほどは…お電話が切れてしまい…」のすぐあとに「前回お伺いした…」と混ざった
            line = TOLD_FOLLOW_UP if follow_up else TOLD_AGAIN[f"request_{when}"]
            self.assertEqual(said[-3:], [APOLOGY_CUT_END[when], line, CLOSING], (when, follow_up))
            self.assertEqual((f.end_reason is not None, "goal_refused" in f.facts), (True, False), (when, follow_up))
        self.assertEqual((APOLOGY_CUT_END["same_day"], APOLOGY_CUT_END["later"], TOLD_AGAIN["request_same_day"], TOLD_AGAIN["request_later"],
                          TOLD_FOLLOW_UP),
                         ("先ほどはお話の最後に通信が悪くお電話が切れてしまい申し訳ございませんでした。",
                          "前回はお話の最後に通信が悪くお電話が切れてしまい申し訳ございませんでした。",
                          "先ほどお伺いしたご要望の件は担当の者に申し伝えさせていただきますね。",
                          "前回お伺いしたご要望の件は担当の者に申し伝えさせていただきますね。", "折り返し担当の者よりご連絡させていただきますね。"))
        # 残りの質問があれば、申し伝える一言のあと、その質問を伺う（締めない）。お詫びはお話の途中で切れた一言（今までどおり）
        # （ご承認が最終目的なら、申し伝え直したあとは締める＝最終目的でないご承認で作る）
        rest = (Question("Q2", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",)),)
        q1b = Question("Q1", q1.text, "yes_no", conditions=("はい", "いいえ"), approval=True, declines=("いいえ",))
        b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=[q1b, *rest],
                     purpose_line="資料送付の件でお電話いたしました。", earlier=told, apology=("cut_off",))
        f = b.flow(play_recordings=True)
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r = r if r.get("result") == "opening" else f.on_first_words_end()
        ids = [p.get("id") or p.get("part") for p in r["play"]]
        self.assertEqual((ids[-3:], f.current, f.end_reason), (["apology_cut_off", "told_again_request_later", "Q2"], "Q2", None))
        # 会話AIが話す通話（質問の録音が無い）：録音（お詫び・申し伝える一言）のあとに、会話AIに残りの質問を話させる（繋がったとき＝_connect と同じ1か所
        # _prepend_played）。⛔ 2026-11-06 日本時間13時台の見直し（ご承認の手順の持ち場の指摘9）で見つけた：話させる印が無く、録音のあと無言になった
        f = b.flow(play_recordings=False)
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r = r if r.get("result") == "opening" else f.on_first_words_end()
        self.assertEqual(([p.get("id") or p.get("part") for p in r["play"]][-2:], f.current, r.get("speak")), (["apology_cut_off", "told_again_request_later"], "Q2", True), r)
        # 申し伝え直す一言を流す前に電話が終わった（繋がっただけで第一声の前に切れた）：申し伝え直した記録は残さず、手順は終えていない（unfinished）＝次の電話で
        # また申し伝え直す。⛔ 2026-11-06 日本時間13時台の見直し（ご承認の手順の持ち場の指摘8）で見つけた：電話の始め（Flow.__init__）で「申し伝え直した・手順の
        # 終わり」と記録し、一言がお客様に届かないまま、次の電話の読みも「伺い終えた」になった
        from flowctl import earlier_point
        f = b.flow(play_recordings=True)
        f.on_connect()
        rep = f.report()
        self.assertEqual((rep["unfinished"], rep["facts"].get("not_agreed")), (["Q1"], None))
        self.assertEqual(f.told_again, "request")
        # 目的のお客様のいる業務で、ご本人に繋がる前に受付の方に「本日は休み」と言われて終えた：お詫び・申し伝える一言はご本人に流すので、まだ流れていない＝同じ
        from instruction import Target
        bt = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=[q1],
                      purpose_line="資料送付の件でお電話いたしました。", earlier=told, apology=("cut_off",), apology_when="later",
                      target=Target(name="岡田", reading="おかだ", role="営業部部長"))
        f = bt.flow(play_recordings=True)
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r = r if r.get("result") in ("opening", "end") else f.on_first_words_end()
        f.on_callee(); f.on_heard("岡田は本日休みです。")
        f.apply("request_callback", {"why": "day_off"})
        rep = f.report()
        # 申し伝え直す一言（told_again）も、ご本人に繋がった時に作る（続きの電話の始めの段の1か所 _resume_cut）＝繋がる前はまだ無い。伺い終えていないかは
        # 前の通話の答えから（earlier_point_open＝始めの段と同じ1か所）
        self.assertEqual((rep["unfinished"], rep["facts"].get("not_agreed"), f.told_again), (["Q1"], None, None))

    def test_opening_parts_are_what_the_flow_plays_on_a_told_call(self):
        # (10) の H2 の残り（11-08 日本時間8時台）：名乗りの録音の文（instruction.Business.opening_parts＝会話AIへの「プログラムが流す録音」の知らせ・名乗りの録音の
        # 組み立て）が、前の電話で申し伝える一言まで言って切れた続きの電話でも「途中で切れたお詫び」＋用件の一文を並べていた（流れの制御は、お話の最後に切れた
        # お詫び＋申し伝える一言を流し、用件の一文は流さない）。お詫びと申し伝える一言の並びは流れの制御と同じ1か所（flowctl.sorry_texts）から作る
        from flowctl import Question
        from instruction import Business
        from phrases import CLOSING
        q1 = Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True, declines=("いいえ",))
        told = {"Q1": {"state": "accepted", "condition": "いいえ",
                       "point_fact": {"question": "Q1", "point": "料金のところ", "said": "料金のところがよく分からなかったんです。", "explained": False,
                                      "told": "request", "outcome": None}}}
        rest = Question("Q2", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",))
        for final, more, when, follow_up in ((True, (), "later", False), (True, (), "same_day", True), (False, (rest,), "later", False),
                                             (False, (rest,), "same_day", False)):
            q = Question(q1.id, q1.text, "yes_no", conditions=q1.conditions, approval=True, declines=("いいえ",), final_goal=final)
            for earlier in (told, None):
                b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=[q, *more],
                             purpose_line="資料送付の件でお電話いたしました。", earlier=earlier, apology=("cut_off",) if earlier else (),
                             apology_when=when, follow_up=follow_up)
                f = b.flow(play_recordings=True)
                f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
                r = f.apply("report_party", {"party": "person"})
                r = r if r.get("result") in ("opening", "end") else f.on_first_words_end()
                said = [p["text"] for p in r["play"]]
                if said[-1] == CLOSING:
                    said = said[:-1]   # 申し伝え直したあとに締める電話の締めは、名乗りの録音ではない
                self.assertEqual(b.opening_parts(), said, (final, bool(more), when, follow_up, bool(earlier)))

    def test_a_point_heard_then_cut_resumes_with_the_explanation(self):
        # ✅ 2026-11-04 日本時間19時26分 ユーザー：「(A) 前の電話で点（「料金のところ」）までは伺えて、ご説明の途中で切れたとき。…お勧めは、点を伺い直さずに、
        # ご説明から始める形：OK」（お見せした形：お詫び（＋用件の一文）のあと、AIの言葉「前回お伺いした料金の件ですが、料金は月額3,000円で、初月は無料と
        # なっております。」→ お客様の返事 →「はい、ほかにご納得いただけない点はございますでしょうか？」）。前の通話の答えの "point" が heard（ご納得いただけ
        # なかった点は伺った）なら、続きの電話の始めに点を伺い直さず、AIが前の点（"point_said"）をご説明する（resumed_step の1か所）。名乗りの録音の最後に
        # 質問は無い（opening_question）。そのあとは、この通話でご説明したときと同じ（ほかに…・ご納得なら「はい」をこの通話の答えに）。⛔ それまで、続きの電話では
        # 何も伺わず、断られたともしないまま次の質問へ進んでいた
        from flowctl import CALLBACK_IDS, Question, earlier_point_said, resumed_step
        from grounding import GROUNDED
        from instruction import Business, build
        say, n2 = self._say, CALLBACK_IDS["other_point"]
        point = "料金のところがよく分からなかったんです。"
        explain = "前回お伺いした料金の件ですが、料金は月額3,000円で、初月は無料となっております。"
        approval = lambda **k: Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"),
                                        approval=True, **k)
        rest = [Question("Q2", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",))]
        def business(earlier, before=(), **k):
            return Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=[*before, approval(**k), *rest],
                            purpose_line="資料送付の件でお電話いたしました。", earlier=earlier, apology=("cut_off",),
                            info=["料金は月額3,000円で、初月は無料となっております。"])
        heard = {"Q1": {"state": "accepted", "condition": "いいえ", "point_fact": {"question": "Q1", "point": "料金のところ", "said": point, "outcome": None}}}
        # 前の通話の答えの読み方（CL-2 が通話の事実 not_agreed の最後のものから入れる）：点を伺ったときのお客様の言葉（無ければ点の値）。手順を終えていれば無し
        self.assertEqual((earlier_point_said({"point": "料金のところ", "said": point}), earlier_point_said({"point": "料金のところ", "said": ""}),
                          earlier_point_said({"point": "料金のところ", "said": point, "outcome": "agreed"})), (point, "料金のところ", None))
        # (1) 名乗りの録音の最後に質問は無い・流れの制御の始めも、いまの質問は無い（前の通話で伺えなかった質問 Q0 があっても、ご説明が先）
        q0 = Question("Q0", "ご担当者様のお名前をお伺いしてもよろしいでしょうか？", "name", conditions=("答えた",))
        b = business(heard, before=(q0,))
        self.assertEqual((resumed_step(b.questions, b.earlier)[0], b.first_ask(), b.first_question()), ("explain", None, None))
        f = b.flow(play_recordings=True)
        self.assertIsNone(f.current)
        _, text = build(b, "S2", opening_mode="recorded")
        self.assertIn("前回お伺いしたご納得いただけなかった点", text)
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r = r if r.get("result") == "opening" else f.on_first_words_end()
        # (2) お詫び・用件の一文のあと、AIがご説明する（点を伺い直さない）。録音のあとにAIが話す
        self.assertEqual([p.get("part") or p.get("id") for p in r["play"]][-2:], ["apology_cut_off", "purpose"])
        self.assertTrue(r.get("speak"))
        self.assertIn(f"「{point}」", r["message"])
        self.assertIn("前回お伺いした", r["message"])
        # AIのご説明の文の中身の判定には、前の電話で伺った点を、お客様の言葉として渡す（第一声ではない）
        self.assertEqual(f.grounding_job("replay_opening", {"part": "own", "answer": explain})[1], point)
        grounded(f, explain, GROUNDED)
        r = f.apply("replay_opening", {"part": "own", "answer": explain})
        self.assertEqual((r["result"], r["say"]), ("own_answer", explain))
        # (3) お客様の返事を聞いてから「はい、ほかに…」（前の通話で伺えなかった Q0 より先）
        f.on_callee(); f.on_heard("そうなんですね。")
        r = f.apply("replay_opening", {"part": "resume"})
        self.assertEqual((f.current, r["ack"]), (n2, "hai"))
        r = say(f, "だいたい分かりました。", "record_answer", question_id=n2, condition_id="分かった")
        self.assertEqual((f.export()["Q1"], f.current, f.end_reason), ("はい", "Q0", None))
        # (4) 目的のお客様のいる業務：繋がってから、お詫び・用件のあとにAIがご説明する
        import dataclasses
        from g22_opening import BUSINESS
        from instruction import Target
        t = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長"), questions=[approval(), *rest], earlier=heard,
                                info=["料金は月額3,000円で、初月は無料となっております。"], apology=("cut_off",))
        g = t.flow(play_recordings=True)
        self.assertIsNone(g.current)
        r = TargetTest.say(g, "はい、岡田は私ですが。", "report_party", party="target")
        self.assertEqual(([p.get("part") or p.get("id") for p in r["play"]][-2:], r.get("speak")), (["apology_cut_off", "purpose"], True))
        self.assertIn(f"「{point}」", r["message"])
        # (5) 最終目的のご承認：ご説明を聞き終えるまでは断られたとしない・この電話でお断りなら、今までどおり目的が果たせない
        b = business(heard, final_goal=True, declines=("いいえ",))
        f = b.flow(play_recordings=True)
        self.assertIsNone(f._goals_lost())
        f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
        r = f.apply("report_party", {"party": "person"})
        r if r.get("result") == "opening" else f.on_first_words_end()
        grounded(f, explain, GROUNDED)
        f.apply("replay_opening", {"part": "own", "answer": explain})
        f.on_callee(); f.on_heard("そうなんですね。")
        f.apply("replay_opening", {"part": "resume"})
        r = say(f, "でもやっぱり、今の業者で十分なので。", "record_answer", question_id=n2, condition_id="断ろうとしている")
        self.assertEqual((f.end_reason, f.facts["goal_refused"][0]["goals"]), ("goal_refused", ["Q1"]), r)
        # 手順を終えていた（ご納得いただけなかった＝declined）なら、続きの電話の始めには伺わず、今までどおり断られた答え
        b = business({"Q1": {"state": "accepted", "condition": "いいえ", "point_fact": {"question": "Q1", "point": None, "outcome": "declined"}}}, final_goal=True, declines=("いいえ",))
        self.assertEqual((b.first_ask()[0], b.flow(play_recordings=True)._goals_lost()), ("Q2", ["Q1"]))
        # 点まで伺えたが、点の言葉（"point_said"）が渡っていない（CL-2 がまだ渡さない間も）：ご説明できる点が無いので、ご説明から始めずに点を伺い直す
        # （前回お伺いした件でご納得いただけなかった点は…＝点を伺う前に切れたときと同じ1か所）
        b = business({"Q1": {"state": "accepted", "condition": "いいえ", "point_fact": {"question": "Q1", "point": None, "said": "", "outcome": None}}})
        self.assertEqual((resumed_step(b.questions, b.earlier)[0], b.first_ask()[0], b.flow(play_recordings=True).current),
                         ("not_agreed", CALLBACK_IDS["not_agreed"], CALLBACK_IDS["not_agreed"]))

    def test_resumed_explanation_starts_with_the_lead_and_keeps_the_point(self):
        # 続きの電話の始めのご説明（前の電話で点まで伺えた＝19時26分の (A)）：(1) AIのご説明は「前回お伺いした（その点）の件ですが、」から（✅ 19時26分 ユーザー
        # 「AIが「前回お伺いした（その点）の件ですが、」から自分の言葉でご説明する」）＝流れの制御が受け取る所で見る（⛔ 21時台の見直しで見つけた：会話AIへの
        # 頼みだけで、想定問答の録音や話し始めの言葉の無い文も、そのまま流れた） (2) 依頼者へ返す記録（not_agreed）に、どの点か・ご説明できたかを残す
        # （「そのあとはこの電話の手順と同じ」。⛔ 点 None・explained 無しで返していた）
        from flowctl import CALLBACK_IDS, Question, RESUMED_LEAD
        from grounding import GROUNDED
        from instruction import Business
        n2 = CALLBACK_IDS["other_point"]
        point = "料金のところがよく分からなかったんです。"
        explain = "前回お伺いした料金の件ですが、料金は月額3,000円で、初月は無料となっております。"
        bare = "料金は月額3,000円で、初月は無料となっております。"

        def flow(**k):
            b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付",
                         questions=[Question("Q1", "ただいまご説明した内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True),
                                    Question("Q2", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",))],
                         purpose_line="資料送付の件でお電話いたしました。", earlier={"Q1": {"state": "accepted", "condition": "いいえ", "point_fact": {"question": "Q1", "point": "料金のところ", "said": point, "outcome": None}}},
                         apology=("cut_off",), info=[bare], **k)
            f = b.flow(play_recordings=True)
            f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
            r = f.apply("report_party", {"party": "person"})
            r if r.get("result") == "opening" else f.on_first_words_end()
            return f
        self.assertTrue(explain.startswith(RESUMED_LEAD))
        f = flow(answers=[("料金", bare)])
        # (1) 話し始めの言葉の無い文・想定問答の録音は受け取らず、話し始めの言葉から言い直していただく（知らせは _point_note の1か所）
        grounded(f, bare, GROUNDED)
        r = f.apply("replay_opening", {"part": "own", "answer": bare})
        self.assertEqual(r["result"], "rejected")
        self.assertIn(RESUMED_LEAD, r["message"])
        r = f.apply("replay_opening", {"part": "料金"})
        self.assertEqual(r["result"], "rejected")
        grounded(f, explain, GROUNDED)
        r = f.apply("replay_opening", {"part": "own", "answer": explain})
        self.assertEqual((r["result"], r["say"]), ("own_answer", explain))
        # (2) 記録：点は前の電話で伺った点・ご説明できた
        e = f.facts["not_agreed"]
        self.assertEqual([(x["point"], x.get("explained")) for x in e], [(point, True)])
        f.on_callee(); f.on_heard("そうなんですね。")
        f.apply("replay_opening", {"part": "resume"})
        f.on_callee(); f.on_heard("だいたい分かりました。")
        f.apply("record_answer", {"question_id": n2, "condition_id": "分かった"})
        self.assertEqual([(x["point"], x.get("explained"), x.get("outcome")) for x in f.facts["not_agreed"]], [(point, True, "agreed")])
        # 一度ご説明したあとは、話し始めの言葉は求めない（2回目からのご説明は、この電話の手順と同じ）
        self.assertNotIn(RESUMED_LEAD, f._point_note() if f.point["stage"] == "explain" else "")
        # ご説明できない（知っていることに無い）ときも、話し始めの言葉から申し伝える・記録はご説明できなかった
        f = flow()
        no = "前回お伺いした料金の件ですが、そちらは担当の者に申し伝えさせていただきますね。"
        grounded(f, no, GROUNDED, part="no_answer")
        r = f.apply("replay_opening", {"part": "no_answer", "answer": no})
        self.assertNotEqual(r["result"], "rejected", r)
        self.assertEqual([(x["point"], x.get("explained")) for x in f.facts["not_agreed"]], [(point, False)])

    def test_a_point_not_said_on_the_continuation_recaps_where_the_call_was_cut(self):
        # ✅ 2026-11-05 日本時間4時16分52秒 ユーザー：「お客様「うーん、何だったか覚えてないですね。」こちら「はい、こちらのプランは月額3,000円で初月は無料と
        # なっております。」こちら「はい、それではご訪問の日時のご希望はございますでしょうか？」という流れは、どちらもひどい違和感がありませんか？たとえは、こちら
        # 「ごもっともです。前回は、『（前回、説明した内容）』。とお話したところでお電話が切れてしまいました。」などと伝える方が自然な流れですよね。お客様に聞かれても
        # いないことを回答したり、全く話題を変えて、それではご訪問の日時のご希望はというふうにつなげるのは、かなりの違和感がありますよ。人ではありえないような対応です。」
        # ⇒ 続きの電話の始めの「前回お伺いした件でご納得いただけなかった点は…」に、点を言っていただけなかった（覚えていない・どちらとも取れない・聞き取れない）とき、
        # 会話AIにご説明させず・手順を黙って終えずに、プログラムが「ごもっともです。」（覚えていない＝わからない）＋「前回は『（ご承認いただく内容の説明の文）』と
        # お話ししたところでお電話が切れてしまいました。」を流し、お客様の返事を「ほかに…」（N2）と同じ3つ（分かった・分からない点がある・断ろうとしている）で読む
        # （振り返りは N2 の質問の言い方の1つ＝伺い方だけが違う）。点を言っていただいたらその点をご説明（1回目）・分かったなら「ありがとうございます。」で次へ・
        # どちらとも取れなければ「はい、」＋「ご説明した内容でご納得いただけましたでしょうか？」。答えたくない・説明の文が無いときは、振り返らずにご納得を伺う
        # （この電話で点を言っていただけなかったときと同じ）。⛔ 0時48分の (ア) の形（会話AIが改めてご説明）・3時49分の形（説明の文が無ければ黙って次の質問へ）を取り下げた
        from flowctl import CALLBACK_IDS, Question
        from grounding import GROUNDED
        from instruction import Business
        from phrases import ACK, CALLBACK_ASK, CLOSING, POINT_ANYTIME, RECORDED, recap_line
        n1, n2, n3 = (CALLBACK_IDS[r] for r in ("not_agreed", "other_point", "agreed_now"))
        explain = "こちらのプランは月額3,000円で初月は無料となっております。"
        recap = "前回は『こちらのプランは月額3,000円で初月は無料となっております』とお話ししたところでお電話が切れてしまいました。"
        self.assertEqual((recap_line(explain), RECORDED["gomottomo"], ACK["gomottomo"]), (recap, "ごもっともです。", "ごもっともです。"))

        def flow(intro=explain, **goal):
            b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付",
                         questions=[Question("Q1", "資料はお手元に届いていますでしょうか？", "yes_no", conditions=("はい", "いいえ")),
                                    Question("Q2", "以上の内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True, intro=intro,
                                             **goal),
                                    Question("Q3", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",))],
                         purpose_line="資料送付の件でお電話いたしました。",
                         earlier={"Q1": {"state": "accepted", "condition": "はい"}, "Q2": {"state": "accepted", "condition": "いいえ"}},
                         apology=("cut_off",), info=["料金は月額3,000円で、初月は無料となっております。"])
            f = b.flow(play_recordings=True)
            f.on_connect(); f.on_callee(); f.on_heard("はい、テスト商事でございます。")
            r = f.apply("report_party", {"party": "person"})
            r if r.get("result") == "opening" else f.on_first_words_end()
            self.assertEqual(f.current, n1)
            return f

        def recapped(said="うーん、何だったか覚えてないですね。", cond="unknown", ack="gomottomo"):
            f = flow()
            r = self._say(f, said, "record_answer", question_id=n1, condition_id=cond)
            # 会話AIにご説明させず（explain_point ではない）、プログラムが振り返りの一言を流す（依頼主の単位の録音 Q2_recap）。ご承認の答えは「いいえ」のまま
            self.assertEqual((r["result"], r["question_id"], r.get("ack"), [(p["id"], p["text"]) for p in r["play"]], f.items["Q2"].condition, n3 in f.order),
                             ("next", n2, ack, [("Q2_recap", recap)], "いいえ", False), said)
            self.assertNotIn("not_agreed", f.facts, said)
            return f
        # (1) 振り返りのあと、はっきり納得：「ありがとうございます。」で次へ（ご承認は「はい」）
        f = recapped()
        r = self._say(f, "ああ、そうでしたね。それなら納得です。", "record_answer", question_id=n2, condition_id="分かった")
        self.assertEqual((f.items["Q2"].condition, r["question_id"], r.get("ack")), ("はい", "Q3", "arigatou"))
        self.assertEqual([(x["point"], x["outcome"]) for x in f.facts["not_agreed"]], [(None, "agreed")])
        # (2) 振り返りで思い出して点を言った：その点をご説明する（1回目＝「ほかにも」ではない）。そのあとは「ほかに…」（言い方の1つ目）
        f = recapped()
        r = self._say(f, "あ、料金のところがよく分からなかったんです。", "record_answer", question_id=n2, condition_id="分からない点がある", value="料金のところ")
        self.assertEqual((r["result"], f.point["stage"], f.point["round"]), ("explain_point", "explain", 1))
        self.assertNotIn("ほかにも", r["message"])
        a = "料金は月額3,000円で、初月は無料となっております。"
        grounded(f, a, GROUNDED)
        f.apply("replay_opening", {"part": "own", "answer": a})
        f.on_callee(); f.on_heard("そうなんですね。")
        r = f.apply("replay_opening", {"part": "resume"})
        self.assertEqual((r["question_id"], [p["text"] for p in r["play"]]), (n2, [CALLBACK_ASK["other_point"]]))
        self.assertEqual([(x["point"], x["round"]) for x in f.facts["not_agreed"]], [("料金のところ", 1)])
        # (3) どちらとも取れない（「そうでしたっけ。」）：納得していないお客様にご納得は伺わない＝点は1回伺ったので手順を終え、「はい、」で次へ（11-02 4時36分の
        # 「1回伺って依頼者へ返す」。✅ 4時48分13秒 ユーザー：「…納得していない状況で→ こちら「はい、ご説明した内容でご納得いただけましたでしょうか？」は
        # 対尾王としてありえないんじゃないですか？」）
        # ✅ 5時20分56秒 ユーザー：「お客様「そうでしたっけ。」と言われて、こちら「はい、続きましてご訪問の日時のご希望はございますでしょうか？」は流れとして
        # おかしくないですか？：「はい、何か思い出されたり、ご不満な点がございましたらいつでもお申し出ください」のような言葉を挟んだ方がいいんじゃないでしょうか？」
        # ＝伺い直さずに、その一言（共通の一言の録音 point_anytime）を挟んでから次へ
        f = recapped()
        r = self._say(f, "そうでしたっけ。", "record_answer", question_id=n2, condition_id="unknown")
        self.assertEqual((r["question_id"], r.get("ack"), n3 in f.order, f.items["Q2"].condition), ("Q3", "hai", False, "いいえ"))
        self.assertEqual((r["play"][0]["id"], r["play"][0]["text"], RECORDED["point_anytime"]), ("point_anytime", POINT_ANYTIME, POINT_ANYTIME))
        # (3b) 振り返りへの「言いたくない」（覚えてはいる）は「承知しました。」＋「ご不満な点が…」（「何か思い出されたり」は合わない＝本書 9-5 の続きの電話の
        #      答えたくない）。⛔ 2026-11-06 日本時間13時台の見直し（ご承認の手順の持ち場の指摘5）で見つけた：「はい、何か思い出されたり…」だった
        f = recapped()
        r = self._say(f, "それは言いたくないです。", "record_answer", question_id=n2, condition_id="refused")
        self.assertEqual((r.get("ack"), r["play"][0]["id"]), ("shouchi", "point_anytime_plain"))
        self.assertEqual(POINT_ANYTIME, "何か思い出されたりご不満な点がございましたらいつでもお申し出ください。")
        self.assertEqual([(x["point"], x["outcome"]) for x in f.facts["not_agreed"]], [(None, "unresolved")])
        # 次の返事では、もう挟まない（1回だけ）
        r = self._say(f, "15日の午後2時でお願いします。", "record_answer", question_id="Q3", condition_id="答えた", value="15日の午後2時")
        self.assertNotIn("point_anytime", [p.get("id") for p in r.get("play", [])])
        # (4) お断り：ご承認は「いいえ」のまま
        f = recapped()
        self._say(f, "やっぱり今回はやめておきます。高いので。", "record_answer", question_id=n2, condition_id="断ろうとしている")
        self.assertEqual((f.items["Q2"].condition, f.point["outcome"]), ("いいえ", "declined"))
        # (4b) 振り返りのあと、分からない点があるとだけ言った（どの点かは言っていない）：プログラムが1回どの点かを伺い（✅ 11-06 日本時間9時05分17秒の一言）、
        # それでも点を言っていただけなければ手順を終える。挟む一言は、前の電話のことを伺う場面なので「何か思い出されたり…」（(3) と同じ＝5時20分56秒の (a)）、
        # 頭は聞き取れた言葉で点を言っていただけなかったときの「承知しました。」
        from flowctl import POINT_UNSAID
        f = recapped()
        r = self._say(f, "うーん、ちょっと分からないところがあって。", "record_answer", question_id=n2, condition_id=POINT_UNSAID)
        # まだ点を1つも伺っていないので「ほかに」は付けない（✅ 2026-11-06 日本時間10時12分44秒 ユーザー：「(イ) 「ほかに」を外して「ご不明な点はどのようなことに
        # なりますでしょうか？」OK」）。⛔ それまでは、この電話の「ほかに…」と同じ「ほかにご不明な点は…」を流していた
        self.assertEqual((r["question_id"], r.get("ack"), [(p["id"], p["text"]) for p in r["play"]]),
                         (n2, "hai", [("callback_other_point_which_recap", "ご不明な点はどのようなことになりますでしょうか？")]))
        r = self._say(f, "いや、いろいろとですね。", "record_answer", question_id=n2, condition_id=POINT_UNSAID)
        self.assertEqual((r["question_id"], r.get("ack"), r["play"][0]["id"], f.items["Q2"].condition), ("Q3", "shouchi", "point_anytime", "いいえ"))
        # (5) 聞き取れない（覚えていないとは言われていない）：振り返るが、頭は「はい、」（「ごもっともです。」は、覚えていない・分からないと言われたときだけ）
        f = flow()
        r = self._say(f, "（雑音）", "report_unclear", question_id=n1)
        self.assertEqual((r["question_id"], r.get("ack"), [p["id"] for p in r["play"]]), (n2, "hai", ["Q2_recap"]))
        # (6) 答えたくない（点を言いたくない＝覚えてはいる）：振り返らず、ご納得も伺わずに「承知しました。」で手順を終える（この電話で点を言っていただけ
        # なかったときと同じ＝test_a_point_not_said_ends_the_step_without_asking_agreement）
        f = flow()
        r = self._say(f, "それはちょっと言いたくないですね。", "record_answer", question_id=n1, condition_id="refused")
        self.assertEqual((r["question_id"], r.get("ack"), r["play"][0]["id"], n3 in f.order, f.items["Q2"].condition),
                         ("Q3", "shouchi", "point_anytime_plain", False, "いいえ"))
        self.assertEqual([(x["point"], x["outcome"]) for x in f.facts["not_agreed"]], [(None, "unresolved")])
        # (7) 説明の文が無い（振り返る中身が無い）：ご納得は伺わず（4時48分13秒）、(3) と同じ一言を挟んで次へ（✅ 5時20分56秒 ユーザー：「(b)…同上」）。
        # 頭は、覚えていないと言われたら「ごもっともです。」（4時16分52秒の振り返りと同じ）・聞き取れないなら「はい、」
        for said, how, ack in (("うーん、何だったか覚えてないですね。", "record_answer", "gomottomo"), ("（雑音）", "report_unclear", "hai")):
            f = flow(intro="")
            r = self._say(f, said, how, question_id=n1, **({"condition_id": "unknown"} if how == "record_answer" else {}))
            self.assertEqual((r["question_id"], r.get("ack"), r["play"][0]["id"], n3 in f.order, f.items["Q2"].condition),
                             ("Q3", ack, "point_anytime", False, "いいえ"), said)
            self.assertEqual([(x["point"], x["outcome"]) for x in f.facts["not_agreed"]], [(None, "unresolved")], said)
        # (8) ご承認が最終目的：一言を挟んでから、お礼を言って締める（もうかけないの印は付けない＝4時36分のご決定）
        f = flow(final_goal=True, declines=("いいえ",))
        self._say(f, "うーん、何だったか覚えてないですね。", "record_answer", question_id=n1, condition_id="unknown")
        r = self._say(f, "そうでしたっけ。", "record_answer", question_id=n2, condition_id="unknown")
        self.assertEqual((r["result"], r.get("ack"), [p["text"] for p in r["play"]], "goal_refused" in f.facts),
                         ("end", "hai", [POINT_ANYTIME, CLOSING], False))
        # 振り返りの一言は、説明の文のあるご承認の質問だけ、依頼主の単位で録音する（作る表 make_ack_clips.script_table・流す question_play が同じ名前）
        import dataclasses
        from g22_opening import BUSINESS
        from make_ack_clips import script_table
        q = Question("Q9", "以上の内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True, intro=explain)
        self.assertEqual(script_table(dataclasses.replace(BUSINESS, questions=[*BUSINESS.questions, q]))[0]["Q9_recap"],
                         (recap_line(explain), "recap"))
        self.assertNotIn("Q9_recap", script_table(dataclasses.replace(BUSINESS, questions=[*BUSINESS.questions, dataclasses.replace(q, intro="")]))[0])
        # 質問に入る一言（intro）のある質問の録音の名前は番号だけ（作る表と流す道具が同じ1か所＝phrases.question_clip）。⛔ この試験を書いて見つけた：2か所が
        # 別々に「番号＋つなぎの言葉の名前」と組み、入る一言をつなぎの言葉の表で引いて止まった
        from flowctl import question_play
        from stitch_gap import played_wav
        t = script_table(dataclasses.replace(BUSINESS, questions=[*BUSINESS.questions, q]))[0]
        # 53字の文は質問の上限（6秒）に収まらないので、同じ読み方で上限の大きい question_long（make_ack_clips.question_how の1か所。⛔ 2026-11-06 日本時間
        # 15時台に見つけた：それまで文の長さにかかわらず question で、作っても長さで落ちる文だった）
        self.assertEqual(t["Q9"], (explain + q.text, "question_long"))
        self.assertEqual(played_wav("S2", question_play([*BUSINESS.questions, q], "Q9")).name, "S2_Q9.wav")

    def test_a_point_not_said_ends_the_step_without_asking_agreement(self):
        # ✅ 2026-11-05 日本時間4時48分13秒 ユーザー：「点を言いたくないやどちらとも取れない：お客様「そうでしたっけ。」といったような、納得していない状況で→
        # こちら「はい、ご説明した内容でご納得いただけましたでしょうか？」は対尾王としてありえないんじゃないですか？」⇒ ご承認をいただけず、ご納得いただけなかった
        # 点も言っていただけない（言いたくない・どの部分か分からない・聞き取れない）お客様に、ご納得を伺わない。11-02 日本時間4時36分のご決定（「ご納得いただけ
        # なかった点を1回伺って依頼者へ返す・ご承認が最終目的なら伺ってから締める」）のとおり、点を1回伺ったら、押さずに手順を終える（ご承認は「いいえ」のまま・
        # 依頼者へは点を伺えなかったと返す。もうかけないの印は付けない）。⛔ 点を言っていただけないときにご納得を伺う形は、ご決定に無く、CL-1 が足していた。
        # 点を伺ってご説明したあとの「なるほど」（11-02 5時56分）は今までどおりご納得を伺う。
        # ✅ 5時20分56秒の (a)(b) と同じ理由で、次へ進む前に一言を挟む（✅ 2026-11-05 日本時間5時4x分 ユーザー：「（「承知しました。ご不満な点がございましたら
        # いつでもお申し出ください。続きまして…」のような形）その形でOK、進めてください」）。「思い出されたり」は、前の電話のことを伺う続きの電話（言いたくない以外）だけ
        from flowctl import CALLBACK_IDS, Flow, Question
        from phrases import CLOSING, POINT_ANYTIME_PLAIN, RECORDED
        n1, n3 = CALLBACK_IDS["not_agreed"], CALLBACK_IDS["agreed_now"]
        self.assertEqual((POINT_ANYTIME_PLAIN, RECORDED["point_anytime_plain"]), ("ご不満な点がございましたらいつでもお申し出ください。",) * 2)
        explain = "こちらのプランは月額3,000円で初月は無料となっております。"

        def flow(goal=False):
            f = Flow([Question("Q1", "資料はお手元に届いていますでしょうか？", "yes_no", conditions=("はい", "いいえ")),
                      Question("Q2", "以上の内容でご承認いただけますでしょうか？", "yes_no", conditions=("はい", "いいえ"), approval=True, intro=explain,
                               final_goal=goal, declines=("いいえ",) if goal else ()),
                      Question("Q3", "ご訪問の日時のご希望はございますでしょうか？", "datetime", conditions=("答えた",))], play_recordings=True)
            self._say(f, "はい、届いています。", "record_answer", question_id="Q1", condition_id="はい")
            r = self._say(f, "いいえ、ちょっと考えさせてください。", "record_answer", question_id="Q2", condition_id="いいえ")
            self.assertEqual(r["question_id"], n1)
            return f
        for heard, op, args, ack in (("それはちょっと言いたくないですね。", "record_answer", {"condition_id": "refused"}, "shouchi"),
                                     ("うーん、なんとなくですかね。", "record_answer", {"condition_id": "unknown"}, "shouchi"),
                                     ("（雑音）", "report_unclear", {}, "hai")):
            f = flow()
            r = self._say(f, heard, op, question_id=n1, **args)
            self.assertEqual((r["question_id"], r.get("ack"), r["play"][0]["id"], n3 in f.order, f.items["Q2"].condition),
                             ("Q3", ack, "point_anytime_plain", False, "いいえ"), heard)
            self.assertEqual([(x["point"], x["outcome"]) for x in f.facts["not_agreed"]], [(None, "unresolved")], heard)
            # 最終目的のご承認：一言を挟んでから、お礼を言って締める（目的が果たせなくなったとはしない＝その業務をかけない印は付けない）
            f = flow(goal=True)
            r = self._say(f, heard, op, question_id=n1, **args)
            self.assertEqual((r["result"], r.get("ack"), [p["text"] for p in r["play"]], n3 in f.order, "goal_refused" in f.facts),
                             ("end", ack, [POINT_ANYTIME_PLAIN, CLOSING], False, False), heard)

    def test_the_opening_and_the_flow_start_with_the_same_question(self):
        # 名乗りのあとに最初に伺う質問（名乗りの録音の最後・AIへの指示文＝instruction.Business.first_ask）と、流れの制御の始めは、同じ1か所
        # （flowctl.opening_question）：名前の読みの確かめが先、続きの電話のほかのご希望はそのあと。⛔ 名乗りの組み立てだけ、読みの確かめを見ずに
        # ほかのご希望から始めていた（名乗りの録音の最後に W1 を流し、流れの制御は R1 の答えを待つ）
        from flowctl import reading_question, Question
        from instruction import Business
        qs = [reading_question("R1", "中島", "なかじま", ["なかじま", "なかしま"]),
              Question("Q1", "パンフレットとカタログのどちらをお送りしましょうか？", "choice", conditions=("パンフレット", "カタログ"))]
        b = Business(company="株式会社テスト", caller="山田", caller_reading="やまだ", purpose="資料送付", questions=qs,
                     earlier={"Q1": {"state": "accepted", "condition": "どれも要らない"}})
        f = b.flow(play_recordings=True)
        self.assertEqual((b.first_ask()[0], f.current), ("R1", "R1"))

    def test_hurry_during_callback_questions_closes(self):
        # かけ直しの質問の途中（不在で戻る時刻を伺っている）に急いでいると言われたら、伺わずに締める（かけ直しの記録はもうある＝同じ申し出は1通話1回）
        from flowctl import Flow, Question
        f = Flow([Question("Q1", "ご予約はされていますでしょうか？", "yes_no", conditions=("はい", "いいえ"))], play_recordings=True)
        f.on_callee(); f.on_heard("あいにく本日は外出しております。")
        f._callback("absent", {"ai"})
        f.on_callee(); f.on_heard("すみません、急いでいるので。")
        r = f.apply("request_end", {"reason": "callee_hurry"})
        self.assertEqual((r["result"], f.end_reason, len(f.facts["callback"])), ("end", "callee_hurry", 1))

    def test_end_item_reads_only_the_current_words(self):
        # ⛔ 同じ見直し：お呼びする段の「電話を終える言葉か」に「いまの言葉だけで選ぶ」を書いていなかった（前の言葉の断りを、いまの言葉の答えにしうる）。
        #    答えの段の「言っていない」の説明に、試しと同じ言葉（「結構です」）を例として書いていた ⇒ 意味の言葉に
        from flowctl import END, END_NONE, end_choices
        from meaning_judge import NOW_ONLY, NOW_ONLY_FACETS, RULES
        self.assertIn(END, NOW_ONLY_FACETS)
        self.assertIn(NOW_ONLY, RULES.split("電話を終える言葉か（end）", 1)[1].split("\n", 1)[0])
        self.assertNotIn("結構です", end_choices(False)[END_NONE])

    def test_end_choices_say_offer_declines_and_matter_urgency_by_meaning(self):
        # ✅ 2026-11-01 日本時間20時11分の 2.（お電話の申し出への「かけてこないでください」は、最終目的で決まる＝判定は答えと読む）・20時30分
        #    （用件の急ぎは、ご自分の時間の話ではない）。⛔ 11-02 まで「短い言葉で断った」と形で書き、G-53end で両方を読み違えた。
        from flowctl import END_HURRY, END_NONE, end_choices
        ans, call = end_choices(False), end_choices(True)
        self.assertNotIn("短い言葉", ans[END_NONE])
        self.assertIn("申し出がお電話なら", ans[END_NONE])
        self.assertIn("用件のほうを急いでほしい", ans[END_HURRY])
        self.assertNotIn("用件のほうを急いでほしい", call[END_HURRY])      # お呼びする段の文は変えていない（用件の急ぎを伺う質問は答えの段だけ）
        for d in (*ans.values(), *call.values()):                           # 試しの言葉と同じ言い方を例にしない
            for w in ("かけてこない", "急ぎの案件", "急いでます"):
                self.assertNotIn(w, d)

    def test_calling_stage_reads_refusal_and_unclear_transfer_by_the_judge(self):
        from flowctl import END_REFUSED, END_UNCLEAR, Flow, TARGET_IS_AWAY, UNDECIDED, WHO_RECEPTION
        tt = TargetTest()
        b = tt.business()
        parts = b.replay_parts()
        # 判定が「理由を言わずに取り次げない」と読めば、会話AIが受付の方と報告しても、その場で1回だけご事情かを伺う
        f = Flow(b.questions, play_recordings=True, opening=parts, target=parts)
        f.use_checks("judge")
        f.on_callee(); f.on_heard("取り次ぐことはできません。"); f.on_check("judge", self.R(UNDECIDED, END_UNCLEAR))
        r = f.apply("report_party", {"party": "reception"})
        self.assertEqual((r["result"], r["play"][0]["part"]), ("confirm_unavailable", "unavailable_confirm"))
        # 判定が「営業のお断り」と読めば、会話AIの理由に関係なく、もうかけない
        g = Flow(b.questions, play_recordings=True, opening=parts, target=parts)
        g.use_checks("judge")
        g.on_callee(); g.on_heard("営業のお電話はお繋ぎできない決まりです。"); g.on_check("judge", self.R(UNDECIDED, END_REFUSED))
        r = g.apply("request_end", {"reason": "not_transferred"})
        self.assertEqual((r["result"], g.end_reason, bool(g.facts.get("do_not_call"))), ("end", "callee_refused_call", True))
        # 決まらず、どこにも寄らない（会話AIの報告だけがきっかけ）：受付の方には、ご事情かを伺う一言
        h = Flow(b.questions, play_recordings=True, opening=parts, target=parts)
        h.use_checks("judge")
        h.on_callee(); h.on_heard("それはちょっと。"); h.on_check("judge", self.R(UNDECIDED, UNDECIDED))
        self.assertEqual(h.apply("request_end", {"reason": "callee_refused_call"})["result"], "confirm_unavailable")


class EndWordsTest(unittest.TestCase):
    """電話を終える言葉の試しの正解の表（end_words）の行ごとに、正解の読みを当てたときにお客様に聞こえる言葉と結果（表でお見せするもの）を確かめる。
    ✅ 2026-11-01 のご判断（6時05分・20時11分・20時56分・22時31分・23時04分・23時59分）。表を直したら、ここも直す（食い違えば落ちる）。"""

    H1 = "はい、それではまた改めてお掛けしてもよろしいでしょうか？"
    # 次の項目の質問の頭は「続きまして」（✅ 2026-11-06 日本時間12時54分30秒 ユーザー：「次の項目の質問に入る前は、すべて「続きまして」でいいんじゃないですか。」）
    NEXT = "承知しました。続きましてご不明な点はございますでしょうか？"
    REFUSED = "承知しました。お忙しいところ申し訳ございませんでした。それでは失礼いたします。"
    R1 = "失礼いたしました。今後このようなお電話はご遠慮したほうがよろしいでしょうか？"

    def test_answer_rows(self):
        from end_words import ANSWER, QUIET, answer_flow
        want = [
            (self.H1, "続ける"), (self.NEXT, "続ける"),
            ("はい、承知いたしました。お忙しいところお時間をいただきましてありがとうございました。それでは失礼いたします。", "締め（goal_refused）・この業務はかけない"),
            (self.NEXT, "続ける"), (self.REFUSED, "締め（callee_refused_call）・もうかけない"), (self.NEXT, "続ける"), (self.H1, "続ける"),
            (self.NEXT, "続ける"), (self.REFUSED, "締め（callee_refused_call）・もうかけない"), (self.REFUSED, "締め（callee_refused_call）・もうかけない"),
            (self.H1, "続ける"), (self.H1, "続ける"), ("", "続ける"),
            # 答えの段のかけ直しの一言（✅ 2026-11-06 日本時間0時44分31秒「(イ) 答えの段のかけ直しすべてで大丈夫」）
            ("承知しました。いつ頃おかけ直しさせていただきましょうか？", "続ける"),
            # 急いでいる理由と一緒にかけ直しを頼まれた：頼まれたことを「また改めてお掛けしても…」と重ねて伺わない（本書 9-3）
            ("承知しました。いつ頃おかけ直しさせていただきましょうか？", "続ける"),
            ("お忙しいところ申し訳ございませんでした。それでは失礼いたします。", "締め（callee_complaint）・人に引き継ぐ"),
            ("はい、パンフレットはお送りしない方がいいということでしょうか？", "続ける"), (self.NEXT, "続ける"), ("", "続ける"),
            ("はい、それではパンフレットをお送りさせていただきますね？", "続ける"),
            # 目的から遠ざかる向きの言い切っていない答えで、業務設定の追って伺う質問が無い：その向きの言葉で言い直さずに「承知しました。」で次へ（✅ 2026-11-03
            # ユーザー：「提案の「承知しました」で次に進むでもOK」・「最終目的に繋がるクロージングはマイナスの言葉で締めない」）
            (self.NEXT, "続ける"),
            ("はい、それではお支払いはカードとさせていただきますね？", "続ける"),
            ("はい、それではご予約はされているということで承っておいて大丈夫でしょうか？", "続ける"),
            (self.R1, "続ける"), (self.R1, "続ける")]
        self.assertEqual(len(want), len(ANSWER))
        for row, w in zip(ANSWER, want):
            _, heard, marks = answer_flow(row)
            self.assertEqual((heard, marks), w, row[1])

    def test_calling_rows(self):
        from end_words import CALLING, calling_flow
        unavailable = "はい、「おかだ」様は今お電話に出られないご状況ということでしょうか？"
        want = [(self.REFUSED, "締め（callee_refused_call）・もうかけない"), (self.REFUSED, "締め（callee_refused_call）・もうかけない"),
                ("失礼いたしました。営業部部長の「おかだたろう」様はいらっしゃいますでしょうか？", "続ける"),
                ("はい、お忙しいところお時間をいただきましてありがとうございました。それでは失礼いたします。", "締め（not_transferred）"),
                (unavailable, "続ける"), None, (unavailable, "続ける"), (self.H1, "続ける"), (self.H1, "続ける"),
                ("お忙しいところ申し訳ございませんでした。それでは失礼いたします。", "締め（callee_complaint）・人に引き継ぐ")]
        self.assertEqual(len(want), len(CALLING))
        for row, w in zip(CALLING, want):
            got = calling_flow(row)
            self.assertEqual(None if got is None else got[1:], w, row[1])

    def test_questions_come_from_the_import(self):
        # ⛔ 2026-11-02 まで、表が意味の言葉・事実を伺う質問か・こちらがすることの言葉を手で書いていた（「大丈夫だということ」「ご予約はお済み」
        #    「お振込み」＝取込の言葉と違う言葉で表を作っていた）⇒ 質問はどれも、答えの段の測りの質問の表（取込で作った言葉つき）から取る
        from end_words import CHOICES, DOCS, RESERVED, question
        from flowctl import CHOICE_TYPES
        for text, choices in CHOICES.items():
            q = question(text)
            self.assertEqual((q.text, tuple(q.conditions)), (text, choices))
            self.assertEqual(set(q.meanings), set(choices), text)
            self.assertEqual(q.asks_fact, text in (RESERVED, DOCS), text)
            if q.type in CHOICE_TYPES and not q.asks_fact:   # 選択肢の質問で事実を伺う質問でないもの：選択肢ごとに、向きを伺う言葉・こちらがすること
                # こちらがすることの言葉が無いのは、CL-1 が誤りとした言葉（G-72 の BAD）を外した選択肢だけ（✅ 11-03 8時10分の (6)(7) ほか）
                from g72_choice_words import BAD
                self.assertEqual(set(q.doubt_words), set(choices), text)
                self.assertLessEqual(set(q.do_words), set(choices), text)
                for ch in set(choices) - set(q.do_words):
                    self.assertTrue(any(k == "do" and t == text and c == ch for k, t, c, _ in BAD), (text, ch))
            else:
                self.assertEqual((q.doubt_words, q.do_words), ({}, {}), text)

    def test_every_choice_has_meaning_words(self):
        # 測りの質問の表の選択肢の質問は、どれも選択肢ごとの意味の言葉を持つ（取込の言葉が抜けると、判定に選択肢の名前だけが見え、言い直しもできない）。
        # ⛔ 2026-11-03：文を直した G7 の意味の言葉が、1回おきの流しで結果から消えていた（g53_meaning.renamed の前）
        from flowctl import CHOICE_TYPES
        from g53_meaning import question_map, renamed
        for q in question_map().values():
            if q.type in CHOICE_TYPES:
                self.assertEqual(set(q.meanings), set(q.conditions), (q.id, q.text))
        self.assertEqual(renamed(), [("担当者からまたお電話を差し上げてもよろしいでしょうか？", ("はい", "いいえ"))])

    def test_answer_truths_are_one_per_words(self):
        # 同じ質問・同じ言葉の行（業務の最終目的かだけが違う）は、正解も同じ（答えの段の測り G-53 の組 F は1つにまとめて判定する）
        from end_words import ANSWER, answer_truths
        got = answer_truths()
        self.assertEqual(len(got), len({(r[0], r[1]) for r in ANSWER}))
        self.assertEqual(got[(ANSWER[0][0], ANSWER[0][1])]["accept"], ["いいえ", "決められない", "unknown"])

    def test_ack_follows_the_decided_reason(self):
        # ⛔ 2026-11-01 夜（表を作りから出して見つけた穴）：締めの相づちを会話AIの理由で選んでいた＝判定が「怒っている」と決めても、
        #    会話AIの報告が「取り次いでいただけなかった」なら「はい、」を流していた（怒っている方には相づちを流さない決まり）
        from end_words import CALLING, calling_flow
        f, heard, _ = calling_flow(CALLING[-1])
        self.assertEqual((f.end_reason, f.log[-1]["reply"]["ack"]), ("callee_complaint", None))


class WhoUnclearTest(unittest.TestCase):
    """受付の方に、お名前だけではどの方か分からないので取り次げないと言われたら、締めずに部署・役職とフルネームで1回だけお呼びし直す（Flow._who_unclear）。
    ✅ 2026-11-01 日本時間23時59分 ユーザー：「名前以外に部署やフルネームを伝えて、取り次いでもらう努力をするべきじゃないでしょうか。そうしないと、
    もう一度かけ直しても断られるだけですよ。」"""

    WORDS = "お名前だけではどの者か分かりかねますので、お繋ぎできかねます。"

    def flow(self, successor=False, **kw):
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        from instruction import Target
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長", **kw))
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), successor=successor)
        f.use_checks("judge")
        return f

    @staticmethod
    def told(f, words):
        from end_words import _reading
        from flowctl import END_WHO, UNDECIDED
        f.on_callee(); f.on_heard(words); f.on_check("judge", _reading(UNDECIDED, END_WHO))
        return f.apply("request_end", {"reason": "not_transferred"})

    def test_calls_again_once_with_the_full_name(self):
        f = self.flow(full_name="岡田太郎", full_reading="おかだたろう")
        r = self.told(f, self.WORDS)
        self.assertEqual((r["result"], r["ack"], [p["text"] for p in r["play"]], f.end_reason),
                         ("call_target", "shitsurei", ["営業部部長の「おかだたろう」様はいらっしゃいますでしょうか？"], None))
        # それでも分からないと言われたら、お礼の締め（取り次いでいただけなかった）。通話の事実にお呼びし直したことを残す
        self.told(f, "申し訳ございません、それでも分かりかねます。")
        self.assertEqual((f.end_reason, f.facts["who_unclear"][0]["recalled"]), ("not_transferred", True))

    def test_department_alone_is_enough(self):
        # ✅ 2026-11-02 日本時間1時22分 ユーザー：(a)「フルネームか部署かどちらかが分かれば、言い直す。」（名前のみの指定の行で、データに部署がある）
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        from instruction import Target
        b = dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", department="営業部"))
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts())
        f.use_checks("judge")
        r = self.told(f, self.WORDS)
        self.assertEqual([p["text"] for p in r["play"]], ["営業部の「おかだ」様はいらっしゃいますでしょうか？"])
        # 部署がもう呼ぶ一言の役職に入っていれば、増えない
        self.assertEqual(Target(name="岡田", reading="おかだ", role="営業部部長", department="営業部").full_call(), "")

    def test_nothing_more_to_tell_closes(self):
        # フルネームも部署も無い（お名字と同じ）＝お伝えすることが増えない：お呼びし直さずにお礼の締め。繋がらなかった理由は「お名前だけではどの方か
        # 分からなかった」＝かけ直さずに依頼者へ返す（✅ 11-02 1時22分 (a)「どちらもなければ、(イ)」）
        from instruction import Target
        self.assertEqual(Target(name="岡田太郎", reading="おかだたろう", full_name="岡田太郎", full_reading="おかだたろう").full_call(), "")
        f = self.flow()
        self.told(f, self.WORDS)
        self.assertEqual((f.end_reason, f.facts["who_unclear"][0]["recalled"], f.not_reached), ("not_transferred", False, "who_unclear"))

    def test_which_one_is_answered_in_full(self):
        # ✅ 2026-11-02 日本時間1時22分 ユーザー：(b)「OK」＝「どちらの岡田でしょうか？」にも、部署・フルネームの入った呼ぶ一言で答える（1通話1回）
        from flowctl import ASKS_YES
        f = self.flow(full_name="岡田太郎", full_reading="おかだたろう")
        f.on_callee(); f.on_heard("どちらの岡田でしょうか？"); f.on_check("asks", ASKS_YES)
        r = f.apply("replay_opening", {"part": "target"})
        self.assertEqual((r["result"], r["ack"], [p["text"] for p in r["play"]]),
                         ("call_target", "hai", ["営業部部長の「おかだたろう」様はいらっしゃいますでしょうか？"]))
        # それでもお名前だけでは分からないと言われたら、お伝えすることはもう無い＝お礼の締め（繋がらなかった理由は、お名前だけではどの方か分からなかった）
        self.told(f, self.WORDS)
        self.assertEqual((f.end_reason, f.facts["who_unclear"][0]["recalled"], f.not_reached), ("not_transferred", True, "who_unclear"))

    def test_successor_call_says_the_predecessor_in_full(self):
        # 後任の方をお呼びする電話：「（前任の方の部署・役職とフルネーム）様の後任のご担当者様は…」（前任の方をフルネームでお呼びしない）
        f = self.flow(successor=True, full_name="岡田太郎", full_reading="おかだたろう")
        r = self.told(f, self.WORDS)
        self.assertEqual([p["text"] for p in r["play"]], ["営業部部長の「おかだたろう」様の後任のご担当者様はいらっしゃいますでしょうか？"])


class TargetTest(unittest.TestCase):
    """目的の人に繋がってから必須の質問を始める（DESIGN.md 4-3。✅ 2026-10-13 ユーザー：「決裁権者と話したいのに、関係ない人と話しても意味が
    ない」）。名乗りの終わりは目的の人を呼ぶ一言。繋がったら、その方にまだ届いていない名乗り・用件を流してから最初の質問。"""

    def business(self, **kw):
        import dataclasses
        from g22_opening import BUSINESS
        from instruction import Target
        return dataclasses.replace(BUSINESS, target=Target(name="岡田", reading="おかだ", role="営業部部長", **kw))

    def flow(self, play=True, recorded=True):
        from flowctl import Flow
        b = self.business()
        return Flow(b.questions, play_recordings=play, opening=b.replay_parts() if recorded else None, target=b.replay_parts()), b

    @staticmethod
    def say(f, heard, op, **args):
        f.on_callee(); f.on_heard(heard)
        return f.apply(op, args)

    def test_opening_ends_with_the_call_and_no_question_until_connected(self):
        f, b = self.flow()
        self.assertEqual(b.opening_parts()[-1], "営業部部長の「おかだ」様はいらっしゃいますでしょうか？")
        self.assertEqual((f.phase, f.current), ("calling", None))
        r = self.say(f, "はい、予約しています。", "record_answer", question_id="Q1", condition_id="はい", value="予約しています")
        self.assertEqual(r["result"], "rejected")
        self.assertIn("目的の人", r["message"])
        self.assertEqual(self.say(f, "はい。", "request_end", reason="done")["result"], "rejected")  # まだ終えられない（質問を始めていない）

    def test_next_call_asks_for_the_successor(self):
        # ✅ 2026-10-24 ユーザー「5つOK」（CL-2 の 4-140：予約証の successor）：前の電話でお呼びした方が在籍していないと言われた会社への次の電話は、
        # 「（前任の方のお名前）様の後任のご担当者様」をお呼びする。確かめる一言は、通話の中で後任の方へ切り替えたときと同じ録音
        import dataclasses
        from flowctl import Flow
        from phrases import SUCCESSOR
        b = self.business(successor=True)
        self.assertEqual(b.opening_parts()[-1], "営業部部長の「おかだ」様の後任のご担当者様はいらっしゃいますでしょうか？")
        self.assertIn("お呼びする方：営業部部長の（お名前）様の後任のご担当者様", b.knowledge())
        # 録音の組は業務×声で1つ（承認したあとは部分を足せない）＝どの電話にも同じ部分（CL-2 の 4-152）：ふつうの呼ぶ一言と後任の方の呼ぶ一言は
        # 別の名前・約束の電話の一言も初めから入れる
        parts = b.replay_parts()
        self.assertEqual(parts, dataclasses.replace(self.business(), promised=True).replay_parts())
        self.assertEqual((parts["target"], parts["target_successor"]), ("営業部部長の「おかだ」様はいらっしゃいますでしょうか？",
                                                                     "営業部部長の「おかだ」様の後任のご担当者様はいらっしゃいますでしょうか？"))
        self.assertIn("promise_again", parts)
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), successor=True)
        self.assertEqual((f.successor, f.system_parts.get("target_confirm"), "target" in f.system_parts), (True, "successor_confirm", False))
        self.assertEqual(f._part_play("target"), {"kind": "opening", "part": "target_successor", "text": parts["target_successor"]})
        self.assertEqual(f._part_play("target_confirm")["text"], SUCCESSOR["target_confirm"])
        g = Flow(b.questions, target=b.replay_parts(), successor=True)    # 名乗りの録音が無い通話（AIが話す形）でも作れる（⛔ 2026-10-24 の見直し：止まっていた）
        self.assertEqual(g.target["target"], parts["target_successor"])
        f2 = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts())      # ふつうの電話は今までどおり
        self.assertEqual(f2._part_play("target"), {"kind": "opening", "part": "target", "text": parts["target"]})
        self.say(f, "はい、後任の山田ですが。", "report_party", party="target")
        self.assertEqual((f.phase, f.facts["connect"][-1]["who"]), ("asking", "successor"))

    def test_transfer_refused_without_reason_is_asked_once(self):
        # ✅ 2026-11-01 ユーザー：受付の方に理由なく「取り次ぐことはできません」とだけ言われたら、その場で「○○様は、今はお電話に出ることができない
        #    といったご事情ということでよろしいでしょうか？」で確かめる（読点は外す＝10-15）。はい・ご事情＝かけ直しの申し出＋お取り次ぎいただける日時
        #    （「恐れ入りますがいつごろでしたらお取り次ぎいただけそうでしょうか？」）・営業はお断り＝もうかけない・戻る時刻＝かけ直し・ほかは返事による
        import dataclasses
        from flowctl import AWAY_WHYS, CALLBACK_PLAN, Flow
        from phrases import CALLBACK_ASK, SUCCESSOR, UNAVAILABLE_CONFIRM
        self.assertNotIn("、", UNAVAILABLE_CONFIRM)
        self.assertEqual(CALLBACK_ASK["transfer_time"], "恐れ入りますがいつごろでしたらお取り次ぎいただけそうでしょうか？")
        self.assertEqual((CALLBACK_PLAN["unavailable"], "unavailable" in AWAY_WHYS), (("transfer_time",), True))
        b = self.business()
        parts = b.replay_parts()
        self.assertEqual(parts["unavailable_confirm"], "「おかだ」様は今お電話に出られないご状況ということでしょうか？")  # 呼び方は確かめる一言と同じ
        self.assertEqual(self.business(successor=True).replay_parts()["unavailable_confirm"], parts["unavailable_confirm"])  # 録音の組は業務×声で1つ
        # はい・ご事情：かけ直しの申し出で、お取り次ぎいただける日時を伺う
        f = Flow(b.questions, play_recordings=True, opening=parts, target=parts)
        r = self.say(f, "申し訳ございません、取り次ぐことはできません。", "request_end", reason="transfer_unclear")
        self.assertEqual((r["result"], r["play"]), ("confirm_unavailable", [{"kind": "opening", "part": "unavailable_confirm", "text": parts["unavailable_confirm"]}]))
        self.assertEqual(f.phase, "calling")
        again = self.say(f, "取り次ぐことはできません。", "request_end", reason="transfer_unclear")   # 伺うのは1回だけ
        self.assertEqual(again["result"], "rejected")
        r = self.say(f, "はい、そうです。会議が続いておりまして。", "request_callback", why="unavailable")
        self.assertIn(CALLBACK_ASK["transfer_time"], r.get("say") or "".join(x["text"] for x in r.get("play", [])))
        # 伺う前の「今はお電話に出られないご事情」は差し戻す（伺ったあとの返事だけ）
        g = Flow(b.questions, play_recordings=True, opening=parts, target=parts)
        self.assertEqual(self.say(g, "会議中です。", "request_callback", why="unavailable")["result"], "rejected")
        # 営業はお断り：もうかけない
        h = Flow(b.questions, play_recordings=True, opening=parts, target=parts)
        self.say(h, "取り次ぐことはできません。", "request_end", reason="transfer_unclear")
        r = self.say(h, "営業のお電話はお断りしております。", "request_end", reason="callee_refused_call")
        self.assertEqual((r["result"], h.end_reason, bool(h.facts.get("do_not_call"))), ("end", "callee_refused_call", True))
        # 後任の方の電話：お名前の代わりに「後任のご担当者様」（共通の一言の録音）
        bs = self.business(successor=True)
        fs = Flow(bs.questions, play_recordings=True, opening=bs.replay_parts(), target=bs.replay_parts(), successor=True)
        r = self.say(fs, "取り次ぐことはできません。", "request_end", reason="transfer_unclear")
        self.assertEqual(r["play"][0]["text"], SUCCESSOR["unavailable_confirm"])
        self.assertEqual(r["play"][0]["kind"], "recorded")
        # 名乗りの録音が無い通話（AIが話す形）でも、言い方は同じ
        k = Flow(b.questions, target=parts)
        self.assertEqual(self.say(k, "取り次ぐことはできません。", "request_end", reason="transfer_unclear")["say"], parts["unavailable_confirm"])

    def test_promised_call_asks_again_before_closing(self):
        # ✅ 2026-10-22 ユーザーの言い方・2026-10-24「5つOK」（CL-2 の 4-135）：約束の電話で、受付の方に事情で取り次げないと言われたら、締めの前に伺い、
        # 答えを通話の事実 not_transferred の again に残す（「OKなら、当日の約束の時刻の幅の中かけ直してもいい」）
        import dataclasses
        from flowctl import CLOSING, Flow
        for said, cond, again in (("はい、お願いします。", "はい", True), ("いえ、今日はちょっと。", "いいえ", False)):
            b = dataclasses.replace(self.business(), promised=True)
            f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), promised=True)
            r = self.say(f, "申し訳ございません、担当が分からないのでお繋ぎできかねます。", "request_end", reason="not_transferred")
            self.assertEqual((r["result"], r["question_id"], r["play"]), ("next", "P1", [
                {"kind": "opening", "part": "promise_again", "text": "「おかだ」様とお電話の約束をしておりましたので後ほど改めてお掛けしてもよろしいでしょうか？"}]))
            r = self.say(f, said, "record_answer", question_id="P1", condition_id=cond)
            self.assertEqual((r["result"], f.end_reason, f.not_reached, f.facts["not_transferred"][-1].get("again")), ("end", "not_transferred", "not_transferred", again))
            self.assertIn(CLOSING, r.get("say") or "".join(x["text"] for x in r.get("play", [])))   # お礼の締め
            self.assertNotIn("P1", f.export())                                                      # 依頼主へ渡す項目には入れない
        # 約束の一言を伺っている間に、受付の方が取り次いだ：代わって出た方にお呼びした方かを確かめてから繋ぐ（⛔ 2026-10-24 の見直し（調べ役）：
        # 代わって出た岡田様に約束の一言を流し、繋がずに終えた）
        from flowctl import HANDOVER, HOLD, TARGET_IS_THERE
        b = dataclasses.replace(self.business(), promised=True)
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), promised=True)
        f.use_checks("judge")
        from flowctl import END_REASONED
        from meaning_judge import Reading
        read = Reading("不在"); read.end = END_REASONED   # 判定が「事情を言って取り次げない」と読む（終わりの理由を決めるのは判定＝11-01 17時04分）
        f.on_callee(); f.on_heard("申し訳ございません、担当が分からないのでお繋ぎできかねます。"); f.on_check("judge", read)
        self.assertEqual(f.apply("request_end", {"reason": "not_transferred"})["question_id"], "P1")
        f.on_callee(); f.on_heard("あ、お約束でしたか。それでしたら少々お待ちください。"); f.on_check("judge", HOLD)
        self.assertEqual(f.apply("record_answer", {"question_id": "P1", "condition_id": "はい"})["result"], "hold")
        f.on_callee(); f.on_heard("お電話代わりました、岡田です。"); f.on_check("judge", HANDOVER)
        self.assertEqual(f.apply("replay_opening", {"part": "handover"})["result"], "confirm_target")
        f.on_callee(); f.on_heard("はい、そうです。"); f.on_check("judge", TARGET_IS_THERE)
        r = f.apply("report_party", {"party": "target"})
        self.assertEqual((r["result"], f.phase, bool(f.facts.get("connect")), f.not_reached), ("next", "asking", True, None))
        # 伺ったのに「はい」と言われなかった（わからない・伺う途中で切れた）：よいと言われていない＝false（⛔ 2026-10-24 の見直し：書いていなかった＝
        # CL-2 は「聞いていない」と読んだ）
        for unknown in (True, False):
            b = dataclasses.replace(self.business(), promised=True)
            f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), promised=True)
            self.say(f, "申し訳ございません、担当が分からないのでお繋ぎできかねます。", "request_end", reason="not_transferred")
            if unknown:
                self.say(f, "ちょっと分かりかねます。", "record_answer", question_id="P1", condition_id="unknown")
            f.on_line_end(ai_speaking=not unknown)
            self.assertIs(f.facts["not_transferred"][-1].get("again"), False, unknown)
        # 約束の電話でなければ、伺わずに締める（今までどおり）
        f, b = self.flow()
        r = self.say(f, "申し訳ございません、担当が分からないのでお繋ぎできかねます。", "request_end", reason="not_transferred")
        self.assertEqual((r["result"], f.end_reason, "again" in f.facts["not_transferred"][-1]), ("end", "not_transferred", False))

    def test_apology_call_plays_the_approved_apology_and_closes(self):
        # ✅ 2026-10-24 ユーザー「OK」（お詫びの文を録音にし、承認のときに聞いていただく）・CL-2 の 4-49・4-58：業務の質問はしない。お呼びした方に
        # 繋がったら（目的のお客様のいない業務は名乗りのあと）、承認したお詫びの録音を流し、お返事を聞いてからお礼の締め。伝えられたかを報告に入れる
        import dataclasses
        from flowctl import CLOSING, Flow
        from g22_opening import BUSINESS
        from instruction import build
        text = "先ほどのお電話で、誤って「無料です」というご案内をしてしまいましたが、正しくは「初回のみ無料」となります。不正確なご案内をしてしまいまして、誠に申し訳ございませんでした。"
        t = dataclasses.replace(self.business(), apology_call=text)
        f = Flow(t.questions, play_recordings=True, opening=t.replay_parts(), target=t.replay_parts(), apology_call=t.apology_call)
        self.assertEqual((t.opening_parts()[-1], t.first_ask(), f.apology_delivered), (t.target.call(), None, False))
        r = self.say(f, "はい、岡田は私ですが。", "report_party", party="target")
        self.assertEqual(r["play"][-1], {"kind": "apology", "text": text})
        self.assertNotIn("purpose", [x.get("part") for x in r["play"]])                      # 用件は流さない
        self.assertFalse(f.apology_delivered)                       # 流すように頼んだだけ（⛔ 前は、この時点で「伝えられた」になった）
        cut = Flow(t.questions, play_recordings=True, opening=t.replay_parts(), target=t.replay_parts(), apology_call=t.apology_call)
        self.say(cut, "はい、岡田は私ですが。", "report_party", party="target")
        cut.on_line_end(ai_speaking=True, callee_speaking=False)    # お詫びの録音の途中で切れた（流し終えた知らせが無い）
        self.assertFalse(cut.apology_delivered)
        f.on_played([x["text"] for x in r["play"]])                 # 電話接続側：最後まで流し終えた
        r = self.say(f, "ああ、わざわざすみません。", "request_end", reason="done")
        self.assertEqual((r["result"], f.end_reason, f.apology_delivered), ("end", "done", True))
        self.assertIn(CLOSING, r.get("say") or "".join(x["text"] for x in r.get("play", [])))
        self.assertIn("お詫びするお電話です。業務の質問はしません。", build(t, "S2", opening_mode="recorded")[1])
        # 目的のお客様のいない業務：名乗りのあとにお詫び。途中で止まったら、お返事のあと一度だけ流し直す
        b = dataclasses.replace(BUSINESS, apology_call=text)
        self.assertEqual(b.opening_parts()[-1], text)
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), apology_call=b.apology_call)
        f.on_opening_cut(b.opening_parts()[:2])
        r = self.say(f, "はい？どちら様？", "request_end", reason="done")
        self.assertEqual((r["result"], r["play"], f.apology_delivered), ("next", [{"kind": "apology", "text": text}], False))
        f.on_played([text])
        r = self.say(f, "そうでしたか、ご丁寧にどうも。", "request_end", reason="done")
        self.assertEqual((r["result"], f.apology_delivered), ("end", True))
        g = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), apology_call=b.apology_call)
        g.on_played(b.opening_parts())                                  # 名乗りもお詫びも最後まで流れた（止めていない）
        self.say(g, "そうでしたか、ご丁寧にどうも。", "request_end", reason="done")
        self.assertTrue(g.apology_delivered)

    def test_apology_call_paths_found_in_the_review(self):
        # ⛔ 2026-10-24 の見直し（調べ役）で見つけた穴：流し直しの条件が広すぎた・代わりの方に繋ぐと締められない・業務の用件が聞こえる・AIが話す形
        import dataclasses
        from flowctl import Flow
        from g22_opening import BUSINESS
        text = "先ほどのお電話で誤ったご案内をしてしまい、誠に申し訳ございませんでした。"
        t = dataclasses.replace(self.business(), apology_call=text)
        # (1) 繋がる前（受付の方とのかけ直しの質問）に終えるときは、お詫びを流さない（受付の方へは流さない）
        f = Flow(t.questions, play_recordings=True, opening=t.replay_parts(), target=t.replay_parts(), apology_call=t.apology_call)
        self.say(f, "あいにく岡田は席を外しております。", "request_callback", why="absent")
        r = self.say(f, "すみません、急いでいるので。", "request_end", reason="callee_hurry")
        self.assertEqual((r["result"], [p.get("kind") for p in r["play"]], f.apology_delivered), ("end", ["closing"], False))
        # (2) お詫びが遮られたあとの断り：お詫びを流し直さず、発信禁止の申告を残して締める
        b = dataclasses.replace(BUSINESS, apology_call=text)
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), apology_call=b.apology_call)
        f.on_opening_cut(b.opening_parts()[:2])
        r = self.say(f, "営業でしょ？もう二度とかけてこないで！", "request_end", reason="callee_refused_call")
        self.assertEqual((r["result"], f.end_reason, bool(f.facts.get("do_not_call"))), ("end", "callee_refused_call", True))
        # (3) 業務の用件は、どの道でも流れない。「ご用件は？」には、お詫びの録音
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), apology_call=b.apology_call)
        f.on_opening_cut(b.opening_parts()[:1])
        self.assertNotIn("purpose", f.opening_unheard)
        r = self.say(f, "え、何の件でしょうか？", "replay_opening", part="purpose")
        self.assertEqual([p.get("kind") for p in r["play"]], ["opening", "apology"])   # まだ届いていない名乗り＋お詫び（業務の用件ではない）
        self.assertNotIn(BUSINESS.purpose_line, "".join(p["text"] for p in r["play"]))
        # (4) 目的のお客様のいない業務で、名乗りをAIが話す形：お詫びを流す所が無いので、作る時点で断る
        with self.assertRaises(ValueError):
            Flow(b.questions, apology_call=b.apology_call)
        # (5) 繋がる前に受付の方から用件を聞かれた：お詫びではなく、用件の一言の録音（✅ 2026-10-24 ユーザー「OK」。同じ日は「先ほど」・あとの日は「先日」）。
        #     お詫びはまだ伝えていない（繋がったら流す）。⛔ 前は流す録音が無く、AIが自分の言葉で答える形だった
        from phrases import APOLOGY_PURPOSE, RECORDED
        for when in ("same_day", "later"):
            t2 = dataclasses.replace(t, apology_when=when)
            f = t2.flow(play_recordings=True)
            r = self.say(f, "どういったご用件でしょうか？", "replay_opening", part="purpose")
            self.assertEqual(r["play"][0], {"kind": "recorded", "id": f"apology_purpose_{when}", "text": APOLOGY_PURPOSE[when]}, when)
            self.assertEqual(r["play"][1:], [f._part_play("target")], when)   # 用件を伝えたら、もう一度だけお呼びする（Intent.md 9-4）
            self.assertNotIn(text, "".join(p["text"] for p in r["play"]), when)  # 受付の方にはお詫びを流さない
            self.assertEqual(RECORDED[f"apology_purpose_{when}"], APOLOGY_PURPOSE[when])
            self.assertEqual((f.apology_asked, f.apology_played, f.phase), (False, False, "calling"), when)
            r = self.say(f, "はい、岡田は私です。", "report_party", party="target")
            self.assertEqual([p["kind"] for p in r["play"]][-1], "apology", when)   # 繋がったら、お詫びの録音

    def test_cut_off_call_continues_from_where_it_stopped(self):
        # CL-2 の 4-77（✅ 2026-10-17 ユーザー：途中で切れた通話は、お詫びとともにすぐかけ直す）：前の通話で取れた答えの質問は、もう伺わずに続きから聞く。
        # 前の通話の答えは、この通話の答えとして渡さない（記録は前の通話のもの）
        import dataclasses
        from flowctl import Flow, spoken_question
        from g22_opening import BUSINESS
        from phrases import APOLOGY_FIRST
        earlier = {"Q1": {"state": "accepted", "value": "予約しています", "condition": "はい"}, "Q2": {"state": "unresolved"}}
        b = dataclasses.replace(BUSINESS, earlier=earlier, apology=("cut_off",))
        # 続きの電話で最初に伺う質問の頭は「確認させていただきたい内容なのですが」（✅ 2026-11-06 日本時間15時20分30秒 ユーザー＝spoken_question の resumed）
        self.assertEqual(b.opening_parts()[-2:], [APOLOGY_FIRST["cut_off"], BUSINESS.purpose_line][-1:] + [spoken_question(b.questions, "Q2", resumed=True)[0]])
        f = Flow(b.questions, earlier=b.earlier)
        self.assertEqual((f.current, f.items["Q1"].state, f.items["Q2"].state), ("Q2", "accepted", "empty"))   # 取れなかった答えは伺い直す
        self.assertNotIn("Q1", f.export())
        # 目的の人のある業務：繋がったら、お詫びのあと続きの質問（つなぎの言葉ごとの録音）
        t = dataclasses.replace(self.business(), earlier=earlier)
        f = Flow(t.questions, play_recordings=True, opening=t.replay_parts(), target=t.replay_parts(), apology=("cut_off",), earlier=t.earlier)
        r = self.say(f, "はい、岡田は私ですが。", "report_party", party="target")
        self.assertEqual([p.get("part") or p.get("id") or p["kind"] for p in r["play"]][:2], ["apology_cut_off", "purpose"])
        self.assertEqual(r["question_id"], "Q2")
        # 全部取れていた：質問を伺わない
        done = {q.id: {"state": "accepted", "value": "x", "condition": "はい"} for q in BUSINESS.questions}
        self.assertIsNone(dataclasses.replace(BUSINESS, earlier=done).first_ask())
        self.assertIsNone(Flow(BUSINESS.questions, earlier=done).current)

    def test_apology_comes_first_when_the_target_answers(self):
        # ✅ 2026-10-24 ユーザー「5つOK」（CL-2 の 4-135：予約証の apology）：前の電話の事情（約束の時間にかけられなかった・途中で切れた）は、目的の方に
        # 繋がったら、まずお詫び（名乗りが要るなら名乗りのあと、用件・質問の前）。⏳ 言い方は案
        import dataclasses
        from types import SimpleNamespace
        from flowctl import Flow
        from g22_opening import BUSINESS
        from phrases import APOLOGY_FIRST
        b = self.business()
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), apology=("cut_off",))
        r = self.say(f, "はい、岡田は私ですが。", "report_party", party="target")
        self.assertEqual([p.get("part") or p.get("id") or p["kind"] for p in r["play"]], ["apology_cut_off", "purpose", "Q1"])
        self.assertEqual((r["play"][0]["text"], f.apology_due), (APOLOGY_FIRST["cut_off"], []))
        # 取り次がれて代わった方がご本人：あいさつ・名乗りのあと、用件の前
        f = Flow(b.questions, play_recordings=True, opening=b.replay_parts(), target=b.replay_parts(), apology=("missed_promise",))
        f.on_callee(); f.on_heard("少々お待ちください。")
        f.handle_call(SimpleNamespace(name="report_party", args={"相手": "受付の方"}))
        r = self.say(f, "お電話代わりました、岡田です。", "report_party", party="target")
        names = [p.get("part") or p.get("id") or p["kind"] for p in r["play"]]
        self.assertEqual(names[names.index("intro") + 1], "apology_missed_promise")
        # 目的の人の無い業務：最初に出た方がお客様＝名乗りのあとにお詫び
        self.assertEqual(dataclasses.replace(BUSINESS, apology=("cut_off",)).opening_parts()[2], APOLOGY_FIRST["cut_off"])

    def test_first_person_is_the_target(self):
        # 最初に出た方が目的の人：まだ届いていない用件と、最初の質問を流す（名乗りはもう届いている）
        f, b = self.flow()
        r = self.say(f, "はい、岡田は私ですが。", "report_party", party="target")
        self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["purpose", "question"])
        self.assertEqual((f.phase, f.current, f.party), ("asking", "Q1", "target"))

    def test_transferred_target_hears_everything(self):
        # 受付の方に取り次いでいただき、代わった方が目的の人：あいさつ・名乗り・用件・最初の質問（呼んだときの名乗りは受付の方にしか届いていない）
        from types import SimpleNamespace
        f, b = self.flow()
        f.on_callee(); f.on_heard("少々お待ちください。")
        reply, silent = f.handle_call(SimpleNamespace(name="report_party", args={"相手": "受付の方"}))
        # お取り次ぎを待つ間は話させない（⛔ G-57：話させる形で返していたので、3本中2本でAIが話した）
        self.assertEqual((f.log[-1]["reply"]["result"], silent), ("noted", True))
        self.assertNotIn("silent", reply)
        r = self.say(f, "お電話代わりました、岡田です。", "report_party", party="target")
        self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["greeting", "intro", "purpose", "question"])

    def test_handover_replay_uses_the_same_target_decision(self):
        # AIが「代わった方」として名乗りの流し直しを頼んだ：目的の人かは、目的の人の報告と同じ1か所で決める（判定が「ご本人」なら繋いで
        # 全部を流す・判定が無ければ目的の人かを確かめる）。⛔ 2026-10-19 G-57：判定が「ご本人」でも、目的の人かを聞き直していた
        # ⛔ 2026-10-21：繋ぐのは「ご本人」の読みが2つ以上そろったときだけ（読み＝AIの「目的の人」の報告・届いた判定の1つずつ）。AIが「代わった方」
        #    と報告していて、届いた判定が1つだけなら、目的の人かを確かめる（G-59：3.5 Flash Lite は、その前の言葉を判定に生かせない。
        #    「お電話代わりました。山本です。」を3回中1回「ご本人」と読んだ）
        from flowctl import HOLD, TARGET_IS_THERE
        for both in (True, False):
            f, b = self.flow()
            f.use_checks("judge", "judge2")
            f.on_callee(); f.on_heard("少々お待ちください。"); f.on_check("judge", HOLD)
            f.on_callee(); f.on_heard("お電話変わりました。岡田です。"); f.on_check("judge", TARGET_IS_THERE)
            if both:
                f.on_check("judge2", TARGET_IS_THERE)
            r = f.apply("replay_opening", {"part": "handover"})
            if both:
                self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["greeting", "intro", "purpose", "question"])
                self.assertEqual(f.phase, "asking")
            else:
                self.assertEqual((r["result"], f.phase), ("confirm_target", "calling"))
        f, b = self.flow()                                           # AIの「目的の人」の報告＋判定1つ＝読みが2つ ⇒ 繋ぐ
        f.use_checks("judge", "judge2")
        f.on_callee(); f.on_heard("岡田は私ですが。"); f.on_check("judge", TARGET_IS_THERE)
        self.assertEqual(f.apply("report_party", {"party": "target"})["result"] != "confirm_target", True)
        self.assertEqual(f.phase, "asking")
        f, b = self.flow()
        f.on_callee(); f.on_heard("お電話変わりました。")
        self.assertEqual(f.apply("replay_opening", {"part": "handover"})["result"], "confirm_target")

    def test_hold_seen_by_the_judge_also_means_a_new_person(self):
        from flowctl import HOLD
        f, b = self.flow()
        f.on_callee(); f.on_heard("少々お待ちください。"); f.on_check("judge", HOLD)
        r = self.say(f, "お電話代わりました、岡田です。", "report_party", party="target")
        self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["greeting", "intro", "purpose", "question"])

    def test_asked_the_purpose_then_call_once_more(self):
        # 目的の人ではない方が用件を聞いてきたら、用件の一文を流してから、もう一度だけ呼ぶ一言（2回目からは呼ばない）
        f, b = self.flow()
        r = self.say(f, "どういったご用件でしょうか？", "replay_opening", part="purpose")
        self.assertEqual([p["part"] for p in r["play"]], ["purpose", "target"])
        r = self.say(f, "えっと、どちら様でしたっけ？", "replay_opening", part="intro")
        self.assertEqual([p["part"] for p in r["play"]], ["intro"])
        self.assertEqual(f.phase, "calling")
        r = self.say(f, "はい、私が岡田です。", "report_party", party="target")      # 用件はもう届いている ⇒ 最初の質問だけ
        self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["question"])

    def test_purpose_is_not_volunteered_to_reception(self):
        # 名乗りを聞き返されたときは、名乗りと呼ぶ一言だけ（用件は聞かれたときだけ。届いていない用件を足すのは、質問へ進む前＝繋がってから）
        f, b = self.flow()
        r = self.say(f, "どちら様ですか？", "replay_opening", part="intro")
        self.assertEqual([p["part"] for p in r["play"]], ["intro", "target"])

    def test_after_connecting_the_callee_is_not_reception(self):
        # ⛔ CL-2 の 4-182 の (4)：繋いだあとに、ご本人から「あとでかけて」と言われる・急いでいると言われると、受付の方に伺っている扱い
        #    （asking_reception）になり、ご本人の「少々お待ちください」で取り次ぎの印（callback_held）が付き、そのあと出た方をお呼びした方かを
        #    確かめる道（_target_back＝呼んでいる段へ戻る）に入りえた ⇒ 受付の方に伺っている扱いは、繋ぐ前だけ
        from flowctl import HOLD
        f, b = self.flow()
        self.say(f, "あいにく岡田は席を外しております。", "request_callback", why="absent")
        self.assertTrue(f.asking_reception)                                           # 繋ぐ前の受付の方：そのまま
        g, b = self.flow()
        self.say(g, "はい、私が岡田です。", "report_party", party="target")
        self.say(g, "あ、すみません、いま手が離せないので、あとでかけてもらえますか。", "request_callback", why="later")
        self.assertFalse(g.asking_reception)
        g.on_callee(); g.on_heard("ちょっと待ってくださいね、予定を見ますので。"); g.on_check("judge", HOLD)
        g.apply("replay_opening", {"part": "handover"})
        self.assertEqual((g.callback_held, g.phase, "target_back" in g.facts), (False, "asking", False))

    def test_split_hold_reading_waits_wherever_the_report_comes(self):
        # ⛔ 2026-11-06 日本時間7時台（5時56分55秒のご質問の読み直し EN-A の指摘2の続き）：かけ直しの質問の途中の受付の方・繋いだあとの方の
        #    「少々お待ちください」を、判定が「取り次ぎを待つ」と「決められない」に割れて読み、会話AIが目的の人・代わった方と報告すると、判定が
        #    そろったときだけ待つ決まり（meaning_said）で、待たずに目的の人かを確かめた・名乗りを流し直した。報告の無いターン・答えの報告は、
        #    どれか1つでも「取り次ぎを待つ」なら待つ（wait_reading の1か所）＝報告の種類で道が割れていた ⇒ 同じ1か所で決める
        #    （✅ 本書 9-4 の (6)「読みのどれか1つでも「取り次ぎを待つ」なら黙って待つ」・2026-11-06 2時28分41秒「「はい、」のような相づちがないと失礼です。」）
        from flowctl import HOLD, UNDECIDED
        for op, kw in (("report_party", {"party": "target"}), ("replay_opening", {"part": "handover"})):
            f, b = self.flow()
            self.say(f, "あいにく岡田は席を外しております。", "request_callback", why="absent")
            self.assertTrue(f.asking_reception, op)
            f.use_checks("judge", "judge2")
            f.on_callee(); f.on_heard("あ、ただいま戻りましたので少々お待ちください。")
            f.on_check("judge", HOLD); f.on_check("judge2", UNDECIDED)
            r = f.apply(op, kw)
            self.assertEqual((r["result"], r.get("ack"), f.holding, "target_back" in f.facts), ("hold", "hai", True, False), op)
        f, b = self.flow()
        self.say(f, "はい、私が岡田です。", "report_party", party="target")
        f.use_checks("judge", "judge2")
        f.on_callee(); f.on_heard("少々お待ちください。")
        f.on_check("judge", HOLD); f.on_check("judge2", UNDECIDED)
        r = f.apply("replay_opening", {"part": "handover"})
        self.assertEqual((r["result"], r.get("ack"), f.holding), ("hold", "hai", True))

    def test_target_again_before_any_answer_is_a_new_person(self):
        # 繋いだあと、何も答えないうちに、また目的の人が出た：代わった方への流し直し（あいさつ・名乗り・用件・いまの質問）
        f, b = self.flow()
        self.say(f, "岡田ですね。", "report_party", party="target")                 # 受付の方を目的の人と報告してしまった
        r = self.say(f, "お電話代わりました。岡田です。", "report_party", party="target")
        self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["greeting", "intro", "purpose", "question"])
        self.say(f, "はい、予約しています。", "record_answer", question_id="Q1", condition_id="はい", value="予約しています")
        r = self.say(f, "岡田は私です。", "report_party", party="target")             # 答えたあとは同じ方
        self.assertEqual(r["result"], "noted")

    def test_unnamed_new_person_is_asked_once(self):
        # 代わった方が名乗らなかった：「「おかだ」様でいらっしゃいますでしょうか？」と1回だけ聞く。認めたら、全部流して質問へ。
        # 録音で流す通話では録音（呼ぶ一言と同じ。⛔ 2026-10-19 G-62：AIに言わせると名前を言い崩した）。AIが話す通話では、同じ文をAIが言う
        from flowctl import HANDOVER
        g, _ = self.flow(recorded=False)
        g.use_checks("judge")
        self.heard(g, "はい、お電話代わりました。", HANDOVER)
        r = g.apply("report_party", {"party": "target"})
        self.assertEqual((r["result"], r["say"]), ("confirm_target", "「おかだ」様でいらっしゃいますでしょうか？"))
        self.assertNotIn("play", r)
        f, b = self.flow()
        r = self.say(f, "はい、お電話代わりました。", "replay_opening", part="handover")
        self.assertEqual((r["result"], [(p["part"], p["text"]) for p in r["play"]]),
                         ("confirm_target", [("target_confirm", "「おかだ」様でいらっしゃいますでしょうか？")]))
        self.assertNotIn("say", r)
        self.assertIn("何も言わずに", r["message"])
        # 確かめへの返事を、最初の質問の答えとして報告されたら：確かめへの返事を待っていることを伝えて差し戻す
        # ⛔ 2026-10-19 G-57（目的の人_本人）：差し戻しが「お取り次ぎいただくのを待っています」のままで、AIは答えの報告を続けた
        r = self.say(f, "はい、そうです。", "record_answer", question_id="Q1", condition_id="はい", value="はい")
        self.assertEqual(r["result"], "rejected")
        self.assertIn("電話に出た方への「「おかだ」様でいらっしゃいますでしょうか？」のお返事を待っています", r["message"])
        self.assertIn("record_answer で報告したりしません", r["message"])
        self.assertNotIn("まだ受け付けていません", r["message"])   # AIは「目的の人」と報告していない（代わった方として流し直しを頼んだ）
        r = f.apply("report_party", {"party": "target"})
        self.assertEqual([p.get("part", p["kind"]) for p in r["play"]], ["greeting", "intro", "purpose", "question"])

    def test_absent_target_goes_to_callback(self):
        from phrases import CALLBACK_ASK
        f, b = self.flow()
        r = self.say(f, "あいにく岡田は席を外しております。", "request_callback", why="absent")
        self.assertEqual((r["question_id"], r["question"], f.phase), ("C1", CALLBACK_ASK["back_time"], "asking"))

    def test_every_away_reason_asks_when_they_are_available(self):
        # ✅ 2026-11-04 日本時間3時15分 ユーザー：「通常は、いない場合、終えるではなく、いつ戻られるのかを確認するのがセオリーですよ！」・同じ夜
        # 「「いつならいらっしゃるのかを確認する」のがセオリーの方が正しい言い方ですね」⇒ お呼びした方の事情でいまお話しできない理由（AWAY_WHYS）の
        # どれでも、終えずに、まず「いつなら」を伺う（理由ごとの言い方は CALLBACK_PLAN の1か所：席を外している＝何時ごろお戻り・お休み＝次のご出社・
        # 出張など＝いつごろお戻りのご予定・ご事情＝いつごろでしたらお取り次ぎ）。戻る時刻が分からなければ「本日お戻りのご予定」→「後ほど改めてお掛け
        # しても」（10-22・10-24）。理由を足したときに、伺う一言の無い理由が入ると、ここで落ちる
        from flowctl import AWAY_WHYS, CALLBACK_IDS, CALLBACK_PLAN, ROLE_KEY
        from phrases import CALLBACK_ASK
        for why in AWAY_WHYS:
            self.assertEqual(ROLE_KEY[CALLBACK_PLAN[why][0]], "time", why)
        for why, said in (("absent", "あいにく岡田は席を外しております。"), ("day_off", "本日、岡田はお休みをいただいております。"),
                          ("long_absent", "岡田は今週いっぱい出張に出ております。")):
            f, b = self.flow()
            r = self.say(f, said, "request_callback", why=why)
            self.assertEqual((r["result"], r["question_id"], r["question"]), ("next", CALLBACK_IDS["time"], CALLBACK_ASK[CALLBACK_PLAN[why][0]]), why)
        f, b = self.flow()
        self.say(f, "あいにく岡田は席を外しております。", "request_callback", why="absent")
        r = self.say(f, "ちょっと分からないですね。", "record_answer", question_id="C1", condition_id="unknown")
        self.assertEqual((r["question_id"], r["question"]), (CALLBACK_IDS["back_today"], CALLBACK_ASK["back_today"]))
        r = self.say(f, "はい、本日は戻ります。", "record_answer", question_id="C6", condition_id="はい")
        self.assertEqual((r["question_id"], r["question"]), (CALLBACK_IDS["again"], CALLBACK_ASK["call_again"]))
        self.assertNotEqual(r["result"], "end")

